with nuevas(numero,viejo,sec) as (values
(65,'4390bd10033b7b9b92ee0610fa1814fd',$q$[{"titulo": "Idea central", "texto": "Ìdí Ìrosùn advierte de una enfermedad en la cintura o en las nalgas, y de molestias en la menstruación y en las vías urinarias. También anuncia que los negocios crecerán dando a conocer el nombre, la marca y los productos. Las fortunas del comercio, la pareja, los hijos, la casa y el dinero vendrán al encuentro de la persona."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene molestias en la cintura, las nalgas, las vías urinarias o la menstruación y conviene revisarlo con un médico (relato de Àgbà-Kuomi).", "Quiere dar a conocer su trabajo, sus productos o su nombre y el reconocimiento no llega (relato de Ọ̀rúnmìlà y el loro).", "Busca prosperar en el comercio, la familia, la casa y el dinero."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fama y popularidad para el trabajo y los productos.", "Fortunas del comercio, de pareja, hijos y casa.", "Curarse de una enfermedad rara.", "Escapar cuando los demás caen."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedad de la cintura, las nalgas, las vías urinarias o la menstruación; conviene ir al médico.", "No contribuir a la ofrenda común y quedar expuesto."]}, {"titulo": "Enseñanza principal", "texto": "El loro se conoce por sus plumas rojas: el trabajo se conoce por su señal. Y en la ofrenda del grupo, quien se niega a poner su parte queda sin protección cuando llega la guerra."}, {"titulo": "Relatos reunidos", "puntos": ["Àgbà-Kuomi y la enfermedad rara. Ifá consultó para Àgbà-Kuomi, que tenía una enfermedad rara bajo las nalgas. Le marcaron nueve babosas, 8,000 cauríes y medicina de Ifá para curarse. Cumplió.", "El òsùn de Ọ̀rúnmìlà. Osu-gagara, el adivino de Atande, consultó para Ọ̀rúnmìlà y le dijo que el òsùn lo haría conocido en el mundo: 'Por las plumas rojas de la cola conocemos al loro'. Le marcaron una gallina, aceite de palma, una rata, un pescado, 20,000 cauríes y un òsùn, el bastón oficial de Ifá. Plantaron el òsùn frente a la casa de Ọ̀rúnmìlà, enterraron lo demás a su pie y le vertieron el aceite de palma encima.", "La riqueza del comercio llega a mirarse. Ifá consultó para Ọ̀rúnmìlà, que pedía la bendición del comercio. Ofreció, y la fortuna del comercio, de la pareja, de los hijos, de la casa y de todo lo bueno vino a mirarse en él.", "El sapo y las ranas. Ifá consultó para la familia de las ranas, que viven en estanques y ríos, y para la familia de los sapos, y les pidió ofrecer contra sus enemigos. La rana Kinkin dijo que debían contribuir; la rana Òsààrà dijo que pondría su parte igual que los demás; el sapo dijo 'está bien', y eso dice hasta hoy. Pero Kòǹkò, el jefe de las ranas, dijo que ni él ni su grupo pagarían. El sapo ofreció y le prepararon medicina de Ifá. Poco después llegaron los hombres a cazarlos a todos. Atraparon al sapo, pero él soltó un líquido blanco y lo soltaron con asco. A las ranas les quebraron las piernas. Solo el sapo escapó."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Àgbà-Kuomi: nueve babosas, 8,000 cauríes y medicina de Ifá.", "Ọ̀rúnmìlà: una gallina, aceite de palma, una rata, un pescado, 20,000 cauríes y un òsùn plantado frente a la casa.", "Comercio: ofrenda a Odù con babosas.", "El sapo: su parte de la ofrenda común contra los enemigos."]}, {"titulo": "Relaciones espirituales", "texto": "El òsùn, bastón de Ifá, da a conocer a Ọ̀rúnmìlà. Ifá protege a quien contribuye."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Òsùn (bastón de Ifá), aceite de palma, babosas, plumas rojas de loro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 65.1 (yorùbá): O nta mi, / Ìdí-àgbà ko jẹki àgbà (joko) simi\": / a daa fÀgbà-Kuọmi / ti Àrùn kan nṣe nisalẹ Ìdí. / Wọ̀n niki o ṣẹbọ, / kiowa gba ewé Ifá, a sàn. / Igbín mésàn, egbàá mẹ̀sàn owó / ati ewé Ifá. / Ó gbó ó rú. / \"Me pica, me duele, / las nalgas viejas del anciano / no le permiten descansar bien / cuando se sienta\"", "Verso 65.2 (yorùbá): Ilé Awo re, / Odede Awo re, / Osù-gagara Awo Atande: / a difá f'Ọ̀rúnmìlà. / A niki Ọ̀rúnmìlà rúbo, / Osù li o maa jẹki ayé mo ẹ, / Iko-Ìdí Oodẹ niijẹki a mọ Oodẹ. / Adiyẹ, epo, eku, eja, / egbaáwa owó, / Osù ati bẹẹbẹẹ, li ebọ. / O rúbọ. / Wọ̀n ri Osù s'ode Ọ̀rúnmìlà, / wọ̀n ko ohun-ẹbọ ti a wi fiṣe etutu / sidi Osù s'ode Ọ̀rúnmìlà, / nigbati wọn ti tu epo sii (Osù) l'ara. / \"Esta es la casa del Babaláwo\" / \"Este es el terreno del Babaláwo\".", "REZO: CHANLA AWO ABA EGA LLELLU ABORE ADIFAFUN ABOCO TINCHERA EYELE CANOCAMBE LOGUN.", "REZO: ODI ROSO EYO ROSO IDIN AWO ADIFAFUN INU CHANLA OWO ABA EGO YEIYU AWO OBERE ADIFAFUN ABOCO CHINCHESE EYELE ECAMBRE LEGUN.", "REZO: IDIN IROGUN IDIN AWO OYAFUN IMU IMU LORIBO AIKORDIE EYELE.", "REZO: ODI ROSO EYO ROSO AWO ONI BABALAWO ADIE FUN FUN INU ONSI OLUGBO.", "REZO: ADIFAFUN OYIGAN LO OGUN AYANAKU TENI TENI KARENTE AWABANI IYU AWAYA AKE IGUI NI ODAN ENINI FAKE KANORI OMO ERIN BERE IGBA OMO NIGBETI AKOKE BIRU KEKEREKE KUARANLE OSHUN OKORO AROYUDE GANGAN TIAGAN AWO DONA BI EGGUN OFERI OLUWO OGUN ALAGUANA OFITI EYIGBONA EGGUN YA SHUGUDU OKUA IYEBU LASHE LENU INLE ILE ALAGUANA, ALAGUANA INLE SHAKUANA LODAFUN AZOJUANO, ADIFAFUN ALAGUANA ASHEGUN OBA.", "REZO: OBA IYAWA INLE OMERE OBIRIN ASI OSAWAO NILE SHANGO EKO OBA OIKALE OSIWERE OBA INKA ARAYE IADULA OSHESHE OSODE ILE ORUNMILA ADIFAFUN OMOBIRIN OBA KAFEREFUN EBBO, KAFEREFUN OZAIN, KAFEREFUN ABATA.", "REZO: AWE WEWE ADIFAFUN OLOGBO ADIFAFUN ONA ODOFO EKUTE AYAYU KORO ADAFE AYA EYELE LEBO EWEFA.", "REZO: ODI ROSO PUPA RUSUROSO ODI OASUN ODI OWO, ODI ORO ONITI KOSUN NIMOBILO GBOMO IWOWO TINIO SINU OGAN WONIKI FIYE ILE MEYI, AKUKO MEYI ATI OGBOJILOGUN OWO, AJUBO AWONA YOINMU AKUKO KAFUN ONITI RUBO NANU AWOJUNTI AYA WOYI POKO OLOFIN BORIRE IWOWO ANONI,ANONI SIBERE SIWIPO ORI IWOWO LA ONA FUN, INTORI NI ORUBO. IFA NORI ONITI ADIFA YIYIO LONA FUN BIOBARUBO.", "SUYERE: ERU SELEDAMI SORO BIOYE IFA OLODUMARE ORI SELEDAMI.", "REZO: OTA AWE AWE IGUI AWO BAYORUN BOGBO KOYOSO AWO NAYA KIDIOSUN IKOKO KOBEROFO OZAIN MOWAYE BELELE OZAIN. REZO: EYO KILE AYI ORI OMORISHA LODA, ODI ORO ARUMA ORUGBO AGADA ADAFA ELEKENI KOSHE ORIRE MARIWO EWE PE,", "IKODIE IDE AYANAKU EYA OWO ABEJE BORI KAFERE FUN ORUNMILA KAFEREFUN LOWE.", "SUYERE: ADE LOWO, ADE NI ORISHA, ADE NI OBA.", "REZO: ADIFAFUN ODI ERUN ODIROYO EYU OPON OBIRIN PAWESHACA ODASILE KOSILE AGBONA PARADO LODO ONILE FUN FUNI LAYE ADIE SHICU ARU ADIE OKAN LULU OKAN ADODI OMO KUNI LODAFUN OZAIN, KAFEREFUN ORUN."]}]$q$::jsonb),
(66,'f258d91fce4c118d190864c6ca2fe3ea',$q$[{"titulo": "Idea central", "texto": "Ìdí Ọ̀wọ́nrín anuncia un reconocimiento cercano y un éxito importante en el trabajo o en la carrera. La persona siente presión laboral. No probará la muerte antes de tiempo: Ifá ata a la muerte. Los enemigos mandan males por detrás, y ahora preparan un ataque de frente: hay que ofrecer en la puerta delantera y en la trasera."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene presión en el trabajo y espera que valoren su esfuerzo o su habilidad (relato de la tortuga).", "Quiere mantenerse firme y resistir (relato de la palmera).", "Siente amenazas de adversarios o de pérdida y debe tomar precauciones (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Reconocimiento y elogios donde quiera que trabaje.", "Firmeza y larga vida, como la palma.", "Atar a la muerte en el patio de la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Presión en el trabajo.", "Ataques de los enemigos por detrás y de frente."]}, {"titulo": "Enseñanza principal", "texto": "El que ofrece puede reírse de la muerte: Ọ̀rúnmìlà la ató con una soga de nudos en el patio, y los que se burlaban murieron riéndose."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga que se volvió gran jugadora. Ìdíwọ̀nrinwọ̀n consultó para la tortuga (Ọbahun Ìjàpá) y le aconsejó ofrecer para que la elogiaran en todas partes donde jugara. Le marcaron cuatro cuentas de coral, cuatro palomas y 8,000 cauríes. Ofreció y se convirtió en una gran jugadora: las cuentas de coral le dieron honor en su desempeño.", "La palma firme en la tierra. Emikomaakú-Yiyeninmaayé consultó para la palma (Ọ̀pẹ) y le aconsejó ofrecer para estar firme sobre la tierra y no morir: una carnera, una campana, 44,000 cauríes y medicina de Ifá. Ofreció, quedó bien plantada y tiene larga vida. Se lavan los ikin con hojas de kúti, se pone la campana encima y se canta sonándola: 'Avergoncé a la muerte; en vez de morir, me volví hojas de kúti'.", "Ọ̀rúnmìlà ata a la muerte. 'Ìdin, ¿de qué te ríes? Se ríen y se ríen y mueren del todo.' Así consultaron para Ọ̀rúnmìlà, que iba a atar a la muerte en el patio de atrás. Le marcaron una soga con nudos y ofreció. Cuando llegaron sus enemigos supieron que ya había ofrecido y se dijeron que ya no podrían hacerle daño. Cantó: 'Tenemos atada a la muerte; ya no moriremos con ellos'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La tortuga: cuatro cuentas de coral, cuatro palomas y 8,000 cauríes.", "La palma: una carnera, una campana, 44,000 cauríes; lavar los ikin con hojas de kúti y poner la campana encima.", "Ọ̀rúnmìlà: una soga con nudos.", "Ofrenda en la puerta delantera y en la trasera."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá ata a la muerte para quien ofrece. Los ikin se lavan con hojas para la larga vida."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de kúti, campana, cuentas de coral, soga con nudos."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 66.1 (yorùbá): İdiwónrinwọ̀n-Idiwọ̀nrínwọ̀n / li o dífá f'Obahun-ljapá, / wọ̀n niki o wa rúbọ / kiole maa gba iyin / nibi ere nigbogbo agbayé. / Ẹbọ: lyun mẹrin, / eyẹlé merin ati ẹgbàárín owó. / Ó gbọ̀ ó rú. / Ọbahun d'osere pàtàki, / o tifi iyun rúbo ere.", "Verso 66.2 (yorùbá): Emikomaakú-Yiyeninmaaye: / li o difá fOpẹ, / wọ̀n niki Ọpẹ̀ wa rúbọ / kiobaa lefi Ìdí mu'lẹ kiomaa baa kú: / Àgutăn, agogo, / egbàá méjilelógún owó ati ewé Ifá. / Ó gbọ̀ ó ru. / Wọ̀n ni: / Opẹ a tirin mu'lẹ, / Ọ̀pẹ a ye.", "REZO: ODI OMONI AWO FASHE IKU. IKU OMO SAREBAKU FASHE IKU AWOOMO IKU ABERERE NILAYE INLE AWO FASHE IKU OMO YEKU OBA NI SHANGO.", "REZO: KUKUTE KUKU ADIFAFUN METETA OMA IKOFA ORUNMILA ISHU LEBO ASHO FUN FUN EYELE LEBO 4 EYELE Y ISHU. ORUMILA ADIFAYOKO LODAFUN OLOFIN.", "REZO: KUKUTE KUKU ADIFAFUN METETA OMA IKOFA ORUNMILA ISHU KUKURA ORUNMILA ADIFAYOKO LODAFUN OLOFIN.", "REZO: ORI OSHAWO OBADA ORUN OSHAWO OBA EYIBA ODI OSHAWO ODA AYAMANARA BARA EYELE.", "REZO PARA OPARALDO: IDIN NAYEKUN OLORUN IWALODEO OYA KALORUN OJUANI ISO ORO.", "SUYERE PARA OPRALDO: SARAYEYE IKU OLORUN SARAYEYE EGGUN IKU OLORUN ADIE SARAYEYE EGGUN IKU OLORUN."]}]$q$::jsonb),
(67,'176ee05574133349c3175283c02fd45e',$q$[{"titulo": "Idea central", "texto": "Ìdí Ọ̀bàrà habla de quitar obstáculos, dificultades y malentendidos por medio de la ofrenda. La persona tiene problemas con su pareja o con la familia de su pareja, y el compromiso es necesario para salir de ellos. Hay un viaje que no debe dudar en hacer: mucha fortuna lo espera allá."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene tensiones con su pareja o con la familia de ella; las evasivas y el desprecio empeoran el pleito (relato de Èdí y Ọ̀bàrà).", "Piensa viajar y duda si en el nuevo lugar le irá bien (relato de Ọ̀rúnmìlà y el viaje a Èňpe).", "Su proyecto está rodeado de obstáculos que debe despejar antes de esperar resultados (relato de la palma y la maleza)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que el monte que lo rodea sea limpiado y lo dejen crecer.", "Fortuna en un viaje a otra ciudad.", "No regresar con las manos vacías."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desprecio en la pareja.", "Discutir en el lugar al que se llega.", "Dudar de lo que Ifá dice."]}, {"titulo": "Enseñanza principal", "texto": "El que llega a una tierra nueva no discute: escucha y da la razón. Así le fue bien a Ọ̀rúnmìlà en Ẹ̀ǹpẹ. Y a quien ofrece, Èṣù le manda quien le limpie el camino."}, {"titulo": "Relatos reunidos", "puntos": ["La palma entre la maleza. Ifá consultó para un árbol rodeado de maleza espinosa y para la palma (Ọ̀pẹ), y les pidió ofrecer un machete, un hacha, la soga de subir palmas, una rata, un pescado, una paloma y 18,000 cauríes para quitar las dificultades de su camino. El árbol se negó y la palma cumplió. Le dijeron que la maleza no la mataría. Un día Èṣù le dijo al granjero que limpiara alrededor de la palma porque desde ahora iba a ser útil para la hacienda. El granjero la limpió, y la palma se llenó de cosas buenas para la granja y la gente.", "Èdí y Ọ̀bàrà. Èdí, el adivino del campo, y Ọ̀bàrà, la adivina de la casa, recibieron Ifá para no pelear para siempre. Les marcaron un gallo y una gallina, un chivo, una chiva y 20,000 cauríes. Ọ̀bàrà ofreció y Èdí no. Èdí iba a saludar a Ọlọ́fin después de trabajar en la granja, y le dijeron que tomara a Ọ̀bàrà por esposa. Pero ella lo despreciaba y le decía 'campesino': '¿Qué voy a hacer yo con un campesino?'. Èdí le rogó mucho tiempo, hasta que fue a hacer la ofrenda que le habían pedido, porque sin ella nunca se casaría.", "Ọ̀rúnmìlà en Ẹ̀ǹpẹ. Ifá consultó para Ọ̀rúnmìlà cuando iba a ejercer la adivinación en la ciudad de Ẹ̀ǹpẹ y preguntaba si le iría bien. Le dijeron que ofreciera, que no dudara de sí mismo ni de Ifá, y que no discutiera con nadie: si allá decían 'esto es así', debía estar de acuerdo. Al llegar, la riqueza del comercio y todo lo bueno le sonrió.", "El halcón y el águila. Ifá consultó para el halcón y para el águila, que defendían su comida y pedían que sus presas no se les escaparan. Les dijeron que ofrecieran por igual. Ofrecieron en cientos, y al salir a cazar el halcón vio su presa y la atrapó, y el águila también. 'El halcón no se lanza sin atrapar, ni el águila falla cuando cae en picada.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La palma: un machete, un hacha, la soga de subir palmas, una rata, un pescado, una paloma y 18,000 cauríes.", "Èdí y Ọ̀bàrà: un gallo y una gallina, un chivo, una chiva y 20,000 cauríes.", "Ọ̀rúnmìlà en Ẹ̀ǹpẹ: ofrenda antes del viaje.", "El halcón y el águila: ofrenda en cientos."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù apoya a quien ofrece y le manda ayuda. Ọlọ́fin dispone el matrimonio de Èdí y Ọ̀bàrà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Machete, hacha, soga de palma, palma de aceite."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 67.1 (yorùbá): Edidi-ndi-won-lowọ, / Ọ̀bàrà-nbo-wọn-mo'lẹ̀; / a difá fún igi inu ẹti, / wọ̀n niki o wa rubo / ki-ẹti-le tan liọrun rẹ̀. / A difá fOpè / wọn niki Ọpẹ̀ wa rúbọ: / Àdá, Aake, Igbà (tiafi ngun pẹ̀), / eku-ẹmọ, eja-aro, eyẹlé ati ẹgbàásan owó. / Igi elẹti ko rúbọ, / Ọpẹ li o rúbo. / Wọ̀n ṣ'ewé Ifá f'Opè. / Wọ̀n ni: / Pà-nti kiip'Ọpè. / Eniti o rúbọ ni Èṣú ngbe. / Ọ̀pè yoo maa fún'ni ni ohun rere / gẹgebi Ọpẹ̀ tinfun òun / Èṣú paapaa ni ohun rere. / O niki Agbẹ̀ fi àwọn ohun ọwọ rẹ̀ / tun Ọpẹ̀ ṣe na. / Àgbẹ̀ gba imoràn naa. / Ayanii: Àgbẹ̀ ntun Ọ̀pẹ̀ ṣe, / Ọ̀pè nfún ni ni ohun rere. / Edidi está bloqueado (obstaculizando) a todos, / Ọ̀bàrà está yendo a cubrirlos,", "Verso 67.2 (yorùbá): Edí awo-oko, / Ọ̀bàrà awo-ilé, / a dífá a niki àwọn mejeji / wa rúbọ kiwọn ma jà titi ayé. / Ẹbọ: Adiyẹ Méjì tobitaką, / òbúko, ewúrẹ ati ẹgbàáwa owó. / Ọ̀bàrà rú, / Èdí ko rú bẹẹni Èdí, / biobati oko de a maa lọ / ki wọn ni'le anarẹ, nile Ọlófin. / • pẹ o, wọn ni Ọ̀bàrà aya rẹ toogbe, / Òun Ọ̀bàrà tiiṣe aya rẹ / ko fẹran Edi tiiṣe pkọ rẹ, / nitorinaa òun a maa ṣẹ gan rẹ pe, / ara oko ni. / Kini oun maa fi ara oko ṣe? / Nigboose Èdí wa nbẹ Ọ̀bàrà. / Ọ̀bàrà ko fẹ rara rara. / O pẹ titi, / Èdí wa lo rúbọ tioti kosilẹ. / Ọ̀bàrà iba kọọ dandan / bikoṣepe o lọ rúbọ.", "REZO: ADIFAFUN EKUEKUEYE OSHA ODARA WAYE ADAFUN ADIE ORUBO. ADIE OKANI ODARA.", "REZO: ODI BARA INDI BARALAGUE TINCHOMO ON ERIOLOGUN ADIFAFUN AGURO UM V ATI OTE ORONIFA ENI LOFE ENICAN LOFECHO OLESI OBINIO SAFUO EPO ORI OCHE EYELE ACHE AIKORDIE EWE PAPA SAN EKU EYA OWO BOTE BERU.", "REZO: LO AWO TINCHOMO ORIELOGUN ADIFAFUN EBUENO OMODE FOGUONOFA OBEDESES PUABARA OBALLU GADABA ONI BABALAWO LODIFAFUN ORUMBE TIATE BOBO NIQUI MIFA.", "REZO: IDO BARA OBARA QUETIEONCHO ORIE LOGUN ADIFAFUN EBURE EYELE LEBO OÑI ADIE MEGUA ATA EPO ORI OWO LA MENI.", "REZO: ODI BARA BARA KOTI KONSHO ORIE LOGUN ADIFAFUN ABURE ODI ADIFA OSO KUMBA UNSHO MOBA YODE YESA", "REZO: ADIFAFUN ABURE MATA OMO OBATALA OMO KEKE AUYE ELOSHE OMO LERIN OBATALA PEKUN LAYE OMO OLOKUN, LODAFUN OBATALA.", "REZO: ADIFAFUN KUEKUEYE OSHA ODARA WAYA ADAFUN ADE OFUBE ADIE OKAN ODARA.", "REZO: ADIFAFUN OMO LADE OBATALA IKU IWEREYEYE IBORI BABA OBATALA AGBEGUNOTA FICHARO EWE, LODAFUN OBATALA, KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN IWORIYEYE OMO OZAIN EYU OLOGBO EWE ODARA EGGUN IÑA SHANGO LONGO ASHERE EYO OGUN, LODAFUN SHANGO.", "REZO: TINSHOMO AWO ALAFIA AFEFE IKU MASUO INTORI OLORUN ADIFAFUN ABURE LEBO."]}]$q$::jsonb),
(68,'6867c0370d670b765b6e76a66b1179d4',$q$[{"titulo": "Idea central", "texto": "Ìdí Ọ̀kànràn advierte que quien actúa con deshonestidad será atrapado y castigado. La traición de alguien de confianza puede traer problemas. Trae muchas cosas buenas, pero exige mucha paciencia; puede haber una herencia o un botín en un lugar lejano, y no hay que ser rencoroso al repartirlo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme una traición de alguien en quien confía.", "Está ante una tentación deshonesta o cerca de gente que quiere robar (relato de los ladrones en la granja).", "Un viaje largo puede traer herencia o fortuna, con paciencia y atención (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Heredar bienes por haber cuidado a quien todos despreciaban.", "Riqueza que llega libremente."]}, {"titulo": "Ibi y advertencias", "puntos": ["Robar: la tierra arresta al ladrón y la vergüenza lo atrapa.", "Traición de alguien de confianza.", "El orgullo que lleva a hundirse, como el cono que bailó en la playa."]}, {"titulo": "Enseñanza principal", "texto": "La compasión se paga. Ọ̀rúnmìlà cuidó al hombre rico que todos abandonaron por su enfermedad, y heredó todo lo suyo. Y quien no hace caso del aviso, como el cono que bailó hasta el mar, se pierde por su propio peso."}, {"titulo": "Relatos reunidos", "puntos": ["Los dos ladrones amarrados como ñames. Ìdíkọ̀nràndíkọ̀nràn, el que amarra los ñames, consultó para dos ladrones que iban a robar una granja, y les aconsejó ofrecer para no terminar amarrados con una soga gruesa, como se amarran los ñames al sacarlos de la tierra: 'La tierra arresta al ladrón en nombre del dueño; la vergüenza agarra al que roba'. Les marcaron cuatro babosas, 3,200 cauríes y medicina de Ifá. Se negaron, fueron a la granja y los atraparon y ataron con una soga fuerte.", "Ọ̀rúnmìlà y el hombre rico enfermo. Ifá consultó para Ọ̀rúnmìlà, que iba a una ciudad lejana, y le pidió ofrecer. Al llegar encontró que el jefe, un hombre muy rico, tenía lepra y todos huían de él. Ọ̀rúnmìlà pensó que era un ser humano creado por Dios, entró en su casa, lo acompañó y le preparó medicinas mientras los demás lo despreciaban. Cuando el hombre sintió que iba a morir, le pidió que se encargara de su entierro, le dio un azadón y un machete para abrir la fosa y le dijo que con ellos también sacara todas sus riquezas, que serían suyas por haberlo cuidado, y que no le diera nada a quienes lo despreciaron. Ọ̀rúnmìlà se hizo riquísimo. Canto: 'Ifá no era de su familia, y heredó libremente sus bienes'.", "El cono que bailó en la playa. Ifá consultó para el cono de metal, que iba a bailar a la playa, y le dijo que ofreciera y que ahí no bailara, que solo mirara mientras los demás bailaban. Su orgullo no lo dejó escuchar. El baile iba de la arena hasta el agua; el cono bailó y bailó sin darse cuenta de que había entrado al mar, y se hundió por su propio peso."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Los ladrones (rechazado): cuatro babosas, 3,200 cauríes y medicina de Ifá; baño de ẹ̀sọ̀ y ojúùsájú, y sopa de babosa con ẹ̀sọ̀.", "Ọ̀rúnmìlà: ofrenda antes del viaje.", "El cono (rechazado): ofrenda y no bailar en la playa."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà enseña la compasión con el enfermo. La tierra protege los bienes del dueño."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀sọ̀, ojúùsájú, babosas, azadón, machete."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 68.1 (yorùbá): İdikonràndikònràn, / İdikònràndikonràn-di-iṣu: / li o difa f'Ole Méjì / nlọ oko-awo, / a niki wọ̀n wa rúbọ / kiama baa fikanrinkan iṣu / di wọn bọ lati oko wa silẹ. / llè niiba olohun m'ole, / owo-ẹtẹ ma l'ole o. / Wọ̀n ni: Kil'ebọ? / A ni: İgbin mẹrin, / ẹgbèrindilógún owó ati ewé Ifá. / Wọ̀n kọ wọ̀n ko rú. / A de wọn bọ oko nitootọ. / Wọn nke: / Nbamo maaṣẹbọ İdikònràn-di-iṣu.", "REZO: ODI KANA KAMAYE BI AWO MONORA AWO YABI MADAWA AWO ABITI LAYE OMO MAYAGBA, OMO INLE, IBAI BABA IFA OMO AWO MOSAGBA ABOYE NIFA ODARA.", "REZO: AWO META MEYI CAFENARE OFE SOLOFUN ARUCHAN LA OLO UNGUAO QUI OROMI OMARE EWE TINCHIRE MOFILE UON LOSOCO OOTOLO SECO ORUBO ONI MOCHE UNKANFUN.", "REZO: ODI CABA OCHE LADIALO UN ORUMILA UMBA ODELE IBICAMBO ORUBO LEBE ADIE OWUNKO LEBO.", "REZO: AWO META MEYI KAGENARE AFE SALGUN ORISHANLA OLO UNGUEO QUI OROMI ONARE EKE TONEBIRE MOFILE OUNLA SECO KOLOLO ORUBO MOFILE TINIBO MOSHE UNKANFUN.", "REZO: IDI CANOSHOSHO LADIELO ADIFAFUN ORUNMILA UMBA ODELE ESHU IBICAMBO ORUBO AKUKO TONEBIRE MOFILE OUN LA SEKO KOLOLO ORUBO MOFILE TINIBO MOSHE UNKANFUN.", "REZO: KANAYE BIAWO MAYORA AWA YABI MORDARA AWO ABITI TI BAYE OMO MOYARE OMO INLE IGBA BABA IFA OMO AWO MOTARA ABEYERENIFE ORDARA OMO ABITI NIYARE OFE OMO OWO ABEYI LOAN ORDI KONAWA KAY HE TONTA ORAN ODI KANA."]}]$q$::jsonb),
(69,'0f1ec6198f182d90316d349acceeb316',$q$[{"titulo": "Idea central", "texto": "Ìdí Ògúndá dice que la sabiduría y el buen carácter deben equilibrar la fuerza física. Advierte que la promiscuidad lleva a la desgracia. Anuncia muchas bendiciones, larga vida y paz mental para quien madruga a trabajar: así se encontrará con lo bueno."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene fuerza y energía, pero debe cuidar sus decisiones y cómo trata a los demás (relato de Ògún y su cabeza).", "Una conducta sexual imprudente puede traerle problemas.", "Sale temprano a trabajar y espera que esa constancia le dé frutos (relato del trabajador del campo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una cabeza tan fuerte como el resto del cuerpo.", "Larga vida y paz mental.", "Recoger el fruto de la constancia, incluso de manos de otros.", "Ser conocido en la sociedad."]}, {"titulo": "Ibi y advertencias", "puntos": ["El mal carácter que deja la casa vacía.", "La promiscuidad.", "Gastar la vida sin disfrutar lo ganado."]}, {"titulo": "Enseñanza principal", "texto": "La fuerza sin carácter deja la casa sola. Ògún tenía un cuerpo fuerte, pero su carácter alejó a todos; tuvo que ofrecer para que su cabeza estuviera a la altura de su cuerpo. Y quien madruga con constancia recoge lo que otros no alcanzan a disfrutar."}, {"titulo": "Relatos reunidos", "puntos": ["La cabeza de Ògún. Ọ̀rúnmìlà dijo: 'Ìdí Ògúndá'. Avisó que Ògún debía ofrecer para que su cabeza estuviera tan fuerte como el resto de su cuerpo: una carnera, una paloma, 44,000 cauríes y medicina de Ifá. Ògún ofreció, y su cabeza quedó fuerte y su cuerpo también.", "La casa vacía de Ògún. Fueron a la casa de Ògún y no encontraron a nadie; la casa estaba abandonada. Dijeron: 'El carácter de Ògún no es bueno'. Querían que su casa se llenara de gente, y le marcaron una chiva, 20,000 cauríes y medicina de Ifá.", "El granjero madrugador y el comerciante. Ifá consultó para el entierro a la orilla del camino y para el hombre que salía temprano a su granja. Un comerciante que había pasado mucho tiempo comerciando en tierras lejanas regresaba con su dinero atado al cuello, y sintió que la muerte lo llamaba. Desesperado, le dio al granjero puntual el dinero que llevaba al cuello y le rogó que cuidara de su cuerpo. El granjero vio la recompensa de su constancia y alabó a sus babaláwo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ògún (cabeza): una carnera, una paloma, 44,000 cauríes y medicina de Ifá.", "Ògún (casa): una chiva, 20,000 cauríes y medicina de Ifá.", "Para ser conocido: palomas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún es el ejemplo de la fuerza que necesita buen carácter. Orí debe estar a la altura del cuerpo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Carnera, chiva, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 69.1 (yorùbá): Ọ̀rúnmìlà I: Ìdí-ògún-dá, / mo ni: Ìdí-ògún-dá. / Ọ̀rúnmìlà I: / bi Ìdí-Ogún ti dára yi kiowa rúbo / ki orí rẹ̀ le dára pẹlu. / Àgùtàn, ẹyẹlé, / ẹgbàá méjielógún owó / ati ewé Ifá / Ôgún gbọ̀ ó rú. / Orí Ògún dára. / Ìdí Ogún dára.", "Verso 69.2 (yorùbá): Ọ̀rúnmìlà I: Ìdí Ôgún dá, / mo ni: Ìdí-ògún-dá. / A de'le Ogún a kob'ẹnikan, / mo ni: / eetiri tiade ilé Ögün tiakob'ẹnikan? / Gbogbo ilè da kesekese, / Wọ̀n ni: / İwà Ogún kò sunwọ̀n, / njẹ biabiwipe / ki ilé Ogún kun ṣomuṣomu, / ebọ ni kiaṣe: / Ewúré, egbàáwá owó / ati ewé Ifá.", "REZO: ODI OGUNDA KINAMU IBU OMU ADIFAFUN AKUE ASHE AKUKO LEBO YAMAGARA ADIFAFUN ALAKU AKUKO IDA, OTI, OWO MESAN ELEBO.", "REZO: OGUNDA OGUNDA PINAMU IBUOMU ADIFAFUN ACUE ECHE AKUKO LEBO LLAMAGARA ADIFAFUN A LACU AKUKO IDA OTI OWO MESAN.", "REZO: BIDAMU IBON ADIFAFUN AWESHE YAGADA ADIFAFUN AKUKO ORI ARUKAN BOKOMO A BADIKU.", "REZO: AWO OMI OYE BARALELE AWO ABITI OBARANILE YEGUE IFA MOTORI LOGE SHANGO OMO MOYARE BINI BEYE KOBU BORO BORELE BEGE AWO ABITI IFA KAFEREFUN AWO, IFA KAFERFUN ESHU GUALA AWO ABITI."]}]$q$::jsonb),
(70,'c79791328ede25bb81c049d2fe6b6887',$q$[{"titulo": "Idea central", "texto": "Ìdí Ọ̀sá habla de intranquilidad y de querer escapar de las responsabilidades. Las presiones diarias causan trastornos emocionales y hace falta la ofrenda correcta para descansar. Pide no despreciar la riqueza que llega y saber qué ofrecer para que no lo ataquen."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está agobiado por los asuntos diarios y no encuentra descanso (relato de Ìdí que no puede sentarse).", "Huye de un cargo o una obligación por miedo a lo que traiga (relato de Ìdí escondiéndose).", "Dos personas ignoran avisos y deben atender un pleito con adversarios."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Descansar y estar en paz.", "Ganar el sustento por obedecer.", "Que nadie pueda vencerlo aunque se junten."]}, {"titulo": "Ibi y advertencias", "puntos": ["Huir de la responsabilidad y quedar en vergüenza.", "Creer que no se tienen enemigos y no protegerse.", "No poder estar quieto."]}, {"titulo": "Enseñanza principal", "texto": "El que huye de la responsabilidad termina en el desprecio. Y el que se cree a salvo por estar bien cubierto, como el maíz, es el primero en caer cuando llegan los que lo buscan."}, {"titulo": "Relatos reunidos", "puntos": ["Las nalgas que no podían sentarse. Las nalgas (Ìdí) corrían a meterse en la casa, corrían a sentarse y no podían; se levantaban y no podían estar quietas. Les aconsejaron ofrecer para descansar: una paloma, 3,200 cauríes y medicina de Ifá, un baño diario de hojas de ẹ̀sọ̀ y jókó-jẹ con jabón negro. Cumplieron.", "Las nalgas que huyeron del cargo. Ọ̀rúnmìlà dijo: 'Ìdí Ọ̀sá, las nalgas están huyendo'. Las nalgas escaparon lejos para que no las hicieran jefe; corrieron a esconderse detrás de la espalda y nadie volvió a verlas. Eso les trajo vergüenza y desprecio. Les marcaron diez hojas de ọ̀wà, diez palomas, diez carneras, 20,000 cauríes y medicina de Ifá. Lo hicieron, y por eso hoy nadie va detrás de ellas.", "El loro y el maíz. Ifá consultó para el loro, que peleaba por su comida, y para el maíz tierno, que iba a tomar tierra en la granja. El maíz creció y se extendió, y le dijeron que ofreciera contra sus enemigos. Respondió con desdén: '¿Cuáles enemigos? Tengo mucha ropa para cubrir a mis hijos'. El loro preguntó qué hacer para tener ganancia; le marcaron hojas bien afiladas y una tela roja. Llegó a la granja con sus cuchillas, vio los granos bajo la cobija del maíz, cortó sus mazorcas y guardó granos para comer. El maíz imploró, pero ya era tarde. La tela roja de la ofrenda, Èṣù se la plantó al loro en el pecho para siempre.", "El tigre y sus garras. Todos los animales se juntaron contra el tigre y lo hicieron su enemigo común. El tigre fue con el adivino y le marcaron veinte hojas afiladas. Ofreció; los babaláwo le dieron diez para su casa y se quedaron diez. Èṣù le metió las veinte hojas en las manos y en las patas, y así nacieron sus garras. Desde entonces nadie lo supera, aunque se junten todos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para descansar: una paloma, 3,200 cauríes y baño diario de ẹ̀sọ̀ y jókó-jẹ con jabón negro.", "Para no huir del cargo: diez hojas de ọ̀wà, diez palomas, diez carneras, 20,000 cauríes y medicina de Ifá.", "El loro: hojas afiladas y una tela roja.", "El tigre: veinte hojas afiladas.", "Dos personas juntas: una tela roja."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù pone la tela roja en el pecho del loro y las garras en el tigre: le da su arma a quien ofrece."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀sọ̀, jókó-jẹ, ọ̀wà, jabón negro, maíz, tela roja, hojas afiladas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 70.1 (yorùbá): İdisáwole, / Ìdí-reejoko, / Ìdí-kolejoko ó tun dide, / Ìdí ko simi. / A niki o wa rúbą / kiobaa le simi: / ẹiyẹlé, ẹgbẹrindilógún owó / ati ewé lfa. / Ó gbọ̀ ó rú.", "Verso 70.2 (yorùbá): Ọ̀rúnmìlà ni: Ìdí-Ọ̀sá!, / mo ni: Ìdí-Ọ̀sá! / Ìdí-Ọ̀sá titi wọn nwa Ìdí kiowa joye. / Ìdí-sare-ẹhin-ẹku; / wọn ko wa ldí mọ. / Ọràn yi di ituju / ờràn naa di egan, / wọ̀n niki ldí wa rúbo / ki àwọn omọ-aràyè / le maa wa a: / Qwa méwà, eiyẹlé méwà, / agutan méwà, egbàáwá owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Nitorinaa ni wọ̀n a maa wa Ìdí titi di òní.", "REZO: ODI SA ODI MAYERE MAÑANA LE YERE IYALEDE MAMA WA AMOIYA WA YERE OMO OSHUNGUERE IYA IEDE BABINU OMO OSHUNGUERO FUMI SHERE.", "REZO: DISA DINEO IDINLOMO AWO ANLO. IDISA DISA ADIFAFUN OLOFIN EYELE LEBO IBIN MAFEREFUN YEMAYA. IDISA ACOTO ISALLA ANDIFALLOCO ANFU OGUORI UN BATI BOBO APELLE. ADAI T EOTO ISALLA ADAFUN AMALE.", "REZO: OLE OKUNI ABOSHU MULEY OSHOYU OMODE ORUNMILA ADIFAFUN OLE LODAFUN IKOFA MAFEREFUN ORUNMILA KAFEREFUN OZAIN.", "SUYERE: OSISE ODISA OÑI MILODI."]}]$q$::jsonb),
(71,'ffceb0b508fe824d0f0327bb6e6fa714',$q$[{"titulo": "Idea central", "texto": "Ìdí Ìká advierte que las malas acciones tienen castigos severos. Hay riesgo de traición o engaño en los negocios o en los secretos personales. Pide ofrecer contra enemigos fuertes con machete, garrote, cuchillo y un palo pesado, y ofrecer por larga vida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que alguien cuente un secreto suyo o lo engañe en un negocio (relato de Olókun y Ọlósa).", "Piensa en vengarse, y el daño a otros se regresa (relato de Abatẹnijẹ).", "Tiene enemigos o busca el lugar adecuado para establecerse (relato de la jícara)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que los secretos no sean revelados.", "Que los enemigos no puedan detener su camino.", "Larga vida."]}, {"titulo": "Ibi y advertencias", "puntos": ["El fin del tiempo de hacer daño: el que pica será atrapado.", "Engaños en los negocios.", "Creerse demasiado grande para ofrecer."]}, {"titulo": "Enseñanza principal", "texto": "La raíz dentro del arroyo nunca detiene el agua. El que hace daño termina atrapado, y el que ofrece sigue su curso aunque lo rodeen."}, {"titulo": "Relatos reunidos", "puntos": ["El fin de Abatẹnijẹ. 'Investigamos a los hechiceros y a todo el que daña a otro: el día que la hormiga brava pica, la atrapan.' Así consultaron para Abatẹnijẹ, y le dijeron que se había terminado su tiempo de hacer el mal. Le marcaron lo que el babaláwo pidiera y medicina de Ifá —un baño de hojas de oriji y ojúùsájú con esponja nueva y jabón negro—, y le advirtieron que soltara la mayor parte de sus bienes como limosna o que se iniciara en Ifá.", "Los secretos de Olókun y Ọlọ́sà. Aṣiribomomo consultó para Olókun y para Ọlọ́sà, y les marcó a cada uno cuatro recipientes de barro, dieciséis palomas, 80,000 cauríes y medicina de Ifá. Cumplieron, y el adivino dijo: 'Nadie ve el fondo del mar ni el de la laguna; los secretos de Olókun y de Ọlọ́sà nunca serán revelados'.", "La jícara y los platos. Ifá consultó para la jícara, que iba a tomar tierra en la granja, y para los platos que se rompen, y les pidió ofrecer un madero grueso, un machete, un cuchillo y un garrote. Los platos ofrecieron. La jícara dijo: '¿Para qué ofrezco si soy grande?'. Creció en la granja, y el hombre llegó y las fue rompiendo una por una para sacarles las semillas y usarlas de recipiente. Pero con los platos se volvió cuidadoso: no los rompe a menos que les llegue su hora.", "Ọ̀rúnmìlà y la raíz en el arroyo. Ifá consultó para Ọ̀rúnmìlà cuando estaba rodeado de enemigos fuertes, y le dijeron: 'La raíz dentro del arroyo nunca detiene el agua; si se te cruzan, su próxima comida será en el cielo'. Ofreció con fe, y cantó: 'Los enemigos que decían que no volvería a casa, los fui encontrando caídos al lado del camino'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Abatẹnijẹ: lo que el babaláwo pida, baño de oriji y ojúùsájú; dar limosna o iniciarse en Ifá.", "Olókun y Ọlọ́sà: cuatro recipientes de barro, dieciséis palomas, 80,000 cauríes y medicina de Ifá.", "Los platos: un madero grueso, un machete, un cuchillo y un garrote.", "Ọ̀rúnmìlà: ofrenda contra los enemigos; ofrenda por larga vida."]}, {"titulo": "Relaciones espirituales", "texto": "Olókun, dueño del mar, y Ọlọ́sà, dueña de la laguna, guardan sus secretos. Ọ̀rúnmìlà vence a los enemigos que se le cruzan."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Oriji, ojúùsájú, jabón negro, esponja, jícara, recipientes de barro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 71.1 (yorùbá): A nwadí Oṣó, / A nwadi Àjé, / A nwadi Asẹni, / ljọ ti Ẹka ṣ'oro (ṣeoro) tiari Ẹka / mu li aipa Ẹka: / a daa fAbatẹnijẹ, / wọ̀n ni: / odún yi ni opin maa de fun / iwà-Ìká Abatẹnijẹ, / Oṣikàpa-adiyẹ-adugbo-run, / At'èniyàn-at'ẹranko-kon'eewọ. / Ẹbọ: Ohunkohun ti Babaláwo ba fẹ ati ewé Ifá, / pelu imoràn pe ki ẹniti a dá'Fá yi fún / ki o yara maa fi pupo ninu ohun ini rẹ̀ / tọrẹ tabi kiowa tẹ Ifá.", "Verso 71.2 (yorùbá): Aṣiribomomo / a difá f'Olókun. / a bu f'Ọlósa. / A niki enikoçkan wọn wa rúbọ: / Ikoko-amo mọ̀rin, / eyẹlé mérindilógün, / Qkẹ merin owó / ati ewé Ifá. / Wọ̀n rúbọ, / wọ̀n nỉ: / A kiiri'di ökun. / A kiiri'dí Ọ̀sá. / Aṣiri Olókun kiitu, / Aṣiri Ọlósa kiyoo tu.", "REZO: ODI KA OKOLOYU OPUA ADIFAFUN ORISAYE TINSHOMO AYALORUN OBA NIFA TINSHOMO OLOFIN OBA ORISAYE ADIFAFUN EGUN OYIBA ORUN MAFEREFUN SHANGO ORISAYE OBAYE ADIFAFUN ODUDUWA.", "REZO: IFA ODI OTA OJORA EBENI EMU OMORO OLLEN ARARE BOLE ADIFAFUN OGUNFO UMBATI UMBOLE ELLE OCOLOCHU OGUELERO OWO GUISO CUMANDELEDE LA MOSE IBE E ECHIN LOFILE ESUN ADAFANFUNRIOLLE, TINCHOMO ELLA LORUN BOCORUMI BOBERIMI GUINPACHE CAFUN JACHO.", "REZO: ODI KA ODIKA ADIFAFUN ORI OYE TINCHOMA AYALORUN EYELE LEBO OMOREBE UN OBAO MOSEI SINOPARE ESHU LONA ESHU LOFIDE AMI ADIFAFUN OLI OLLE TINCHE ELLA ODO AKUKO LEBO EKU EYA EURE LEBO.", "REZO: NI KUMON LERI OKUMAMBO ARAYE SHANGO, KUKE OBA KANA OKUN NI LESUN OSADO ANO ORUNMILA ODI KA ADIFAFUN OKUMAMBO, ARAYE NI ISHE NI FUN LORUN.", "SUYERE: OZUN PON PON, OZUN PON PON NI TI IGUI AJA OMI ISAI SUN PON PON.", "REZO: ODIKA ADIFAFUN OMOLOGU ATATABIRAKUN OMODE MERIN OKUNI ABO OWO BOGBO YONO OLOFIN ELEJE GONOFO ZANGBETO LODAFUN PAKOKO KIKIVITO AKUOLOGA INLE OMO MERIN YEWA UKA LODAFUN AFAFA ORUNMILA BOKONO.", "REZO: ADIFAFUN OBATALA OMO MEDILOGUN MOYEN EKUTE LANRIN LANLA ONU GAGA NI ODARA ELEGUA OSAN ORUN MARUNLA ORISAYE OBATALA UMBOWA ONIKA ABITI NI AWO ODI KA."]}]$q$::jsonb),
(72,'03ed5cb55b51b4dda6ba5af2b8073e8e',$q$[{"titulo": "Idea central", "texto": "Ìdí Òtúrúpọ̀n trae soluciones para el embarazo y para enfermedades causadas por parásitos. La persona puede vivir una desilusión o un despertar espiritual. Ifá pide honestidad y anuncia un hijo poderoso que tendrá que vencer muchas dificultades; recomienda adorar a Òòṣà funfun cada cinco días."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos y busca apoyo ante dificultades para concebir o dar a luz (relatos de Olú-Ọgán y de Ṣàngó).", "Tiene una molestia en la parte baja del cuerpo que conviene revisar con un médico (relato de Ondugbé).", "Vive una desilusión o está cambiando su forma de ver la situación.", "Necesita ser honesto; un hijo podría enfrentar dificultades.", "Pidió ayuda a su familia y un intermediario no le entregó lo que le dieron (relato de Èṣù Ọ̀dàrà y los ancestros)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fuerza para dar a luz muchos hijos.", "Un hijo poderoso que hace grande a su padre.", "Riqueza, pareja, hijos y casa para quien adora a Òòṣà.", "Curarse de una enfermedad de la parte baja del cuerpo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedad en la parte baja del cuerpo; conviene atenderse con el médico.", "Que un hijo muera antes de tiempo si no se ofrece.", "Faltar a la honestidad."]}, {"titulo": "Enseñanza principal", "texto": "Ṣàngó ofreció completo para tener a su hijo, y ese hijo lo hizo grande. Lo que se adora con constancia —cada cinco días— devuelve riqueza, pareja e hijos."}, {"titulo": "Relatos reunidos", "puntos": ["Olú-Ọgán y la fuerza para parir. Ìdítiripọn consultó para Olú-Ọgán y le aconsejó ofrecer para tener fuerza para dar a luz muchos hijos: dieciséis semillas de quimbombó, dieciséis ñames hembra, cuatro chivas y 3,200 cauríes. Cumplió.", "Ondugbé y la enfermedad de las nalgas. Oṣunṣun, adivino de Olúigbó, consultó para Ondugbé y le pidió ofrecer para no padecer una enfermedad en las nalgas: dos gallos, un perro, 6,600 cauríes y medicina de Ifá. La enfermedad llegó, pero se pudo curar.", "Ṣàngó y su hijo Oṣé. Ifá consultó para Ṣàngó, que lloraba porque no tenía hijos, y le dijo que un hijo estaba por llegar si ofrecía. Ofreció completo, y el hijo que nació fue Oṣé. Le dijeron que lo llevara a donde fuera, y que si encontraba enemigos o una batalla lanzara a Oṣé contra ellos: habría una explosión y sus enemigos desaparecerían. Ese hijo hizo grande a Ṣàngó.", "Lààlà gbàjà y la adoración de cada cinco días. Ifá consultó para Lààlà gbàjà, que se iba a vivir para siempre en la granja y se quejaba de no tener bendiciones. Le dijeron que ofreciera, que volviera a casa cada cinco días y ofreciera a Òòṣà. Lo hizo, y enseguida llegaron la riqueza, la esposa y los hijos. Dijo feliz: 'Este Òòṣà sí merece adoración'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Olú-Ọgán: dieciséis semillas de quimbombó, dieciséis ñames hembra, cuatro chivas y 3,200 cauríes.", "Ondugbé: dos gallos, un perro, 6,600 cauríes y medicina de Ifá.", "Ṣàngó: ofrenda completa para tener hijo.", "Lààlà gbàjà: ofrenda a Òòṣà cada cinco días."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó recibe a su hijo Oṣé, su arma de dos filos. Òòṣà funfun (Ọbàtálá) se adora cada cinco días para el bienestar."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Semillas de quimbombó, ñames hembra (ewura)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 72.1 (yorùbá): İditiripon, İditiripon, / Ìdí abiyamo tiripon-tiripòn: / a dífá f'Olú-Ọgán. / Wọ̀n niki Olú-Ogán wa ṣẹbọ / a bimọ rẹ pupo: / eso ilá mẹrindilógún, / obiṣu (ewura) mẹrindilógún, / ewúré mẹrin / ati egbẹrindilógún owó. / Ó gbọ̀ ó rú.", "Verso 72.2 (yorùbá): Oṣunṣun-awo-Olúigbó: / li ó dífá f'Ondugbé. / A ni ki o wa rúbo / ki o ma baa ri àrùn Ìdí: / akuko-adiyẹ Méjì, ajá, / egbẹtalélógbọ̀n owó pẹlu / ati ewé Ifá. / Bi o ba ti ri àrùn Ìdí / ki o baa lẹ ṣan.", "REZO: ODI BATRUPON YABOLE APU OTO ASHIKALE SHEYO ASHIKALE KILE FELENI OWO KILE FELENI OTO.", "REZO: ODI BATRUPON NINCHE AWO NIDE OLOFIN CHEMUNI SHANGO TONCHE OLODAFA OBOLU BE ORUBO AIKORDIE ABO OSIADIE META EKU EYA ASHO FUNFUN ASHO PUPUA ABEFAOGUAO.", "REZO: YOBOLOBO APU OTO ASHIKALE SHEYE ASHIKALE KILE FELENI.", "REZO: ADI AWO LEÑI AUN TUYOFA LUYUNSI ADIFAFUN OBANALA ABASHELE ALAKE TINEORU OSHA ADIFAFUN TIMBELE YOKO ESHU KOMABA OMOBIRIN MEYI INDOKE ADASILE BABARI LODAFUN OBATALA.", "REZO: ORUN BELEKUN ORUN ADIFAFUN OKOLONSHO ALAPINI AWO ORUN EGUNGUN. ORUN GBONBA ORONI O PAISHAN META EMITI ONI ORUN OKE ORUN OTUN AKPADINIKE ALOSIN ASHEGUN OTA BURUKU OJOKO BIRIKITI KALE JAGUN APANI BASHO AWOLU KOLU KODIDE ORUN BELEDUN ORUN SIPA ALOSIN JE ORUN SHIGBE ORONI OROGUN NI APARA TOSHO."]}]$q$::jsonb),
(73,'fd487b314d188ba422c7b79470552d0d',$q$[{"titulo": "Idea central", "texto": "Ìdí Òtúrá pide cuidar la dieta para tener buena salud y ofrecer por la armonía de la familia. La persona puede tener problemas de presión arterial o colesterol. Su familia será numerosa y conocida por sus bienes si se comporta como sus antepasados. Debe ser generosa con los suyos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa su salud, como la presión o el colesterol, y debe revisarse con un médico (relato de Olúyemi).", "La familia se está desuniendo o teme separarse (relato de Alárá).", "Espera una familia numerosa y estabilidad económica."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una familia unida y feliz el resto de sus días.", "Prosperidad.", "Una casa llena y bien provista por compartir.", "Recuperar la salud con la ofrenda."]}, {"titulo": "Ibi y advertencias", "puntos": ["Presión alta y colesterol; conviene cuidar la alimentación y revisarse con el médico.", "Comer solo y no compartir.", "Desatender al enfermo por cuidar lo propio.", "Casarse sin el consentimiento de los padres."]}, {"titulo": "Enseñanza principal", "texto": "El que come solo no es como los demás; el que comparte con su familia llena la casa de su padre. Y quien no ayuda a su mayor cuando lo necesita pierde lo que se le había dado."}, {"titulo": "Relatos reunidos", "puntos": ["Olúyemi y la enfermedad de abajo. Ifá consultó para Olúyemi y le aconsejó ofrecer para no sufrir una enfermedad en la parte baja del cuerpo: una paloma, una gallina, un gallo, pescado ahumado, 18,000 cauríes y medicina de Ifá. El hijo que tiene este Odù no debe casarse sin el consentimiento de su padre o de su madre. Prohibido: nuez de kola y carne de animales de granja; puede cocinar con pescado o babosa.", "Alárá y la escoba. Ifá consultó para Alárá y le aconsejó ofrecer para que su familia no se dispersara: un manojo de escoba, que es la unión de muchas varas, dos pichones de paloma y 16,000 cauríes. Cumplió, y el adivino aseguró que sería feliz el resto de sus días. Alárá prosperó.", "Adábàá, el que comparte. Ifá consultó para Adábàá el que come solo sus ratas, para Adábàá el que come solo sus peces, para Adábàá el que come solo su carne, y para Adábàá el que se arrodilla en la casa de su padre. Este último fue el único que preguntó a Ifá qué camino tomar. Le dijeron que no dudara: empezó a matar chivos y a reunir a sus hijos, esposas y parientes para que todos comieran, bebieran y estuvieran contentos. La gente dijo que los otros no eran humanos, y que él sí tenía corazón. Su casa siempre estuvo llena.", "Níní y Àìní. Níní y Àìní eran sirvientes e hijos adoptivos de la Deidad (Òòṣààlá). Níní trabajaba a su lado y se hicieron ricos; Àìní trabajaba otra parcela con menos habilidad, y la Deidad prefería a Níní. Un día la Deidad enfermó y no podía levantarse. Los adivinos le marcaron doscientos huevos de aves del monte. Mandó a Níní a buscarlos, pero Níní se quejó por dentro y se quedó cuidando su granja. Entonces mandó a Àìní, que fue con los adivinos: le marcaron doscientas pimientas de caimán, la mitad en cada mano; en lo profundo del bosque debía cerrar los ojos y regarlas a derecha e izquierda, y después peinar los arbustos. Así lo hizo y encontró los huevos, con los que la Deidad sanó. Mientras tanto, unos ladrones se habían llevado todo el maíz y el ñame de la granja. Al sanar, la Deidad le quitó a Níní todas sus bendiciones y se las dio a Àìní."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Olúyemi: una paloma, una gallina, un gallo, pescado ahumado, 18,000 cauríes y medicina de Ifá.", "Alárá: un manojo de escoba, dos pichones de paloma y 16,000 cauríes.", "Adábàá: chivos para compartir con la familia.", "Àìní: doscientas pimientas de caimán; la Deidad, doscientos huevos de aves del monte."]}, {"titulo": "Relaciones espirituales", "texto": "Òòṣààlá (Ọbàtálá) premia a quien lo atiende en la enfermedad. Èṣù guía a Àìní a los huevos. Alárá es uno de los reyes hermanos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Escoba, pimienta de caimán (ataare), huevos de aves del monte, pescado ahumado, babosa; prohibida la nuez de kola."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 73.1 (yorùbá): Baba omọ niiṣe t'ọmo ni ire. / lye omo niiṣe t'ọmọ ni ire. / Ogbo ati Ato d'owọ Edú, / a dífá f'Olúyẹmi. / A niki o wa rúbọ / nitori àrùn Ìdí. / Ẹbọ: Ẹyẹlé, agbebo-adiyẹ, / akuko-adiyẹ, ẹja-aro, / egbàásàn owó / ati ewé Ifá. / Un padre desea un hijo sano, / una madre desea un niño sano, / la longevidad y la vejez dependen de Edú:", "Verso 73.2 (yorùbá): Qkọ̀ re-i-ko iwa ilè jọ: / a dífá f'Alárá. / Wọ̀n niki o wa rúbo / ki àwọn ebi rẹ̀ le maa jo / ki wọn ma tuka. / Ebọ: Iṣu-owọ, / ejigbere-eyẹlé, / egbàájo owó. / Alárá gbọ̀ ó rú. / Wọ̀n ni: / To, Abariwon! / 1 yoo maa ye p. / O, Alárá. Yiyẹ niiyẹ Alárá. / El azadón es el único / que cuida del bienestar de la tierra:", "REZO: ODI ATAKOFENE ODI ATA KOLE EÑI APARO OUN TUYEFE LEYUN SI ADIFAFUN OBALANSHE LEBO. ADIFAFUN ORUMILA. LODAFUN OBATALA ORUNMILA LORUGBE, EYELE LEBO.", "REZO: IDITACO LEÑI APO AUN TULLEFA LOLLUFE LOLLUN ADIFAFUN OBALANCHE LEBO EYELE LEBO.ORDAFUN ORUMILA ORDAFUN OBATALA. CUMAGUN B ALOLE OLLUTODE ODAFA LLOCO ADAFUN TOGO UN GUATIMA SE UN LLELE OBATALA. SUGUN BALOLE OLLUTODE ADAFALLOCO UN GUATI MASE UN GUATIMASE UN GUATIMA UN LLENFE OBATALA.", "REZO: LEGUN EDE ADODI OFOKU AKURIN SEMBE LUJU ATENA IFA SHOSHO LE OWORE OMO OLOGBOJODU AWO DE IFA SHAROTO ABIATEFINI MEFA ESHU ARA EKONI MEFA OASHO A NA ONINI ADIFAFUN ESHU FAUNMI INTOBI ARON KAFEREFUN AGBANUKUE KAFEREFUN ORUNMILA.", "SUYERE: AKASHOSHO OFUMI LA AWA KAMADAJUN."]}]$q$::jsonb),
(74,'84005b2cb1ce76f65b8dd5970d2f1007',$q$[{"titulo": "Idea central", "texto": "Ìdí Ìrẹtẹ̀ habla de trabajar duro para llegar a una posición elevada. La persona piensa en un ascenso o un empleo nuevo, pero el miedo puede bloquearlo. Puede ser un gran líder en su centro de trabajo; vivirá muchos años y conocerá a sus nietos. Pide paciencia y cuidado al hablar en público."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le ofrecen un ascenso o un empleo y teme no estar a la altura (relato de Adegbitẹ).", "Quiere tener trabajo y dejar de temerle (relato de Ariṣẹmaṣe).", "Busca liderazgo, una vida larga y quedarse firme en su lugar (relato de la olla de barro)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Llegar a ser rey o líder.", "Tener trabajo y no tenerle miedo.", "Larga vida para conocer a los nietos.", "Quedarse firme donde otros se queman o mueren."]}, {"titulo": "Ibi y advertencias", "puntos": ["El miedo a lo que se desea.", "Hablar sin cuidado en público.", "Juntarse con gente insolente."]}, {"titulo": "Enseñanza principal", "texto": "La paciencia, el conocimiento, la oración y la buena resolución hacen al líder. Por eso las deidades escogieron a Ọ̀rúnmìlà como su vocero en Òṣogbo."}, {"titulo": "Relatos reunidos", "puntos": ["Adegbitẹ será rey. Ọmọyin, el adivino del bienestar, que lava la cabeza del jefe y el cuerpo del iniciado, consultó para Adegbitẹ y le dijo que en el futuro sería rey. Le marcaron diez palomas, plumas de loro y 2,000 cauríes. Cumplió.", "El que no tenía trabajo. Ijimere, el adivino del ejercicio y la belleza, consultó para Ariṣẹmaṣe y le aconsejó ofrecer para tener trabajo y no tenerle miedo: un carnero, un azadón, un machete y un perro. Preguntó por qué, e Ifá le dijo: 'El azadón nunca falta al trabajo, el machete nunca se enferma, el perro trabaja sin descanso y el carnero no le teme a la oposición'.", "La olla de barro en la granja del bosque. Ifá consultó para la olla de barro, que iba a escoger tierra en la granja del bosque. Muchas otras cosas fueron también; algunas se quemaron y otras murieron, pero la olla, que fue la única que ofreció, ni se quemó ni murió: ahí se quedó para siempre.", "Ọ̀rúnmìlà, vocero de las deidades. Ifá consultó para Ọ̀rúnmìlà cuando iba a la ciudad de Òṣogbo con Ifá y mil y una deidades. Se comprometió a reunir a todas las deidades cada cinco días —Ṣàngó, Ọya, Ògún, Ọbàtálá y las demás— y a ser quien dijera al pueblo lo que cada una pedía. Lo escogieron por su paciencia, su conocimiento, su oración y su buena resolución: 'En todo lo que haya que hacer, tú serás nuestro líder y vocero'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Adegbitẹ: diez palomas, plumas de loro y 2,000 cauríes.", "Ariṣẹmaṣe: un carnero, un azadón, un machete y un perro.", "La olla de barro: ofrenda antes de escoger tierra.", "Ọ̀rúnmìlà: reunir a las deidades cada cinco días."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es vocero de todas las deidades: Ṣàngó, Ọya, Ògún, Ọbàtálá y las demás. Orí se lava para la corona."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Plumas de loro, azadón, machete, olla de barro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 74.1 (yorùbá): Ọmoyin awo Ire / Ọmoyin wẹ ori Olorí, / ori-olori mọ. / Ọmoyin wẹ awo-alawo, / awo-alawo nke roro. / a dífá fún Adegbitẹ Awẹrorogbọla / Wọ̀n ni: / Adegbitẹ a joba lola. / Ẹyẹlé mẹwa, ikoode / ati egbàáwa owó li ebọ. / Ó gbọ̀ ó rú.", "Verso 74.2 (yorùbá): ljimere awo idaraya, / asunwọn-lewà: / li o difá f'Ariṣémaṣe İdirẹtèrẹtẹ. / Wọ̀n niki o wa ṣẹbo / ki iṣẹ le maa wun iṣe, / qni èrú iṣe nba. / Ebọ: Agbo, pkọ̀, / adá, ajá. / A ni: Eetiri? / Hà nì: / Qkọ̀ kiikọ isé sile. / Adå kliṣokunrun, / Ajă nf'ori ja'gbo wa ṣiṣé. / Erù ijà kii b'Agbo.", "REZO: ODI LEKE AWARI ODI OLOWO ASHUPA ODOLORO ODIGUIN ODAFUN ORUNMILA ORUBO."]}]$q$::jsonb),
(75,'975b4b6c2ba67f2f710e5c4c8fec175d',$q$[{"titulo": "Idea central", "texto": "Ìdí Ọ̀ṣẹ́ habla de daños que vienen de organismos que no se ven, como los parásitos, y advierte que el exceso en la vida sexual trae enfermedad. Hay un enemigo desconocido que estorba los propósitos de la persona. Pide ser un fuerte adorador de Ifá para tener larga vida, calma y buen juicio: la fortuna que le desviaban llegará por fin a sus manos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme a un adversario que todavía no identifica (relato de Baálẹ̀-ẹro).", "Puede tener una enfermedad relacionada con la vida sexual y debe revisarse.", "Ve oportunidades que se le desvían y quiere recuperar la calma y el buen juicio.", "Cumplir el consejo completo hace la diferencia (relato de la palma y Pèrègún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que los parásitos y lo que no se ve no le hagan daño.", "Descubrir al enemigo oculto.", "Larga vida, calma mental y buen juicio.", "La fortuna que sus enemigos le desviaban llega por fin a sus manos.", "Que la gente lo siga y lo busque."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un enemigo desconocido que estorba sus propósitos.", "Enfermedad por el exceso en la vida sexual; conviene revisarse con el médico.", "Ofrecer a medias.", "No compartir con honestidad los bienes con la familia."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se ofrece completo protege completo. La palma ofreció la mitad y quedó protegida; Pèrègún ofreció todo y además quedó armada con su filo. Y quien ofrece abundante a Ifá no queda bloqueado por nada en el mundo."}, {"titulo": "Relatos reunidos", "puntos": ["Los 165 árboles y el extraño. Ifá avisó a los 165 árboles del bosque que se acercaba un extraño peligroso que podía matarlos. Debían ofrecer cuatro cuchillos, manteca de òrí, aceite de palma y 18,000 cauríes. Todos escucharon, pero casi ninguno cumplió. La palma (Ọ̀pẹ) dio solo la mitad; Pèrègún dio todo. A los que ofrecieron se les dio medicina de Ifá y se declaró: 'Los parásitos nunca dañarán a la palma, nunca atacarán a Pèrègún; y el parásito terco que se atreva con Pèrègún morirá en su filo'.", "Baálẹ̀-ẹro y el enemigo oculto. Baálẹ̀-ẹro, el jefe de los viajeros, fue a consultar porque algo le frustraba todo lo que emprendía y no sabía quién era. Ifá le dijo que tenía un enemigo oculto, de esos que desvían y estorban los propósitos de otro, y le marcó cuatro gallinas, 8,000 cauríes y medicina de Ifá para que quedara al descubierto.", "Àjàgùnmòlè, el que responde por el destino. 'Que el árbol del cercado se rompa en gajos para sembrar otro.' Así consultaron para Àjàgùnmòlè, el jefe de los babaláwo en el cielo, y le dijeron que mientras más abundantes fueran sus ofrendas a Ifá, menos lo bloquearía cualquier cosa negativa en el mundo. Ofreció y tuvo una vida tranquila y larga. El canto lo hace responsable del destino: 'Si no tengo dinero, si no tengo pareja, si no tengo hijos, si no tengo casa, si muero joven: tú respondes, Àjàgùnmòlè'.", "Eégún y el rey. Los awo de Eégún consultaron para Eégún, y los awo del rey para el rey, cuando los dos venían del cielo a la tierra. Les dijeron que al llegar siguieran adelante, y los dos habían ofrecido antes de venir. Cuando Eégún llegó a la tierra, la gente gritaba y corría detrás de él; cuando llegó el rey, preguntaban por dónde había venido y formaban una multitud a su espalda. La vida les fue placentera a los dos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Los árboles: cuatro cuchillos, manteca de òrí, aceite de palma y 18,000 cauríes.", "Baálẹ̀-ẹro: cuatro gallinas, 8,000 cauríes y medicina de Ifá.", "Àjàgùnmòlè: ofrendas abundantes a Ifá.", "Eégún y el rey: la ofrenda hecha antes de venir a la tierra."]}, {"titulo": "Relaciones espirituales", "texto": "Àjàgùnmòlè, jefe de los babaláwo del cielo, responde por el destino de quien ofrece. Eégún y el rey son seguidos por la gente. La palma y Pèrègún son los árboles protegidos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Palma (Ọ̀pẹ), pèrègún, manteca de òrí, aceite de palma, cuchillos."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 75.1 (yorùbá): Ojú liafi nṣo orí, / ohun ti nṣe Ọ̀ṣẹ́ ko to inkan: / a daa f'Orunlojo igi. / A niki wọ̀n wa rúbọ / kiwọn ma baa gba àlejò buburú / tiyoo pa wọn: / Ọbẹ mẹrin, òrí, epo / ati egàásan owó. / Wọ̀n gbọ̀ wọn ko rú. / Opẹ̀ rúbọ ṣùgbọ̀n ko rúbo pe. / Pèrègún nikan li ó rúbo pe, / wọ̀n ṣe ewé Ifá fún wọn. / Njẹ ó di to, Abariwon! / Afomo (Ọ̀ṣẹ́) kiip'Ọ̀pẹ, / Afomo kiimọ Pèrègún, / Afomo tiko gboran biobamo Pèrègún / ojú Pèrègún ni yoo ṣe kú dandan. / \"Los ojos protegen a la cabeza\", / \"Una pequeña cosa puede hacer / daños (estragos) incalculables\":", "Verso 75.2 (yorùbá): Qṣéṣewọn, / wọ̀n nwadi Ọ̀ṣẹ́. / biabarúbo tan lia-nri-di Aṣeni. / A daa fún Baalẹ-ero, / wọ̀n nibi-o-ba-rúbo-a-ridi Aṣeni, / Ô ni: kini ebọ? / Wọ̀n niki ó rú: / Adiyẹ mérin, / ẹgbàárin owó ati ewé Ifá. / Ellos sufrieron un desastre (daño), / todos investigan las causas del mal, / pero hasta que cada uno no sacrificó / no pudo descubrir la razón / de tener un enemigo desconocido (Aṣeni'\"?):", "REZO: ODI SHE IDIN SHE OUN BABALAWO BONBO SHEKETE SHEKETE BONBO.", "REZOS: EDICHE ACOTO ICHE ODAFUN AMALE ODAFUN ORUMILA OCHORI OLADAFUN OSHUN IGUI ABACHE GUIN ONI ONLE ACOCS EYELE IDEBA IRERE CHE IDICHA ADIFAFUN OLOCHE OLOFIN RURU TURU ILLA INTORI OBINI TCHIRE LECHE IBIBACHE QUIN ÑAMI ADIFAFUN AMATOTO ALUFARO NIN KAFEREFUN OGUN EYELE LEBO BAGAZOS DE MAIZ EYELE EURE LEBO.", "REZO: OLADOFUN OLUO BOMO SHE KETE SHE KETE OLUO OLOFERI MODUN ERINI ODI KERESHE IGUI OBASHE KIONI ADFAFUN ONYE AKOKA EYELE IDEBA IDISHE IRELESHE ADIFAFUN OLOSHE OLOFIN ELELU IYA ILORI OBINI SISHE IRLESHE IGUIBASHE IGBIN ÑAMI ADIFAFUN AMATOTO OLOFARINU OGUN EYELE LEBO EURE LEBO."]}]$q$::jsonb),
(76,'80eb62b5c6247fe0a3e26d38b62df521',$q$[{"titulo": "Idea central", "texto": "Ìdí Òfún habla de quitar obstáculos y de un viaje inesperado, que puede ser también un viaje espiritual o una consagración. Los negocios van mal o están trabados: toca tomar un nuevo rumbo y organizarse. Ifá le desea a la persona la bendición de los hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita reorganizar un negocio que no prospera.", "Se acerca un viaje que no tenía planeado (relato de Ìdí y Òfún).", "Se siente cercado por un problema (relato de la gente de Ifẹ̀-Ooye).", "Alguien cercano desea tener hijos (relato de la termita)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un viaje inesperado que sale bien.", "Salir de un cerco o de un enredo.", "Muchos hijos, incluso para una mujer que no los tenía.", "Ser una persona buena e influyente."]}, {"titulo": "Ibi y advertencias", "puntos": ["Negocios bloqueados.", "Perder un cargo por no ofrecer lo que se lleva puesto.", "Usar adornos brillantes que atraen a los envidiosos, si es mujer."]}, {"titulo": "Enseñanza principal", "texto": "Cuando el pelo está enredado, solo el peine lo desenreda. Para salir del cerco hace falta lo que ordena, no la fuerza."}, {"titulo": "Relatos reunidos", "puntos": ["El viaje inesperado de Ìdí y Òfún. Ojijifiri consultó para Ìdí y para Òfún y les dijo que venía un viaje inesperado; les pidió ofrecer para que fuera un éxito: una carnera, una paloma, 18,000 cauríes y medicina de Ifá, una sopa de hojas de àikújegúnrè con la paloma o con pescado ahumado, que se come muy temprano.", "La gente de Ifẹ̀-Ooye cercada. Ìdí los guarda en casa; Òfún los derrama cuando maduran; solo Ọ̀rúnmìlà los salva. Así consultaron para la gente de Ifẹ̀-Ooye cuando estaban sitiados. Ofrecieron un peine, una paloma y 24,000 cauríes, porque si el cabello está enredado, solo el peine lo desenreda.", "La termita y sus hijos. Ifá consultó para la termita, que lloraba porque no tenía hijos, y le dijo que los tendría, todos oscuros e iguales, si ofrecía dos correas. Es la misma tira que forman las hormigas cuando avanzan por miles en la tierra. Ofreció y tuvo hijos sin número que llenan la tierra.", "Àńsèké, la princesa de los insectos. Ifá consultó para Àńsèké, la princesa y la más influyente de los insectos, que lleva dos aros de cuentas alrededor de la cadera. Le pidieron ofrecer esas cuentas para tener larga vida, y se negó. Los demás insectos se reunieron y la destituyeron como princesa, aunque no pudieron quitarle su origen noble. Vive mucho y los insectos la rodean, pero ya no es su princesa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ìdí y Òfún: una carnera, una paloma, 18,000 cauríes y sopa de àikújegúnrè con paloma o pescado ahumado.", "Ifẹ̀-Ooye: un peine, una paloma y 24,000 cauríes.", "La termita: dos correas.", "Àńsèké (rechazado): sus cuentas de la cadera."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es el único que libera al que está cercado. Èṣù castiga a quien no le da su parte."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àikújegúnrè, pescado ahumado, peine, correas, cuentas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 76.1 (yorùbá): Ojjjifiri: / liodifá fún Ìdí, / a bu fún Òfún, / wọ̀n ni: / ọ̀ràn idídéfuu (airotẹlẹ) nbọ, / kiwọn wa rúbo / kiolejẹ fun rere. / Agùtàn, eyẹlé, / egbàásan owó / ati ewé Ifá.", "Verso 76.2 (yorùbá): I ndi wọ̀n mọ le, / EH / Òfún nhon wọn mọ gbò: / Tani le gba'nl? / Oronmila to le gba'ni / Tanile vọ nl? / Orúnmita lo le yo ni / a daa fún wọn n’Ifẹ-Ooye / ni jo akamg. / wọ̀n ni phọ niki wọn ve, / kiwọn ro / Oriya, gyẹlé / ati pabăámejila owó / nitoripe / \"Bi ayé irun ba di'ju, / Oriya ni l yan'ju re\".", "REZO: ODI FUMBO ODI FUMBO ARA, ARA OSHANLA. ARA INLE AYE MOYERANI.OSHANLA ODOGUN AGBA OGO ARA.", "REZO: OKOKONIROKO ILE LACHARAYU IQUIDO ONI BABALAWO LODARFUN ELEMINI BARA SAGUN OBA TIOBA MOLLIN NIGURIN ERIN.", "REZO: OKA COMI CORO ILE LOCHASA UNEGUILO ONI BABALAWO LODAFUN ELENRINI BARATI OSAGUN OBATI OBALLALLUN NI EBERIN OCUPA NILABAN IKUTOCHU DE DE AUN AFOQUI IDE COFO ORUN COFO ELLO KOFO.", "REZO: AKANKANIKARO ILE LACHARAYU EQUILONA BABALAWO LODARFUN ELEMINI BARATI OSAWO UMBATI AGUA IAYEN NIOBINI GUCACOFA NIBATAN ACUCUE NIA TAIRE IKU TACHODEDE ICU TACHODEDE ICU OFO ANO LOCHEDEDE ORUN COFO ELLO QUICUIBI ANO OWO MELLE.", "REZO: ODI FUMBO KARIDEFUN KARAWE DENDEFUN KARKO ELEGUA ESHU BAIKU NIWE INLE MOWANILE ELEGUA ESHU ODARA OFUNDI ADIFAFUN ETBA AUN BATON LONI OBINI LELE EBEYI AWO ADIFAFUN AYE EYELE LEBO IDIFUN ADIFAFUN ESHU ANIRE LAWO OTAYEIBE ADIE KOYOKO EYELE BABALAYIKI AWO TENIYI AWO ELEGUARA SOKUN SOKUN LAYE OBUNDI OFOJUDE ABURE ALODE EBBO OBALU OGUN ODARABI AWO TENIYI OMO ELEGUARA ODI FUMBO.", "REZO: MAYOLO NI IFA AWO BANI AWO OMO ODI FUMBO OBATALA NI SHIBI AWO ALABO LOKUN OMO IFA ORINIFA ELEGUA ALA KANAKO ESHU GOGO ELEGUA ONI IFA INLE IFA BAGUN OBATALA OLONIAWA AWO OSHA ORI OBATALA ONIRE IFA ELEGUA WEWO TISHA IFA.", "REZO: ODI FUMBO ABAYERE AGUEMA ONIROGUE EKUTELE NIODERE ORUNMILA ADIFAYOKO OBATALA SHUTUDEDE IKU MAFO UMBALODE ESHU ODARA ORUMALE ISOTA ONIRE EBBO ABALLERE DEDERE NIFA EBBO EGUADA KOMAFOLLA KAMASHODO ASHEGUN OTA OBATALA ESHU OMO ADIFAFUN OLUO ALADASHE.", "+++"]}]$q$::jsonb),
(77,'f6271b1250be022500f9d05c9c92443b',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ogbè dice que las relaciones espirituales y las emociones de la persona pesan más que los negocios y el dinero, por eso los negocios avanzan despacio. Ifá promete riqueza, pide no ser codicioso ni desesperarse, y asegura que la persona saldrá bien parada aunque le deseen la destrucción."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le dedica mucha atención a sus relaciones y su negocio avanza lento.", "Pregunta por un posible matrimonio (relato de Agbe-Imorimodori y la hija de Ọlọ́fin).", "Tiene riqueza y fama, pero debe cuidarse de quienes quieren perjudicarlo (relato de Odùgbemi).", "Siente que le faltan bendiciones (relato de Iṣin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Llegar a ser muy rico con la ofrenda.", "Salir adelante contra todo lo que le desean o le hacen.", "Matrimonio: la hija de Ọlófin fue dada como esposa.", "Heredar el lugar del padre gracias a la ofrenda."]}, {"titulo": "Ibi y advertencias", "puntos": ["Codicia y desesperación.", "Confiar en la belleza o en la palabra fácil y no ofrendar.", "Romper una costumbre sagrada y perder lo ganado."]}, {"titulo": "Enseñanza principal", "texto": "La buena fortuna ya llegó al vecindario, pero solo la recibe quien la merece. El buitre, torpe y poco querido, fue el único de tres hermanos que ofrendó, y fue él quien terminó en el trono."}, {"titulo": "Relatos reunidos", "puntos": ["Agbe y la hija de Ọlófin. Ifá consultó para Agbe-Imorimodori cuando iba a pedir por esposa a Biojẹla, hija de Ọlófin. Le marcaron dos ratas, dos pescados, una gallina y 3,200 cauríes, y Ifá dijo que la joven sería entregada a un babaláwo como esposa.", "Odùgbemi, rico en la tierra. Aigboniwonran consultó para Odùgbemi, un hombre muy rico y popular, y le pidió ofrendar. Si el signo sale en la ceremonia del nacimiento de un niño, se ofrece una paloma; si sale en la iniciación de Ifá, una carnera.", "La manzana akee. Èlà consultó para la manzana akee, que se lamentaba cada día preguntando si algún día tendría riqueza, esposas e hijos. Ofreció. Desde entonces le cortan las hojas, le quitan la corteza y los frutos y le sacan las raíces para medicina, y aun así sigue prosperando: el daño que le hacen se le convierte en ganancia. El fruto se pone rojo como ojos cansados y luego se abre, y eso significa quedar libre de la pobreza.", "El buitre, Kólikóli y Èlulùú. Olórèé era viejo y tenía tres hijos: Gúnnugún, el buitre, el mayor y torpe; Kólikóli, gran orador y buen agricultor; y Èlulùú, el menor, hermoso y encantador. A los tres les pidieron su vestido agbàdà como ofrenda y solo el buitre cumplió. Al morir el padre lo sentaron en el trono, pero el pueblo lo rechazó por torpe. Escogieron entonces a Kólikóli, pero alguien le echó una medicina en el agua y empezó a tartamudear. Coronaron a Èlulùú y lo subieron a un caballo para recorrer la ciudad; en el camino vio un grillo entre los arbustos, se bajó a perseguirlo aunque los ancianos le dijeron que un rey no desmonta antes de llegar al trono, y quedó atrapado en el lazo que servía de trampa. Por romper la costumbre perdió la corona, y no quedó más remedio que coronar al buitre, como había anunciado Ifá."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Agbe: dos ratas, dos pescados, una gallina y 3,200 cauríes.", "Odùgbemi: una paloma en la ceremonia de nacimiento; una carnera en la iniciación de Ifá.", "Herederos de Olórèé: el vestido agbàdà de cada uno.", "Para hacerse rico: la ofrenda que marque Ifá, sin desesperarse."]}, {"titulo": "Relaciones espirituales", "texto": "Ọlófin entrega a su hija a un babaláwo. Ifá favorece al que ofrenda aunque el pueblo no lo quiera."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Manzana akee (hojas, corteza, frutos y raíces usados como medicina), vegetal tètè, ratas, pescados, gallina, paloma, carnera, vestido agbàdà."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 77.1 (yorùbá): Ohun tiope baále ilé ti ko ni kongara idẹ, / oun li o sẹ iyale ilé ti ko ni'busùn ala, / a difá f'Agbe-Imorimodori / nlọ gba Biojẹla omọ Ọlọ̀fin. / Eku Méjì, eja Méjì, adiyè / ati ẹgbèrindílógún owó. / Ifá ni: / \"Babaláwo niki a fa ọmọ yi fún lati fiṣe aya\".", "Verso 77.2 (yorùbá): Aigboniwonran awo Olú-Oje: / li o dífá f'Odùgbemi / tio nṣe borokini ayé. / Wọ̀n niki Odügbemi wa rúbo, / kioma baa di bòrokinní òrun. / Eyẹlé ni ẹbọ / biabadaa ni Esentaye omotitun. / Àgùtàn ni ẹbọ biabadaa ni ltẹfá. / 115 borokinní: hombre respetable, rico.", "/ IROSO OGBE", "REZO: IROSO UMBO SHOREGUN SHORU KOMASHE KOTUSHE ARESHENLE ADIFAFUN ORUNMILA TIO FA MARO AKOFA ELEBO, AIKORDIE ELEBO.", "REZO: UMBE MI ADIFAFUN ELEGBA MONI ALASHE LEBO MORO MORO LOKUN TONIFA ONI BARABANIREGUN KOBALA ESEOBELE OTUN ORUNMILA ESE OPELE OSI ELEGBA ONIFA ESHU UNTEFA ORUNMILA ODA ELEGBA BARALAY IKI LOKUN LAYE NI YARE MAWA OSUN OKUNOLA LAROYE LOYE LAYE OLOKUN OMO OLOKUN SOKUN IYARE ELEGBA KOWA YEBE ORUNMILA MOFORIBALE IRE ASHE GUN OTA ATEFA IGBODUN ELESE ELEGBA LODAFUN ORUNMILA.", "REZO: SHEREN SHURU KOMASHE KOTUSHE ARESHELE ADIFAFUN ORUNMILA TIO FA MARE AKOFA AIKORDIE LEBO.", "REZO: ALAMU SHEMI AKOKOLE KUANI ADAFUN ARIRE AKUKO OMO AJERE TINSHE OMO YAY OLORUN.", "REZO: SHERE SHENU AUN LATE KOROSHE GUANTOSHE EREKE SHEKE, ADIFAFUN ORUNMILA NIBATI OBATE ELEGBA NIFA FALORO OWO OLANA ADIFAFUN LODE ARONIBA AUN AWO.", "REZO: UMBE MI ADIFAFUN ELEGBA MONI ALASHE LEBO MORO MORO LOKUN TONIFA ONI BARABANIREGUN KOBALA ESEOBELE OTUN ORUNMILA ESE OPELE OSI ELEGBA ONIFA ESHU UNTEFA ORUNMILA ODA ELEGBA BARALAY IKI LOKUN LAYE NI YARE MAWA OSUN OKUNOLA LAROYE LOYE LAYE OLOKUN OMO OLOKUN SOKUN IYARE ELEGBA KOWA YEBE ORUNMILA MOFORIBALE IRE ASHE GUN OTA ATEFA IGBODUN ELESE ELEGBA LODAFUN ORUNMILA.", "REZO: IFA NI KAFEREFUN SHANGO ATI OGGUN, LODAFUN ORUNMILA, ADIFAFUN OBATALA.", "REZO: IROSO UMBO OKUN IRE OSIBALE, IROS UMBOMI EYU NIFON UMBE OSHA OGUBO AJAN NAMAYA EKUN ATOLA DOLA IGUADA LODIFAFUN ORUNMILA NIKATIKUN OGBUN AROMO OYORIKU IRE DOI A KATIKERE LOBI AFIKERE EKUN EBBO OBINI IKERE OJIN EKUN OKO EBONI OSHE OGIDAN ADIFAFUN ORUNMILA."]}]$q$::jsonb),
(78,'98ab6034486ca9cd275acb9955021826',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ọ̀yẹ̀kú habla de envidia y de seducción, y pide ofrendar para evitar consecuencias graves. Un cambio de trabajo o de actividad le traerá mejoras. La persona no debe apresurarse; recogerá el fruto de cuidar a sus hijos, y hay una herencia para ella que no debe anunciar antes de recibirla."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa mudarse o cambiar de actividad (relato de Ọ̀rúnmìlà en casa de Olókun-Ṣande).", "Su éxito puede despertar envidia.", "Una relación puede dañar a un tercero (relato de Amure y la esposa de Ṣàngó).", "No debe apresurarse a juntar dinero; las ganancias llegan con espera."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Mejoras por cambiar de trabajo o de casa.", "Ganancias y una vida tranquila; Orí le dará buenos frutos.", "Recompensa por alimentar y cuidar a los hijos.", "Una herencia que está por llegar."]}, {"titulo": "Ibi y advertencias", "puntos": ["Envidia por cobrar lo que se gana.", "Llevarse a la pareja de alguien poderoso: la muerte lo persigue si no ofrenda.", "Vender o malbaratar lo que es herencia de la familia.", "Anunciar la herencia antes de tenerla."]}, {"titulo": "Enseñanza principal", "texto": "Solo el fuerte va a la guerra, solo el que aguanta es agricultor y solo el cortés llega a babaláwo. Lo heredado no se vende: Ìrosùn vendió a su hermano Kèlèkú y desde ese día nada le salió bien."}, {"titulo": "Relatos reunidos", "puntos": ["Amure y la esposa de Ṣàngó. Oro Dúdú, el adivino del interior del bosque, consultó para Amure cuando iba a llevarse a la mujer que Ṣàngó tenía en su casa, y le advirtió que si no ofrendaba la muerte lo mataría. Le marcaron tres chivos y 6,600 cauríes. Escuchó y cumplió.", "Ọ̀rúnmìlà en casa de Olókun-Ṣande. Cuando Ọ̀rúnmìlà se mudaba a la casa de Olókun-Ṣande, le dijeron que ahí tendría muchas ventajas pero que lo envidiarían cuando empezara a cobrar sus honorarios. Ofreció cuatro palomas, una calabaza de iyẹ̀-ìrosùn y 8,800 cauríes, y luego, a petición de los adivinos, tres chivos y 6,600 cauríes más. Aun así lo envidiaron, y él cantaba: 'El adivino se mudó con su calabaza llena de polvo iyẹ̀, y al adivino ya se le acabó el polvo'.", "Şojúẹwà, hijo de Òyinbó. Le pidieron a Şojúẹwà, el mayor de los hijos de Òyinbó, que ofrendara para tener riqueza; le dijeron que su Orí le daría buenas ganancias y que la vida le sería agradable. Ofreció dinero y palomas, y tuvo paz y tranquilidad.", "Ìrosùn vende a su hermano. Le advirtieron a Ìrosùn que no vendiera a Kèlèkú, su hermano, al hombre blanco, y que ofrendara. Él dijo que era su herencia y que haría con ella lo que quisiera. Lo vendió; el hombre blanco empezó a hacer maravillas con lo que compró y Ìrosùn ya no logró nada más en su vida. La serpiente, que camina sola y en zigzag, muere de una en una: así se pierde el que rompe con los suyos. Kèlèkú también es el nombre de una tela muy cara que se hereda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Amure: tres chivos y 6,600 cauríes.", "Ọ̀rúnmìlà: cuatro palomas, una calabaza de iyẹ̀-ìrosùn y 8,800 cauríes; después tres chivos y 6,600 cauríes.", "Şojúẹwà: dinero y palomas."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó defiende lo que es suyo. Olókun-Ṣande abre su casa a Ọ̀rúnmìlà. Orí da las ganancias."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Iyẹ̀-ìrosùn (polvo de Ifá) en calabaza, chivos, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 78.1 (yorùbá): Oro dúdü awo inú igbó: / li difá l'Amure, / nigba Amure niọ / gba obirin Sàngó wa ilé. / Won ni: / \"bi ko ba san ebọ, / ikú naa liomaa paa\". / Obúko méta, / egbẹ̀talélógbọ̀n owó. / Ó gbó ọ̀ rú.", "Verso 78.2 (yorùbá): Itakutali-aita-aṣo, / Irikurili-airi-ofi: / li o difá f'Ọ̀rúnmìlà / nre'le Olókun-Ṣande. / Wọ̀n ni: / \"ilé Olókun naa a san an pupopupẹ ju. / Nitorinaa ki ó rú\": / Eyẹlé mẹrin, akeregbe iyẹ-iròsù / ati egbèrinlélẹgbaárin owó, / nitoripe nigba o ba j'eru / titi ara a la wọn. / Ọ̀ rúbọ. / Wọ̀n ni: \"ki o tun rú: / Öbúko mẹta / ati egbetalélógbọ̀n owó sii\" / Ó gbọ̀ ó rú. / Nigbati o j'eru titi ara la wọn. / O nkọrin bayi: / Awo re'le lọ f'iyẹ̀ wa o / lyẹ̀ Awo ko dẹ kù / lyẹ̀ Awo ko dẹ kù / Awo re'le lọ fiyẹ̀ wa o / lyẹ̀ Awo ko dẹ kù.", "REZO: IROSO YEKU IROSO KALEKU AWO OFI ABE LALA BELE LELEMAKA DAKUARERERE IFA ONIBARABARINEREGUN AWO BAYEBA IFA KORERE AWO OBAYA BEIYE IKU.", "REZO: IBE IKU OREO BAYEBI IKU UNLO BAYEBI IKU MOWANI OLORUN BAYEBI IKU IKU OLORUN.", "SUYERE: AWADA OBAYE IBEIYE, AWADA OBAYE IBEIYE IKU, AWADA OBAYE IBEIYE IKU LELEO AWADA OBAYE IBEIYE.", "REZO: IROSO KALEKU KOSI AWO EFI ABE LALA BALE LELE MAKADA KUARERE IFA ONI BARABANIREGUN AWO KAYEDI IFA KERERE AWO OMAYE BAIYE IKU IROSO KALEKU AWO MAYABA, IKU MAYABA, IKU OBA KOLOYE, AWO OBA KOLOYE KO YENERIFA INLE AKUA URO ABEYEKU IROSO KALEKU EFIA OBA KOLOYE IFA MAFEREFUN ORUNMILA, SHANGO, ELEGBA.", "REZO: ACAPAN GANGA ORUN NICUTE CUTE IFE ILESE ADIFAFUN TINCHORE IRE ACUTA LEBO LORDAFUN ORUMILA ESHU Y OZAIN.", "REZO: IROSO KALEKU KOSI AWO EFI ABE LALA BALE LELE MAKADA KUARERE IFA ONI BARABANIREGUN AWO KAYEDI IFA KERERE AWO OMAYE BAIYE IKU IROSO KALELU AWO MAYABA, IKU MAYABA, IKU OBA KOLOYE, AWO OBAKOLOYE KO YENERIFA INLE AKUA URO ABEYEKU IROSO KALEKU EFIA OBA KOLOYE IFA, MAFEREFUN ORUNMILA, SHANGO, ELEGBA.", "REZO: IROSO YEKU AKAPA GANGA ORU NIKUTE KUKU IFA IRESE. ADIFAFUN GUERE TINSHOMO AGUTAN ELEGBO. OLOGBO META KUPANOLU ARUN PAMILO ATARI AWO QUI IBEMIZA ADIFAFUN ORUNMILA,AKUKO ELEGBO KEBOYO MEYE SHOGUDU MEYI EBEYE AWO, EYELE MEYI, ABO ELEGBO.", "SUYERE: KUKE EUDE ASHO ODUDUWA AFE OYU ASHO KI GUOFI."]}]$q$::jsonb),
(79,'118909af68b0c0b89ea1f567f512dac4',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ìwòrì enseña que no hay alegría, paz ni ganancia verdadera cuando se actúa con maldad, y que las dificultades y los cambios son parte del crecimiento y un camino a la sabiduría. La persona debe mirar sus metas de largo plazo y no conformarse con gustos pasajeros. Pide honrar al padre: si vive, no contradecirlo; si murió, invocarlo y rezarle."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita una meta de largo plazo y no solo una ganancia rápida.", "Pasa por cambios incómodos que le pueden enseñar mucho.", "Pidió algo y le llegó de más; debe aprender a pedir con medida (relato de los granjeros y la lluvia).", "Piensa viajar o dejar algo a medias, y debe cumplir sus compromisos y honrar a los mayores (relato de Ẹ̀mí léńjé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un viaje o un trabajo fuera que trae bienes, mientras la casa también mejora.", "Un hijo a la vuelta del viaje.", "Riqueza, esposa, hijos y casa por honrar al padre.", "Alcanzar la 'buena posición' por el buen carácter y la sabiduría."]}, {"titulo": "Ibi y advertencias", "puntos": ["Robar o dañar al prójimo: todo acto malo se regresa.", "Dejar las cosas a medias o no tratar a la gente con la verdad.", "Rechazar la ofrenda y luego pagar el doble."]}, {"titulo": "Enseñanza principal", "texto": "Quien nunca pasó escasez no sabe apreciar la abundancia, y una vida toda dulce, sin nada amargo, es aburrida. La buena posición se busca en el mundo: aprendiendo de todo, haciendo el bien al que necesita, sin miedo y con buen carácter. Si el padre ya murió y hay problemas sin salida, se le invoca durante siete días sin salir de casa."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y los que querían quedarse en el cielo. Le anunciaron a Ọ̀rúnmìlà que los seres humanos vendrían a hacerle una pregunta, y ofreció pescados y doscientos ẹka. Un día llegaron toda clase de personas y espíritus: moribundos, ladrones y malhechores, cansados de ir y venir de la tierra, y le pidieron quedarse en el cielo. Ọ̀rúnmìlà les explicó que seguirían yendo y volviendo hasta alcanzar la buena posición que Odùduwà señaló para cada quien. Para lograrla había que limpiarse de las faltas, llenarse de conocimiento, vivir sin miedo a los enemigos, a la muerte, a la enfermedad o a la pobreza, gracias al buen carácter y la sabiduría, dejar de robar y hacer el bien a los pobres. Les dijo que quien roba recibe castigo y que lo malo regresa. Cuando todos los hijos de Odùduwà elegidos para traer lo bueno al mundo estén reunidos, se llamarán ènìyàn, seres humanos.", "Los agricultores y la lluvia de todo el año. A los agricultores les advirtieron que si todas las estaciones fueran de lluvia el mundo no tendría armonía, y fueron con Àgbọnnìrègún. Ọ̀rúnmìlà les pidió cuatro chivas y 8,000 cauríes para que el mundo siguiera como lo ordenó Odùduwà, con una temporada de lluvias y otra de secas. Se negaron. Ese año llovió sin parar y no salió el sol; la gente enfermó, muchos murieron y la cosecha se perdió. Volvieron a disculparse y Ọ̀rúnmìlà les dijo que la ofrenda se había duplicado: ocho chivas y 16,000 cauríes.", "Ẹ̀mì Léńjé y la ciudad de Ìwòyè. Le dijeron a Ẹ̀mì Léńjé que en el extranjero lo esperaban y que fuera sin tardanza, aunque se quedaría pensando en su casa. Lo mandaron llamar para ayudar a reconstruir Ìwòyè, que estaba en ruinas. Fue, la ciudad se recuperó por completo y, al regresar, su esposa le dio un hijo. La casa que dejó estaba mejor que cuando se fue.", "Ọ̀rúnmìlà honra a su padre. Ọ̀rúnmìlà preguntó si sus cosas mejorarían, y le dijeron que pensara en su padre, lo invocara y le rezara durante siete días, porque los padres son como nuestros dioses. Al terminar, le llegaron riqueza, esposas, hijos, casas y propiedades. Cantaba: 'Si me levanto, honraré a mi padre; honrar es lo que hacen los mayores'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: pescados y doscientos ẹka.", "Los agricultores: cuatro chivas y 8,000 cauríes; al llegar tarde, ocho chivas y 16,000 cauríes.", "Siete días de invocación al padre o a la madre fallecidos, sin salir de casa."]}, {"titulo": "Relaciones espirituales", "texto": "Odùduwà fija la buena posición de cada persona. Àgbọnnìrègún aconseja a los agricultores. El padre o la madre difuntos son los primeros a quienes se invoca."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pescados, chivas. Las estaciones de lluvias y de secas como orden del mundo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 79.1 (yorùbá): \"Kafinudidun ṣee\", / \"Enimaalo-komaalo / Enimaadẹhin-kodẹhin Dandan / èniyàn liayan ki wọn mure'losayé\", / Morantan awo Ọ̀rúnmìlà: / li ó dífá f' Ọ̀rúnmìlà. / Ó ni: \"àwọn qmo-aráyé / nbọwa biileere orọ kan\". / A niki Ọ̀rúnmìlà rúbọ: / Eja, igbá èkọ. / Ọ̀rúnmìlà gbó ó rú. / Nüjokan, àwon oriṣẹkú, / or'emèrè, ole / ati gbogbo àwọn èniyàn / majẹkit'èniyàn-sunwọ̀n gbarajo / wọn tọ Ọ̀rúnmìlà wa. / Wọ̀n ni: Ipaara ayé yi su wa Ọ̀rúnmìlà! / Nitorinaa kiojowẹ jẹki a simi si ğrun. / Ọ̀rúnmìlà I: / ẹyin kole ṣaimaa paara òde-ayé titi eyin / o fi de ipo rere naa ti Odùduà / ti yan fun gbogbo èniyàn. / Lẹhinna li eyin yoo simi si òrun. / Wọ̀n ni: / Kini ipo rere naa? / Ọ̀rúnmìlà niki ẹ jéwọ̀ òbùn. / Wọ̀n ni: A jéwọ̀ òbùn, / Olúwa dáṣo ró wa. / Ọ̀rúnmìlà ni: / Ipo rere naa li ayé-Amotan ohungbogbo, / ayọ̀ nigbagbogbo, / wiwa laisi ominu tabi ibèrú ọ̀tá, / ija-ejó tabi eranko buburú miran, / laisi iberú ikú, àrùn, ejo, / ofo, oṣó, àjẹ tabi Eṣú, / laisi ibèrú ifarapa omi iná, / ewé oro tabi iwo, / laisi ibẹrú aini tabi oṣi, / nitori agbára inú yun, / iwàrere ati ọgbón. / Nigbati ẹko jale mọ / nitori irora tio wa ninu rẹ / fún olúwa ohun-ini naa / ati mimo abukù tio wa ninu iwà yi / fun wa niwaju Oduduà / ati àwon ẹgbẹ rere miran / ti o wa ni ọ̀run ti nba wa ṣ'ọrẹ, / ti wọ̀n si nfẹ ire si wa, / pe wọn o kọ wa silẹ. / Ao pada sinu òkùnkùn ayé, / a ko niiri àwon ẹgbẹ rere na mọ / tabi iranwọ wọn, / pe ao san ohun naa tiaji pada dandan. / Mimope bẹẹ ni iwaburúkú gbogbo / ni akowaba, / ewu ati abukù wọn ni otoọto, / ohun ti yoo gbe wa de ipo rere naa: / Ọgbọ̀n ti o pọ to eyiti a le fiṣe akoso ayé, / irúbo tabi iwà iferan ooreṣiṣe / fún gbogbo èniyàn tiiṣe alaini / tabi ti o nfẹ iranlowo lodo wa, / itara fun tabi sisa ipa lati fi kun ire tiowa / li ayé laijẹki ire tia ti ni lọ. / Àwọn ènìyàn yoo maa losi run / wọn yoo si maa padawa s'òde ayé / lẹhin iparada (ikú) wọn, / titi ẹnikoçkan wọn yoo fi de ipo rere naa. / Opolopo ohun rere liowa / li òrun ti ayé koitiini / ti ayé yoo si ni dandan. / Nigbati àwon pmo Odùduà pejẹ, / awọn ti o yan lati ko ire wasi òde ayé / Il a npe ni: / Eniyàn.", "Verso 79.2 (yorùbá): alje ikorò diẹ sil\" / u hile Eniti / \"ave / Họ̀ lẹ̀ Iponju ri komp adún gro\": / a daa fan awgn Agbọ̀ ti nwipe: / “gbogbo igba ayé iba jẹ kiki òjò, / aye iha don-adüntán\" / Wọ́n ni àwọn a rúbọ / ki Bara Àgbọnnìrègún / Jowp ye gba wọn. / Ọ̀rúnmìlà niki p wa rúbo / nitori wèrè yin / ati pe ki ayé le maawa / bi Oóduà tida ayé si, / labà-òjò ati igbà-èrùn kioma tase. / [bọ: Ewúrẹ mérin, / egbàárin owó ati bẹẹbẹẹ. / Wọ̀n ko rúbọ. / Ọ̀rúnmìlà wa jẹki ojò rọ̀ pupo / li odún naa titi a ko firi oorun rara, / Èniyàn bẹrẹsii Ṣ'okünrùn. / Wọ̀n si kú pupo ninu odún naa, / ohun-ògbin ati bẹẹbẹẹ ko dára. / Wọn pada wa rúbo pẹlu ẹbẹ. / Ọ̀rúnmìlà ni: eru goke. / O di mẹjoméjẹ, ewúrẹ di mẹjo / ati egbàájo owó.", "REZO: IROSO WORI IROSO NI BAYE NI BAUN NI TENSHE NI ALODAFUN AYO OMO ODDE, MAFEREFUN SHANGO.", "REZO: OSHE BINI LLERO ADIFAFUN LOKOSO YAYU AKUKO LEBO OSOGUERE IROSO NI BALLE NI BAUN TANCHE NI OLODAFUN ALLO OMO ARDE MAFEREFUN SHANGO.", "REZO: IROSO IWORI IFA LA PASA NIPAO TALE LOLLU CODO SU ADONILLE OLORDAFUN INTALE ORGAN EYELE ACHERERAN MEDILOGUN ICOBERE."]}]$q$::jsonb),
(80,'087cf34b3e13803cda323d8878bccf1f',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ìdí habla de una persona con don para curar y sanar; si no trabaja en salud o sanación, debería considerarlo. También da soluciones para lograr un embarazo. Las cosas están difíciles por ahora, y la ofrenda sirve para adelantarse a los momentos duros. Si hay dos parejas o dos esposas, debe tratarlas por igual."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja en el cuidado de la salud o piensa formarse para cuidar a otros (relato de Ìrosùn y las heridas).", "Tiene una herida o dolencia que no debe descuidar.", "Desea tener hijos (relato de la mujer llamada Ìrosùn).", "Viene una etapa difícil y debe prepararse antes de que empeore (relato de Olósùn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Talento para sanar: las heridas que cura, sanan.", "Una mujer que deseaba ser madre lo logra.", "Salir de la pobreza: dinero, pareja, hijos, casa y paz.", "No volver a pasar tiempos duros."]}, {"titulo": "Ibi y advertencias", "puntos": ["Penuria y cosas que no se resuelven.", "Favorecer a una pareja y abandonar a la otra: deja odio entre los hijos para siempre."]}, {"titulo": "Enseñanza principal", "texto": "El que tiene dos familias no debe oprimir a una para consentir a la otra. Látalápò, padre de las ratas, abandonó a la madre gato; por eso hasta hoy los gatos persiguen a los ratones."}, {"titulo": "Relatos reunidos", "puntos": ["Ìrosùn, el que cura heridas. Bimobawondi-a-sàn consultó para Ìrosùn y le aseguró que toda herida que curara sanaría. Le marcaron vendas, pescado ahumado, 14,000 cauríes y medicina de Ifá, y se convirtió en médico. Si el signo sale en la ceremonia de un recién nacido o en la iniciación de Ifá, la persona puede dedicarse a curar heridas.", "Ìrosùn quiere ser madre. Ọja-abiamo-aditu consultó para Ìrosùn, que deseaba ser madre, y le marcó dos murciélagos, dos ratas de campo y 20,000 cauríes. Ella ofreció.", "Olósùn y el cordón roto. Olósùn vivía en franca pobreza y preguntó si sus cosas mejorarían. Le prometieron que no volvería a pasar tiempos difíciles si ofrecía un cordón largo de cuentas rotas y un chivo. Cumplió, y su vida cambió pronto: tuvo dinero, esposas, hijos, casas y tranquilidad. Cantaba: 'Ya disfrutamos la buena vida; los tiempos duros no volvieron'.", "Látalápò, el gato y la rata. Látalápò, padre de las ratas, se casó primero con la madre gato, que le dio muchos hijos. Cuando tomó a la madre rata como segunda esposa, dejó de visitar y de cuidar a la primera. Los hijos de las dos crecieron juntos, y un día los gatitos vieron a su madre arrinconada y despreciada. Ella les explicó que su padre la había abandonado. Poco después, los hijos gato rodearon a los ratones y empezaron a cazarlos uno por uno. El padre corrió con sus babaláwos, pero ya era tarde: desde entonces hay enemistad entre gatos y ratones."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para sanar: vendas, pescado ahumado, 14,000 cauríes y medicina de Ifá.", "Para ser madre: dos murciélagos, dos ratas de campo y 20,000 cauríes.", "Para salir de la pobreza: un cordón largo de cuentas rotas y un chivo."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá entrega al hijo de este signo el oficio de curar. El cuidado de la familia completa es parte del trato con Ifá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ìrosùn (Baphia nitida o Pterocarpus osun) maceradas en agua con iyẹ̀-ìrosùn del signo, para lavar los ikin de la persona. Vendas, pescado ahumado, murciélagos, ratas de campo, cuentas, chivo. Si hay problemas para embarazarse, conviene también ir al médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 80.1 (yorùbá): Bimobawondí-a-sàn: / a difá fún Irosù. / Wọn nì: \"gbogbo pgbẹ / ti Irosù nba wọn dí a san\". / Ki ó rúbọ: / qja-ikalẹ-idimo, eja-arẹ, / ẹgbàájé ewo ati ewé Ifá. / Öun yoo di Oníṣègün. / Biobaṣe ni Ẹsẹntayé t / abi ni ltẹfá li a daa, / Egbo ni oun yoo maa ri wo ju.", "Verso 80.2 (yorùbá): Qja-abiamo-aditu: / li o difá fún Irosù, / wọ̀n ni ki o wa rúbọ / kio baa le di Abiamo. / Adán Méjì, eku-ẹmọ Méjì, / ẹgbàáwa owó. / O rúbọ.", "REZO: IROSO DI MANDULAIN ATI EINTOSHE OUN OME ORUNMILA. ADIFAFUN ORUNMILA KEWAYE.", "REZO: ALLAU CORO ADIFAFUN ELLA ELEBELE LEBO LLAMI EGUE FAE", "REZO: ÑAMU ÑAMU, EITANE ONI OKA OGUARAMO KORA GUAÑA OSUA.", "SUYERE: OSUPOKA SUPUERE ORUNMILA SUPUERE OSUPOKA SUPUERE ORUNMILA SUPUERE AWO."]}]$q$::jsonb),
(81,'238a42ed94f4e08cb4a7f34fa5cd57de',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ọ̀wọ́nrín anuncia prosperidad que ya viene en camino, pero pide ofrendar para no perder la paz y la armonía por pleitos que pueden llegar junto con el éxito, con familiares o amigos. La persona encontrará su fortuna si sigue un camino recto; otra persona mira el mismo camino. Trae pareja para el que la busca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera éxito, pero teme pleitos con la familia o los amigos después.", "Un grupo necesita paz para evitar peleas internas (relato del pueblo de Alẹde Owa).", "Pregunta por un buen año para el dinero y los hijos (relato del pueblo de Ifẹ̀-Ooyẹ).", "Busca pareja (relato de Àpón Àko y Àgàn Ifẹ̀)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un año de buena fortuna en dinero y en hijos.", "Paz mental y evitar pleitos o guerras internas.", "Encontrar pareja: el soltero y la mujer sin esposo se encuentran en el cruce de caminos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Pleitos y rupturas que llegan después del éxito.", "Casarse sin conocer el pasado de la pareja.", "Infidelidad que causa escándalo y conflicto."]}, {"titulo": "Enseñanza principal", "texto": "El éxito también trae envidias y pleitos; la ofrenda protege la paz de la casa. En el matrimonio la fidelidad evita el desorden, y el soltero debe conocer bien a quien va a tomar por pareja."}, {"titulo": "Relatos reunidos", "puntos": ["El pueblo de Alẹde Owa. Ifá consultó para el pueblo de Alẹde Owa y le pidió dieciséis palomas, una carnera, dieciséis caracoles babosa y 16,000 cauríes (o 160,000) para tener paz y evitar la guerra civil.", "Ifẹ-Ooyẹ. Erintunde consultó para el pueblo de Ifẹ-Ooyẹ y anunció un año de buena fortuna en dinero y en hijos. Ofrecieron una carnera, una paloma y 16,000 cauríes.", "Àpọ́n y Àgàn se encuentran. Ifá consultó para Àpọ́n de Àko, un hombre maduro y soltero que lloraba por no tener esposa, y para Àgàn de Ifẹ, una mujer que no hallaba buen esposo. A los dos les pidieron ofrendar. Cada uno llevó su ofrenda al cruce de caminos y rezó: 'Creador, déjame hallar una buena pareja y que ella me halle a mí, para tener paz'. Mientras rezaban ahí, se encontraron.", "Áwèlé, la infiel. Ifá consultó para Áwèlé, una mujer casada que olvidó la fidelidad: coqueteaba en su casa y se acostaba con vecinos, parientes, viajeros y extranjeros. Le preguntaron si iba a alborotar toda la comarca con su conducta. Por eso Ifá pide a la persona mucho cuidado para que su sexualidad no le traiga conflictos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la paz: dieciséis palomas, una carnera, dieciséis caracoles babosa y 16,000 o 160,000 cauríes.", "Para la fortuna del año: una carnera, una paloma y 16,000 cauríes.", "Para hallar pareja: ofrenda en el cruce de caminos."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá une a quienes ofrendan en el cruce de caminos. Ningún otro Ifá dice la verdad como Ìrosùn Ẹlẹ́rin."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Palomas, carnera, caracoles babosa. Aceite de palma colado, para comer con ñame y con vegetales."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 81.1 (yorùbá): rosd wọ̀nrin wọ̀nrin, / Irosd wọ̀nrinwọn: / a difà tún wọ̀n l'Alẹde Qwa, / a niki wọ̀n wa ṣebọ: / eyẹle mẹrindilógún, àgutàn, / igbin mẹrindilógún / egbàájo tabi okẹ méjọ owó. / Kiwọn baa le rojuraye maa kọ ilé wọn / ki ijà ma baa ṣẹlẹ laarin ara wọn.", "Verso 81.2 (yorùbá): Erintunde, a ri're, / a daa fún wọn n'lfẹ-Ooyẹ. / Wọ̀n ni: / \"odún eni odún owó, / odún eni odún ọmọ\". / Àgùtàn, ẹyẹlé / ati ẹgbàa méjo owó ni ebọ. / Wọ̀n rúbọ n'lfẹ̀-Ooyẹ.", "REZO: ANABORO ONA ODO ADIFAFUN ORULOLLO EYELE ONI OKO DUN DUN EKO EBEFA OWO LEBO OWO MEFA.", "REZO: IROSO JUANI ANABORO ONA ODO ADIFAFUN ORU LEYE EYELE OÑI OKO DUN DUN, AKUKO LEBO, EWEFA LEBO.", "REZO: IROSO JUANI ALABULI LAMPE SHANGO ADIFAFUN OKIDI UMBATI LOSO LOSO OYO INLE, LORUGBO ABO LEBO, ETU MEYI, AWO MAYI, OWO TENTEBORU SHANGO AINA LOKE MANO LOKE, LODAFUN SHANGO."]}]$q$::jsonb),
(82,'8eac248776a6dbc12041799f4f213cd7',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ọ̀bàrà habla de compartir y dar a los demás para asegurar la prosperidad y la felicidad. Una próxima reunión u oportunidad de negocio saldrá bien. Aunque la persona esté bien de dinero, no debe rechazar regalos pequeños, porque ofende a quien los da y esos regalos le ayudan a progresar. Conviene tener siempre bebida para un visitante inesperado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene cerca una reunión o una oportunidad de negocio (relato de Oyinbo y sus productos).", "Puede enseñar o ayudar a otros y se pregunta si aceptarán lo que sabe (relato de Ọ̀rúnmìlà en Òtù-Ifẹ̀).", "Tiene recursos, pero puede despreciar algo pequeño o invertir sin pensar (relato de Tètèrègún y la jícara)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Éxito en un negocio o en una reunión.", "Ser un buen maestro y que la gente acepte sus enseñanzas.", "Vender en abundancia.", "Bendiciones de los ancestros que llegan de visita sin ser reconocidos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ser tacaño con conocidos o familiares.", "Desairar a quien llega con poco o con un regalo pequeño.", "Enemigos que hablan en contra."]}, {"titulo": "Enseñanza principal", "texto": "Tener fortuna no impide seguir juntando. Olókun es inmensa y no se hace más chica porque Tètèrègún tome agua con su jícara; dar no empobrece. Y a quien recibe bien al visitante le llegan las bendiciones que traen los que vienen del cielo."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà enseña en Otù-Ifẹ. Cuando Ọ̀rúnmìlà iba a Otù-Ifẹ a enseñar a la gente de la ciudad y del campo a ser buenos vecinos, le dijeron que sería un buen maestro y que aceptarían sus enseñanzas. Antes de viajar ofreció mucha nuez de kola amarga, hojas de ọgbọ̀, plátanos y 16,000 cauríes.", "Oyinbo vende en abundancia. Ifá consultó para Oyinbo, el hombre blanco, y le pidió un puñado de sal, una gallina blanca, una paloma blanca y 20,000 cauríes para vender mucho. Ofreció y se hizo próspero.", "Tètèrègún y Olókun. Tètèrègún usaba una jícara pequeña para sacar agua de la riqueza de Olókun, el mar, que desde siempre ha sido enorme porque todos los ríos le llegan. Alguien le preguntó a Olókun si no le molestaba. Olókun respondió que, aunque el otro tomara, ella no se hacía más pequeña. Tètèrègún regresó rico a su casa.", "Ègà y los padres que vinieron del cielo. Agbe, Àlùkò y el pájaro Ègà vivían en la tierra y sus padres ya habían muerto. Ègà era sacerdote y cada año celebraba su fiesta de Ifá. Un año los padres decidieron visitarlos desde el cielo, pero como los vivos no pueden ver a los muertos, llegaron con la cara y el cuerpo de otras personas. En casa de Agbe pidieron vino y les dijeron que ya no había. En casa de Àlùkò solo quedaba el asiento en las jícaras. En casa de Ègà los recibieron con mucha comida y vino. A él solo le dejaron todo lo bueno que traían del cielo, y su vida se volvió muy cómoda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: mucha nuez de kola amarga, hojas de ọgbọ̀, plátanos y 16,000 cauríes.", "Oyinbo: un puñado de sal, una gallina blanca, una paloma blanca y 20,000 cauríes.", "Tener vino y comida para recibir a quien llegue."]}, {"titulo": "Relaciones espirituales", "texto": "Olókun representa la abundancia que no se acaba. Los ancestros visitan a sus hijos y bendicen al generoso. Egúngún se honra en la fiesta de Ègà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nuez de kola amarga, hojas de ọgbọ̀ (Nervilia umbrosa o Parquetina nigrescens), plátano, sal, gallina blanca, paloma blanca, vino de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 82.1 (yorùbá): Bufúnmi-ki-mibufún o, / Ayé a maa gun, / a daa fOrúnmilà / nlọ s'Otu-Ifẹ, / o maa kowon ni iṣe ilé, iṣe oko. / Wọ̀n nì: / Ọ̀rúnmìlà a wifún wọn, / wón a gbọ̀. / Sùgbọ̀n kio wa rúbo / kiotoo maa lowi fún wọn / ewé qgbọ̀, gèdẹ̀ àgbagbà ati ẹgbajo owó. / Ọ̀rúnmìlà rúbọ. / \"Una vida de dar y recibir / hará del mundo un lugar más placentero para vivir\":", "Verso 82.2 (yorùbá): Ọmọ ko Alajé, / ota nta wàrà, / a dífá f'Oyinbo / A niki Oyinbo wa rúbo / a maa ta pupqju. / Ebọ: lyọ igbio, / adiyẹ-funfun, eyẹlé funfun, / egbàáwa owó. / Oyinbo gbó ó rú. / O di Alajé.", "REZO: IROSO BARA IRESEGAN OPE KUFIRIWO ILU ADO LODIFA KOLARA OSHA WONNI AYA RAMI OMA FE NI ODDUN NI AMA BASHE KUPA CURE ELEBO.", "REZO: AQUITI POGUE AWO EBANA ADIFAFUN OLOFIN EYELE LEBO TETE OLA ADIE ELLELE LEBO. IROSO IFA ADIFAFUN ABADI LOFO IGRE.", "REZO: IROSO BARA LORI OFO OKO OYORE INTORI ORUNMILA LORI OMA LORI NIKU LORI EYO.", "REZO: IROSO BARA, IROSO EGAN OPE KUFIRIFUGUN LA ADOLODIFA KOLARA ISHAGUIOMI AYA RAMI OMAFE MI ODDUN MAMA BASHE IKUPA AURE LEBO. EJELOGUN OWO LEBO. AIRA COMBO AKUSIN MABIYA KOSUOLOBO NIMON SINSI BAYI NI ALARA BEBE SHINSHE INSHE TUSI BERESIMI LOKUO LORIFA ONIRA.", "REZO: AKITI NOGUE AKUO ABANA ADIFAFUN OLOFIN EYELE LEBO TETE IFA OLA ADIE EYELE LEBO IROSO IFA ADIFAFUN OBADI LOFO IGRO."]}]$q$::jsonb),
(83,'d6b1baaf9dc9815aaacf4b736cc96f1d',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ọ̀kànràn llama a la persona a valorarse y a defender sus derechos. Suele ser tímida, retraída y fácil de dominar; necesita ánimo para imponerse y vencer el miedo. No debe dejar su puesto o su cargo, ni siquiera por un tiempo, en manos de nadie que no sea su propio hijo, porque lo perdería para siempre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Es tímido, le cuesta imponerse o deja que otros decidan por él.", "Debe saber quién puede perjudicarlo sin acusar por simple sospecha (relato del gato Ologbo).", "Piensa ceder un puesto y luego le puede costar recuperarlo (relato de Òkèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vencer los obstáculos y a los enemigos.", "Una mujer de la que dicen que ya no puede tener hijos, los tendrá.", "Conservar su lugar cuando no lo presta."]}, {"titulo": "Ibi y advertencias", "puntos": ["Aguantar insultos sin defenderse: solo se come sufrimiento.", "Prestar el cargo 'por un rato' y perderlo.", "Creer lo que dice la gente sobre la esterilidad."]}, {"titulo": "Enseñanza principal", "texto": "Quien no se defiende de los agravios termina comiendo aflicción. Y quien dice 'déjame manejar esto por ti un tiempo' puede quedarse para siempre con lo ajeno: así perdió Oníṣakí su trono."}, {"titulo": "Relatos reunidos", "puntos": ["El gato, hijo de adivino. Ifá consultó para Ologbo, el gato, cuando decidió vencer todos los obstáculos y a sus enemigos. Le marcaron cuchillos, pimienta de guinea, 22,000 cauríes y medicina de Ifá.", "Òkèrè y el trono de Ṣakí. Òkèrè andaba cazando por el bosque, subiendo y bajando colinas, hasta que llegó a Ṣakí. Se quedó ahí y empezó a ayudar al rey Oníṣakí en algunas funciones, hasta que tomó el mando por completo. Oníṣakí luchó mucho por recuperar su trono, pero ya era tarde, y es Òkèrè quien sigue en él.", "La mujer que dijeron estéril. La gente aseguraba que una mujer ya no tendría hijos en la tierra. Ọ̀rúnmìlà dijo que esa mujer los tendría, porque los hijos no se compran, pero con la ofrenda y las medidas correctas llegan a cualquier edad. Ella ofreció y tuvo sus hijos. Ifá dijo que lo que decía la gente eran mentiras."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para vencer: cuchillos, pimienta de guinea, 22,000 cauríes y medicina de Ifá.", "Para tener hijos: la ofrenda que marque Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà defiende a la mujer de la que dudan. Ifá da valor al tímido."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cuchillos, pimienta de guinea. Si una mujer busca embarazarse a edad avanzada, conviene también la consulta médica."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 83.1 (yorùbá): Olúkònràn-iwosi, / Olúkoya-iwosi. / Eniti ko le koya iwosi, / iya kiiyewon i jẹ: / a daa f'Ologbo omo-awo. / Ologbo 1 / òun maa ṣégun òdí, / òun maa ri ẹhin tá. / A niki ó wa rú: / Ọbẹ, ataare, / ogbokànlá owó ati ewé Ifá."]}]$q$::jsonb),
(84,'9560cdb2c4c551ba22d423693f64c99a',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ògúndá subraya el valor de la ofrenda y del uso de las plantas medicinales, pide no hacer el mal y cultivar el buen carácter. Las cosas no están fluyendo. Ifá le desea una buena pareja: no debe separarse de la que su Orí escoja, porque con ella tendrá a sus hijos y con ellos llegará la riqueza. Dos personas deben ofrendar para no caer en una pelea sin sentido."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que sus asuntos no fluyen.", "Al buscar salir de un problema debe evitar la soberbia y el maltrato (relato de los dos cazadores).", "Una unión de pareja puede traer los hijos que desea (relato de Ọ̀rúnmìlà y Olósùn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Esposa e hijos; prosperidad con la llegada de los hijos.", "Éxito en lo que emprende, como el cazador del cielo.", "Salvarse de una guerra o de un pleito entre otros."]}, {"titulo": "Ibi y advertencias", "puntos": ["Mandar mensajes malos a Èṣù: tienen consecuencias.", "Divorciarse de la pareja que eligió su Orí.", "Comerse lo que encuentra sin preguntar: perder la fortuna escondida.", "Dos personas que se pelean por un malentendido."]}, {"titulo": "Enseñanza principal", "texto": "Dios no obliga a nadie a ofrendar, pero el que quiere triunfar ofrenda. Solo Dios es dueño de la prosperidad y la reparte a quien quiere. Ọ̀rúnmìlà enseñó el hábito de bañarse cada cuatro días y frotarse el cuerpo con osùn."}, {"titulo": "Relatos reunidos", "puntos": ["La gente malvada y el baño. Ọlọ́run mandó a las personas ofrendar y Ọ̀rúnmìlà les enseñó a usar la medicina; las ofrendas se piden a Elegbara para que las lleve a Olódùmarè. Òrìṣà-ńlá pidió no mandar a Èṣù recados malos por lo que traen de regreso. Ofrecieron cuatro palomas, jabón negro, osùn y 3,200 cauríes, y desde entonces se acostumbra bañarse cada cuatro días y untarse osùn.", "Los dos cazadores y los huevos. A Ọdẹ-ayé, el cazador de la tierra, y a Ọdẹ-ọ̀run, el cazador del cielo, les pidieron cuatro palomas y 8,000 cauríes para tener buena cacería. Solo el del cielo cumplió. Un día este encontró cinco huevos bajo unas hojas; dejó dos en un cruce de caminos y le avisó a su compañero que ahí le había dejado algo. El de la tierra, que no había cazado nada, se los llevó contento, los coció y se los comió. Al día siguiente, el del cielo encontró 20,000 cauríes debajo de cada huevo que guardó. Cuando el otro le contó que se los había comido y que estaban deliciosos, le dijo: 'Se acabó; tú nunca prosperarás'.", "Ọ̀rúnmìlà y Olósùn. Ọ̀rúnmìlà ofrendó antes de casarse con Olósùn, y ella tuvo incontables hijos a los que frotaba con osùn: tantos como los monos del bosque, las hormigas soldado y las hojas caídas.", "Los tambores de Olúwẹri. Wááwá, el cazador de la tierra, y Gbúèdè, el cazador del cielo, vieron los peces del río Ijámọ̀ desde orillas opuestas y quedaron de volver en cinco días a pescar. Ese mismo día Olúwẹri soñó pesadillas y su babaláwo, Àtàpásùú, le pidió ofrendar para que una guerra no se llevara a sus hijos: tres chivos, a los que se quitaría la piel, muchos racimos de plátano y manteca de cacao, puestos con un fuego pequeño en la orilla antes del amanecer. Cada cazador vio la fogata, creyó que el otro se le había adelantado y se fue enojado; empezaron a mandarse mensajes de guerra. Con las pieles, Olúwẹri armó tres tambores, el grande, el mediano y el chico, y así sus hijos se salvaron de la calamidad en el río."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Cuatro palomas, jabón negro, osùn y 3,200 cauríes.", "Para la cacería o el trabajo: cuatro palomas y 8,000 cauríes.", "Olúwẹri: tres chivos (con sus pieles se hacen tres tambores), racimos de plátano y manteca de cacao, en la orilla del río antes del amanecer."]}, {"titulo": "Relaciones espirituales", "texto": "Elegbara (Èṣù) lleva las ofrendas a Olódùmarè. Òrìṣà-ńlá pide no usar a Èṣù para el mal. Olúwẹri, el espíritu del río, protege a sus hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Jabón negro, osùn (madera roja de Angola) para frotar el cuerpo, plátanos, manteca de cacao, pieles de chivo para tambores."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 84.1 (yorùbá): Ajá sian titifide ehin enu wọn, / Agbo sian titifide jojẹ: / a difá f'awa Èniyàn ni'kà / Ọlọ̀run li o wipe ki àwọn omọ-aráyé / maa ṣebọ Ọ̀rúnmìlà / li o pe Oògùn ni sisa. / Ó ni bi àwọn omọ aráyé / baṣẹ'bọ tán, / ti wọn tu erutan, / ki wọn wipe ki Elégbárá / jowọ ba wọn gbe ebọ de / odo Olódùmarè. / Ọlorun ko torọ ebọ / bẹẹni ko beere eru, / eniti nwa ire niiṣebo. / Òriṣà-nlá li o wipe / ki omo-aráyé mamaa ran Èṣú / ni iṣé ti o buru o / nitori ajadẹhinbo. / Eyẹlé mẹrin, awẹnu, osùn / ati ẹgbàá mẹrindilógún owó li ẹbọ. / Wọ̀n rúbọ. / Lati ọjo naa li Ọ̀rúnmìlà ti kọ èniyàn / li asa iwẹ qjọ mẹta, / ojọ márùn ati if'osùn p'ara. / Para un perro es agradable / los dientes en su boca, / Para un carnero es agradable / sus cuernos:", "Verso 84.2 (yorùbá): Ekitipẹtẹ: / a dífá f'Odẹ-ayé / a bu f'Odẹ-orun, / A niki wọ̀n rú: / Ẹyẹlé mẹrin ati egbàárin owo / ki oko-odẹ ti wọn lọ le san wọn bọ. / Qdẹ-ayé ko rú, / Odẹ-orun li o rú.", "REZO: IROSO TOLDA OBATALA MOWAYENI AIYE GBOGBO ORISHA EWUNYIARA OKUN OLOKUN ORE OSHA YANYA AGUEMA OPA OÑI INA ADENU EÑI OLOKUN ABAKUA OBATALA LODAFUN OSHA ODONU KAFEREFUN SHANGO.", "REZO: AGRIO AMUBO OBIBO ALLABO OBIBO MUCHEREBO OMUBO OMA ANDIFA YECAN FUN OBATALA ACHEREREBO LUGUA AUN ARAYE TIONIFE.", "REZOS: KAFORESHE ERACO CAMA FORECHE ENA ADIFAFUN OGGUN AKUKO EFUN EWE TETE AÑIO TOTO GUELETE EMIFE ADIFAFUN CONGO APOLO UMBATI LOYOBE AYIBO EYELE LEBO. MAFEREFUN OGUN MAFEREFUN SHANGO.", "REZO: IROSO TOLDA KAFEREFUN OLOKUN, OBATALA,INLE Y OSHUMARE."]}]$q$::jsonb),
(85,'0567a639590070f3f8881743768c0f99',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ọ̀sá habla de la importancia de la ofrenda para superar obstáculos y vencer a los enemigos. Suele haber gente conspirando para estorbar a la persona. Pide ofrendar a Orí con un pescado grande y no olvidar nunca a quienes le han hecho bien."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente oposición a un proyecto y debe confirmar quién y cómo lo frena (relato de Ọ̀rúnmìlà ante los obstáculos).", "Busca protección y guía para una decisión importante (relato de la elección de Orí y carácter).", "No debe olvidar a quienes lo han ayudado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vencer a los enemigos y superar los obstáculos.", "Buen Orí y buen carácter.", "Poder y reconocimiento, como Ṣàngó después de su iniciación."]}, {"titulo": "Ibi y advertencias", "puntos": ["Personas que conspiran para obstaculizarlo.", "Olvidar a los benefactores o a quien lo inició.", "Querer todo al mismo tiempo: escoger Orí y carácter el mismo día y perder ambos."]}, {"titulo": "Enseñanza principal", "texto": "El Orí se escoge una sola vez; el carácter, la riqueza, la pareja y los hijos se escogen después, a su tiempo. Quien quiere todo a la vez lo pierde todo. El buen carácter es lo que da medida a lo que uno tiene."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà, el que vence. Ifá consultó para Ọ̀rúnmìlà y le marcó un chivo para convertirse en el señor que vence a los enemigos y supera los obstáculos. Ofreció.", "Orí en Ìdó y carácter en Èjìgbòmẹkùn. Ọ̀rúnmìlà fue a la antigua ciudad de Ìdó a escoger su Orí, y le explicaron que el mismo día no se puede ir al mercado de Èjìgbòmẹkùn a escoger el carácter: si se escoge Orí un año, el carácter se escoge al siguiente, porque al escoger uno se cierra el otro lugar. Ọ̀rúnmìlà eligió su Orí y les pidió paciencia a los hombres, pero no le hicieron caso. El que trata de escoger las dos cosas al mismo tiempo suele perder las dos. A Ọ̀rúnmìlà la vida le fue agradable.", "Gbàjà Ìròkò inicia a Ṣàngó. Gbàjà Ìròkò consultó cuando iba a iniciar a Ṣàngó en Ifá, y le dijo que haría cosas que se oirían en el cielo y en la tierra y que nadie le podría hacer frente. Lo inició, y desde entonces Ṣàngó tiene más fuerza: cuando truena en el cielo, todo tiembla en la tierra. El canto le recuerda: 'Ṣàngó, ya eres un rey poderoso; no olvides a tus sacerdotes'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: un chivo.", "A Orí: un pescado grande."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó recibe Ifá de Gbàjà Ìròkò y se vuelve más fuerte. Orí se escoge en Ìdó y el carácter en el mercado de Èjìgbòmẹkùn. Èlà es dueño del buen carácter."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Chivo, pescado grande. El trueno y la tormenta como señal de Ṣàngó."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 85.1 (yorùbá): Afẹfeṣe-orí-igi-hẹrẹhẹrẹ, / Efufulẹlẹniiti-ewé-agbon-nikoronikoro / a dífá f'Ọ̀rúnmìlà / Wọ̀n niki ó rú: / Obúko kan kiobaale ṣégun ọ̀tá, / kiobaale r'ẹhin òdi / Ó gbọ̀ ó rú.", "REZO: IROSO SA IFA PELE PELE LILE OGUELE WA GUERE MANILEI LA PUPUA OLOKIN TINSHE EFEYUDE OLOFIN MAFEREFUN SHANGO.", "REZO: IFA PELE PELE LELE SILE OGUELE RE MANILE ILA PAPA OLOFIN TOUNCHA FOLLUDE OLOFIN MAFEREFUN SHANGO.IKU CAN IMBERE CUCAN ADIFAFUN OCO ALAQUE LEBO OSU AWO ESA ADIFAFUN ESA BATIN TILOMU OSUN GUABE OYA OLORO LEBO EYELE ADIFAFUN ORA OMA OCONI ORUN AUCO LEBO, AUCO IDA OWO MEFA.", "REZO: ADIFAFUN ENINI OLUNI OMA BURUKU EMI LENI LENI ETULICORERA. ADIFAFUN ENINI FINSHERU OSHA OBATALA APOLA SOKUN SOKUN LAYE NI SHANGO SOKON MABINU UN SORO OFO LAMASHE BOGBO OBINI.", "IROSO KA", "REZO: IROSO KA BOKALA OKALA BOKIKA OTUTAN ADIFAFUN OBE AKUKO LEBO.", "REZO: BOKALA OKALA BOQUIKA OKUTAN ADIFAFUN OBE AKUKO LEBO.", "REZO: ODE OLODUMARE WA NI ILU EYE ADIFAFUN OBINI OSHUN, OLOFIN, ORUNMILA ORUBO AURE EÑI OWO LA MEYO.", "REZO: EYE LORUBO OBINI ILU KUNI OFORI BERE BERE LORDAFUN OMO."]}]$q$::jsonb),
(86,'7ba59257b24cc50c46dbbeeeb5ec4890',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ìká pide ofrendar para tener salud, paz mental y buen nombre, y para alejar la somnolencia. El negocio cuesta más de lo que debería. Esta persona viaja mucho y gana dinero fuera; no debe avisar a nadie el día de su partida, porque alguien quiere robarle al regreso. Debe vigilar también lo que pasa en casa mientras está fuera."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja mucho y su negocio le deja poco.", "Quiere que conozcan su trabajo sin perder la tranquilidad (relato de Ọ̀rúnmìlà y su nombre).", "Viaja seguido y teme que le quiten lo ganado (relato del viaje a Ìjerò).", "Tiene somnolencia o malestar y conviene revisarse (relato de Osù)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fama: su nombre se escuchará en todo el mundo.", "Buena salud y paz mental.", "Volver a salvo de un viaje con lo ganado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Robo o emboscada en el camino de regreso.", "Envidia por las ganancias.", "Alguien que quiere acercar a otra persona a su pareja mientras él está fuera.", "Una enfermedad que provoca sueño."]}, {"titulo": "Enseñanza principal", "texto": "El babaláwo debe saber de todo y cambiar de ropa según el trabajo que va a hacer. Ọ̀rúnmìlà se salvó porque se vistió de cazador, cantó como cazador y no reveló la fecha de su viaje. 'Una flecha nunca duerme dentro de su funda.'"}, {"titulo": "Relatos reunidos", "puntos": ["El nombre de Ọ̀rúnmìlà. Le dijeron a Ọ̀rúnmìlà que su nombre se oiría en todo el mundo y que todos querrían conocerlo. Ofreció pescado ahumado, una paloma y 20,000 cauríes para tener salud y paz.", "Osù y la enfermedad del sueño. Aroka-Agboka consultó para Osù, el báculo de Ifá, para que no le diera la enfermedad del sueño, que podía matarlo. Ofreció una flecha en su funda, una carnera y 44,000 cauríes. El adivino dijo: 'Una flecha nunca duerme en su vaina'.", "Ọ̀rúnmìlà disfrazado de cazador. Ọ̀rúnmìlà trabajaba en una ciudad lejos de la de su padre, Òkè Igètí, y ganaba tanto que algunos se pusieron celosos. Vieron que mandaba sus ganancias a casa y planearon asaltarlo el día que regresara. Esa noche tuvo pesadillas, consultó y salió Ìrosùn Ìká: no debía decir a nadie la fecha real de su regreso, tenía que ofrecer a Ògún toda su ropa usada y conseguirse ropa de cazador. Preparó un apirù, el espantamoscas que llevan los cazadores, y anunció que se iría en cinco días. Los enemigos mandaron cazadores a esperarlo en el bosque al tercer día. Ọ̀rúnmìlà pasó entre ellos vestido de cazador cantando un ìjálá, canto de cazadores, en el que les decía que sabía lo que tramaban. Creyeron que era un cazador valiente y lo dejaron ir. Al día siguiente lo buscaron y ya no estaba: era el hombre que cantó el ìjálá con el apirù al hombro.", "Olúáwo y su esposa Gégélóṣe. Olúáwo iba a la ciudad de Òhan a dirigir el funeral del padre de su esposa Gégélóṣe. Tenía un perro con la mitad derecha de la cara pintada de blanco y una oveja con la pata izquierda pintada de osùn. En sueños su propio Ifá le dijo que mandara al perro y a la oveja por delante. Gégélóṣe supo lo que tramaban contra su esposo y salió a buscarlo; cuando reconoció a los animales pintados, cantó un ìjálá para avisarle que no entrara a la ciudad, que no durmiera en los alrededores y que siguiera directo hasta Ìjerò. Olúáwo escuchó y se fue."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: pescado ahumado, una paloma y 20,000 cauríes.", "Osù: una flecha en su funda, una carnera y 44,000 cauríes.", "Para el viaje: ofrecer a Ògún la ropa usada y vestirse de cazador al regreso.", "Un perro y una oveja marcados que van por delante."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún recibe la ropa usada y protege el camino. Osù, el báculo de Ifá, no se duerme. El Ifá propio de la persona habla en sueños."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pescado ahumado, paloma, carnera, flecha con funda, apirù (espantamoscas de cazador), pintura blanca y osùn. Si hay somnolencia constante, conviene revisarse con el médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 86.1 (yorùbá): Iro-agogo-agboka: / a dífá f'Ọ̀rúnmìlà. / Wọ̀n ni: / \"nibi gbogbo ayiká ayé / ni wọ̀n maa gbọ orukọ re / ti wọ̀n si maa maa wa mọo\". / Wọ̀n niki ó rúbọ / ki ara le rọọ. / Ẹbọ: Eja-aro, ẹyẹlé / ati ẹgbàáwa owó. / Ó gbọ̀ ó rú. / \"El sonido de una campana / se escucha en el mundo entero\":", "Verso 86.2 (yorùbá): Aroka-Agboka: / a difá f'Osù. / A niki Osù wa rúbẹ / kio maa baa dùbúlẹ àisàn. / Kio maa baa kú. / Ebọ: ọfà inu apo, àgùtàn / ati ẹgbàá mẹjilélógún owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Qfà kiidùbúlẹ ninu apo\".", "NA", "REZO: IROSO KALU KUKUTE KUKU ADIFAFUN MALADE TINAKAYA ORUNMILA OBARABABIREGUN.", "REZO: AGUIFA NI ELLO NI TOUNLLO NI LELEFA ODAFA BARABONI REGUN ACODIE ASHO FUNFUN.", "REZO: KUKUTE KUKU ADIFAFUN MALADE TINCHOLLA ORUMILA ADIE LEBO AUCO EYELE LEBO.", "REZO: KUKUTE KUKU ADIFAFUN MALADE TINCHOLLA OBARABA NIREGUN."]}]$q$::jsonb),
(87,'8b5ff321de836da3f03c3ce6572e63e1',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Òtúrúpọ̀n advierte contra el mal carácter y da soluciones para tener hijos sanos, que no se mueran al nacer; ayuda a la mujer a evitar los abortos. Lo que le pertenece a la persona no se perderá. Si guía a otros, debe volver con todos y ofrendar a Ògún. Debe llevar a su hijo mayor a todas partes y enseñarle lo que solo él sabe."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que su mal carácter le arruine el nombre y las relaciones (relato de Ṣọ̀pọ̀nná).", "Una mujer está preocupada por un embarazo o por la salud de sus hijos (relato de Abimokú, que pasa a llamarse Mọ́lá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos que sobreviven.", "Regresar sano de un conflicto o una guerra.", "El hijo mayor que salva al padre."]}, {"titulo": "Ibi y advertencias", "puntos": ["Mal carácter que no deja que la gente hable bien de uno.", "Pérdida de embarazos.", "Ir solo a un lugar peligroso y caer en una trampa."]}, {"titulo": "Enseñanza principal", "texto": "Ṣọ̀pọ̀nná no ofrendó y se quedó con su mal carácter; si lo hubiera hecho, Ọ̀rúnmìlà le habría compuesto el carácter y su nombre sería bueno. El hijo que observa con prudencia, aunque desobedezca para cuidar, puede devolverle la vida a su padre."}, {"titulo": "Relatos reunidos", "puntos": ["Ṣọ̀pọ̀nná y su mal carácter. Pupadamofunfun consultó para Ṣọ̀pọ̀nná, la viruela, que por su mal carácter no dejaba que la gente hablara bien de él. Le pidieron una paloma sin manchas, 18,000 cauríes y medicina de Ifá para que Ọ̀rúnmìlà le diera buen carácter. Se negó, y su nombre sigue siendo temido.", "Abimokú, la madre que perdía a sus hijos. Le dijeron a Abimokú que, si ofrendaba, todos sus hijos sobrevivirían. Ofreció una tortuga y 16,000 cauríes y le pidieron cambiar su nombre a Mola, 'el niño sobrevive'. Una tortuga joven nunca muere.", "Èkó en la guerra. Ọ̀rúnmìlà iba a cruzar una tierra en guerra. Le dijeron que volvería con cosas buenas y que nada malo le pasaría si ofrendaba a Ògún. Cumplió, y le pidieron cantar 'Èkó los sacó, Èkó los devolvió', como hacen hasta hoy los que marchan.", "Akíntóhùndè y los monos. Akíntóhùndè era un cazador que sabía toda clase de medicina, pero no sabía que en el cruce de caminos de Àgbàlá había monos salvajes. Su hijo mayor quiso acompañarlo y él le ordenó quedarse; pero Èṣù le dijo al muchacho que lo siguiera en silencio. En el bosque, siete monos rodearon al cazador para vengar a los que había matado y lo retaron a luchar mientras cantaban. Akíntóhùndè fue tumbando a uno tras otro con su machete y les sacaba los ojos. Al final el mono jefe lo alzó, lo azotó contra el suelo y lo mató; luego fue por unas hojas, frotó su savia en los ojos de sus compañeros y los revivió. El hijo, escondido detrás de un árbol, vio todo. Cuando los monos se fueron, usó las hojas que sobraron y su padre volvió a la vida con la vista sana. Esas hojas solo las conoce el pájaro Èlulùú, que las busca cuando sus crías quedan ciegas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ṣọ̀pọ̀nná: una paloma sin manchas, 18,000 cauríes y medicina de Ifá.", "Para que vivan los hijos: una tortuga y 16,000 cauríes; cambiar el nombre a Mola.", "Antes de un viaje o un conflicto: ofrenda a Ògún.", "Akíntóhùndè: la ofrenda antes de salir de cacería."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣọ̀pọ̀nná es la deidad de la viruela. Ògún protege al que vuelve de la guerra. Èṣù guía al hijo para salvar al padre."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortuga, paloma sin manchas, machete. Las hojas que devuelven la vista, conocidas por el pájaro Èlulùú. Ante embarazos que se pierden, la mujer debe atenderse también con su médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 87.1 (yorùbá): Pupadamofunfun: / a dífá fún Ṣọ̀pònná / Af'olúgboroda'ju-òràn-rú / A ni lwàburúkú / koniijeki orukọ rẹ / sunwọ̀n lẹnu ayé. / Wọ̀n niki ó wa rúbọ / ki Ọ̀rúnmìlà le baa yanju iwà rẹ̀. / Ẹbọ: Ẹyẹlé (tikiise adikala), / egbàásan owó / ati ewé Ifa. / Ṣọ̀pònná ko rúbo. / Ibaṣepe o rúbo naa / Ọ̀rúnmìlà iba baa yanju iwà rè / ti orukọ rẹ̀ iba fi sunwọ̀n lenu ayé.", "Verso 87.2 (yorùbá): Irosù'Túrúpòn: / a dífá f'Abimokú. / A niki Abimokú wa ṣẹbọ. / Abimokú maa bimo / la a tun maa pòn qmọ. / Ẹbọ: Ìjapá / ati egbàájo owó. / Ó gbó ó rú. / Wọ̀n ni: / \"oruko rẹ di \"Mola\" lati oni lo o. / To, Abariwon! / Abawun kiibimokú.", "REZO: IROSO TRUPON IROSO TUTU ABERENI KOYO WANWADORO IFA YOKAFUN YEMAYA OBADORO AWO IRE BAYENI SHANGO AWO MARO ELEDE AFOFO LOKUNYODE WAWA YERE ABEBE LAYE IFA.", "REZO: BIÑA BAROMI OCU ADIFAFUN IROCO ORUBO QUINI INA COMAGUA LLOGUN OMI LORUBO ODUN DUN OLLORO PETE AIKORDIE EYELE ETU EBETA OWO CAMIQUE AWO OLLARORUN ADIFAFUN LORUMA AMACANCA NIFE EYELE LEBO OYA ORO.", "REZO: IROSO TUTO ODARIANIGUO LAYABA ANI FOKELEKE ASHUMI KAYE WA JEKELALE AWO BARAYENI IFA ARUN OBINI IFA OFAKEYAWANI ODE IRO TRUPON ROSO TUTO ONI BABALAWO YEKUN ODE IFA AWADE IFA IROSO TUTO IBANI LAYE, NISHA SHANGO OBANILAYEBE AWA LAYEBE YEMAYA IROSO BAIFA BATRUPON INLE LEYEKUN LODE OBAYEBE IROSO OJUANI BATRUPON IFA OFO, OFO LAYE BENUN ARUN.", "REZO: ERINLA LELEYA ENISO OKO OKOLELE AWO AGBODE AFINISUN LENI KAEBOMBONGOBO NOOWI AHIKATE O SINTESIN XONIDAFUN AJE ALATESI LO NISE ASARIN KANKAN ARIBI MAMAYO WEN OFIWERE NAGBEBE LOWO WA A EJILOPA ADOMI FALOWINI IYAN YIMA NA OMO ANOGAJA IDI DAFE OMUDAWO OKO MADOPO OMONI TIOBON OMO ENI TIKO MOKA NIMON LIGOJINAPA NIBEN WAYE SU ONIYUBONA OMO KAMBE LONA OKO SHURURONMILE ASHAGUTAN MEYI NOGBE OMO ONI LE MATUKALE AFIGSA TOWO DAZARUN OKO NIMO FOMA FOMO ENRILOLO ADIFAFUN ORUNMILA MAFEREFUN OGGUN.", "REZO: BABA AWA YEIFA ABORI BODEKE OMO AWO ALARA WEWERE IFA AWO OMO ABONI EGGUN OBE KERELEI AWO OYEYE YEKUN INLE OBA ORO SHENSHE OKUN TLIRE IBA IBOYE ETI EGGUN OBARIE OZAIN TINSHARE IFA IROSO BATUTO IRE ABERI BOYE ELESE OZAIN IRE ABERIBOYE EGGUN OWE OMO ALARA IFA NI ORUN.", "REZO: MEKUA EIYE BURUKU ADIFAFUN BATUTO EKPA, ATEKUE, EWE BABARI, ATI IYARI EBANILODO MEJOUN ITA LENI META, LEKUA", "EBA AGBANIREO ADIFAFUN ABIKODUN ONI SHANGO ONILAGBABA LODAFUN ORUNMILA.", "REZO: IROSO TUTO ODARIANIGUO LAYABA ANI FOKELEKE ASHUMI KAYE WA JEKELALE AWO BARAYENI IFA ARUN OBINI IFA OFAKEYAWANI ODE IRO TRUPON ROSO TUTO ONI BABALAWO YEKUN ODE IFA AWADE IFA IROSO TUTO IBANI LAYE, NISHA SHANGO OBANILAYEBE AWA LAYEBE YEMAYA IROSO BAIFA BATRUPON INLE LEYEKUN LODE OBAYEBE IROSO OJUANI BATRUPON IFA OFO, OFO LAYE BENUN ARUN.", "REZO: ERINLA LELEYA ENISO OKO OKOLELE AWO AGBODE AFINISUN LENI KAEBOMBONGOBO NOOWI AHIKATE O SINTESIN XONIDA FUN AJE ALATESI LO NISE ASARIN KANKAN ARIBI MAMAYO WEN OFIWERE NAGBEBE LOWO WA A EJILOPA ADOMI FALOWINI IYAN YIMA NA OMO ANOGAJA IDI DAFE OMUDAWO OKO MADOPO OMONI TIOBON OMO ENI TIKO MOKA NIMON LIGOJINAPA NIBEN WAYE SU ONIYUBONA OMO KAMBE LONA OKO SHURURONMILE ASHAGUTAN MEYI NOGBE OMO ONI LE MATUKALE AFIGSA TOWO DAZARUN OKO NIMO FOMA FOMO ENRILOLO ADIFAFUN ORUNMILA MAFEREFUN OGGUN.", "REZO: BABA AWA YEIFA ABORI BODEKE OMO AWO ALARA WEWERE IFA AWO OMO ABONI EGGUN OBE KERELEI AWO OYEYE YEKUN INLE OBA ORO SHENSHE OKUN TLIRE IBA IBOYE ETI EGGUN OBARIE OZAIN TINSHARE IFA IROSO BATUTO IRE ABERI BOYE ELESE OZAIN IRE ABERIBOYE EGGUN OWE OMO ALARA IFA NI ORUN.", "REZO: MEKUA EIYE BURUKU ADIFAFUN BATUTO EKPA, ATEKUE, EWE BABARI, ATI IYARI EBANILODO MEJOUN ITA LENI META, LEKUA EBA AGBANIREO ADIFAFUN ABIKODUN ONI SHANGO ONILAGBABA LODAFUN ORUNMILA.", "REZO: ADIFAFUN SHANGO BOGBO ORISHA OLE OBATALA ODE AKASHO IASA IGI OMU LORDAFUN OBA, KAFEREFUN IBEYI OMO EDDUN.", "REZO: ADIFAFUN IROSO BATRUPON MALOLE AWO OSHUNBULARE ODO, OÑI, OSUN ARA, KAFEREFUN OSHUN LODAFUN ORUNMILA."]}]$q$::jsonb),
(88,'f6747f39666805a79209db1e0cbe60cb',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Òtúrá dice que hay cosas buenas para nosotros aunque no nos gusten: la persona tiene una tarea desagradable pero necesaria. Ifá le desea riqueza. Después de ofrendar no debe contar sus secretos. Hay algo que dejó a medias y debe retomarlo y terminarlo para enderezar su camino."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene que cumplir una obligación que no le gusta.", "Lo juzgan por una función cuyo propósito otros todavía no entienden (relato de la misión de Ìrosùn Òtúrá).", "Viene una oportunidad de dinero y le conviene ser discreto con sus planes."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fortuna, pareja e hijos que llegan en abundancia.", "Salir de un año de tiempos duros.", "Volver a la paz retomando lo abandonado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Abandonar a Ifá o lo que el destino le marcó.", "Contar los secretos después de la ofrenda.", "No dormir ni descansar y agotarse sin ver avances."]}, {"titulo": "Enseñanza principal", "texto": "Ifá guarda en el cielo el paquete que cada quien eligió; lo que hacemos aquí se va sumando a él. Si uno se aparta de lo que le tocó, la vida en la tierra no es fácil. Hay que regresar al punto donde se dejó el camino y empezar de nuevo."}, {"titulo": "Relatos reunidos", "puntos": ["Ìrosùn Òtúrá, enviado al mundo. Olódùmarè ofrendó para que la persona que mandara al mundo con un encargo no lo rechazara y pudiera hacer del mundo un lugar en paz. Ofreció dos jicoteas, hojas de ọgbọ̀ y 6,600 cauríes, y envió a Ìrosùn Òtúrá. Todos se quejaron de su mal carácter, pero Odùduwà dijo que lo había mandado por el bien de la humanidad y no lo cambiaría: él es quien hace que la gente reunida, después de un tiempo, se disperse y vuelva a sus casas.", "Ọ̀rúnmìlà y el año difícil. Ọ̀rúnmìlà se quejó de haber pasado todo un año de tiempos duros. Ofreció, y luego cantaba: '¿Dónde quedaron los malos ratos? El retoño del ñame trae fortuna, esposas e hijos en montones'.", "Ifákóládé abandona a Ifá. Ifákóládé era jefe Ẹlẹ́mọ̀ṣọ́ entre los sacerdotes desde hacía mucho, pero dejó a un lado a Ifá y no quiso ofrendar. Hizo todo lo humanamente posible y no veía progreso: no dormía, no descansaba y se agotó. Le dijeron que regresara a la línea de sus ancestros y retomara lo que había abandonado. Volvió a adorar a Ifá y la vida le fue cómoda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Olódùmarè: dos jicoteas, hojas de ọgbọ̀ y 6,600 cauríes.", "Si es babaláwo, ñame machacado para Ifá; si no, un ñame con su guía larga, de forma constante."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè y Odùduwà envían a Ìrosùn Òtúrá al mundo. Ifá guarda en el cielo el destino de cada quien."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Jicoteas, hojas de ọgbọ̀, ñame machacado, ñame con su retoño."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 88.1 (yorùbá): Ẹniburúkú-ni-ẹjoti-a-nyin-wọn: / a difá f'Olódumarè, / wọ̀n niki ó rúbọ / ki ẹnti o maa ran niṣé yi / ma le kọ iṣẹ naa. / Ki ayé le maa gun. / İjapá Méjì, ewé ogbọ̀ / ati egbẹtalélógbòn owó. / Ó gbọ̀ ó rú. / Wọ̀n bọ òrun rè. / Nigbati o rúbọ tán, / o wa ran Irosutúrá losi òde-ayé. / Àwọn aráyé ni: / İwà İrosutúrá ko sun wọn. / Odùduà ni: / Ire ni ọ̀un fiṣe s'ayé. / Nitorinaa òun / ko jẹ fi ẹlomiran rọ'po rẹ. / Ó ni: / Bi ẹgbẹ ba jọ bobapẹ wọn a tuka. / Bi qjà ba kun bobapẹ titi a tú. / Biibatiri bi pmo-èniyàn / ba jọ titi tii wọ̀n ko ba le tuka / lọ ilé won? / \"La gente mala dice que hay un día / en que nosotros los alabaremos\":", "REZO: IROSO TURARA NIBE AKANI IKANIJU OLODAFUN OGUN NIBATI OGGUN OLOSILE ORUNMILA KATE NIFA.", "REZO: IROSO TURARA NIBE AKANI IKANIJU OLODAFUN OGUN NIBATI OGGUN OLOSILE ORUNMILA KATE NIFA.", "REZO: ALA GORON GORO ADIFAFUN OÑI GUANCA GUANCA TINLLO OLLE OLA OFAMETAN AKUKO LEBO.", "REZO: IROSO TURA ALANGOROGORO ADIFAFUN OGGUN WAKA UMBATI INLE MIE ALAILUE MEYE KODENU ORITITI MODENU ADIFAFUN ADEYE ERAKO.", "REZO: ADIFAFUN OGGUN NIBE ASHARPONI IKAUYUN LODAFUN OGGUN ATEFA NIBATI OGGUN OFOSILA KAFETENI ORUNMILA OGGUN ALAGUEDE LODAFUN OBATALA.", "REZO: ADIFAFUN OGGUN NIBE ASHARPONI IKAUYUN LODAFUN OGGUN ATEFA NIBATI OGGUN OFOSILA KAFETENI ORUNMILA OGGUN ALAGUEDE LODAFUN OBATALA.", "REZO: IROSO TURA ALANGOROGORO ADIFAFUN OGGUN WAKA UMBATI INLE MIE ALAILUE MEYE KODENU ORITITI MODENU ADIFAFUN ADEYE ERAKO.", "REZO: ODO OGUE IROSO TUNIALARA INLE YEBU ESI MOWA ERU YENYE NI OKU OLOKUN LOBAKE OBA OKU ORUGBO ADE LEITOSHU OSHUN IYUMO IBU LOSA KEKE KAFEREFUN ORUNMILA.", "REZO: BABA IROSO TOLDA ADIFAFUN ESE IGUI, IROSO TOLDA OMO IROSUN OFEKEBA ODABAWE OKE OMO OFO ODABAWE OMO KEKE TIFE OLODAFUN OMO ODARA. LODAFUN OLOFIN, MAFEREFUN OLOFIN, KAFEREFUN OZAIN.", "REZO: IROSO BOMBO DIRE ADIFAFUN OLOFIN OPE KOMBE LOYU ADE OLOFE IGBA ADE OLOFIN, OGGUN OSHONA OSI LARA OPE NIFEDE MOWA BELE BELE ONIFON IYA IDE AWO PRIOMO TIFUN OLOFIN OPA- RASUN SOKUN SOFUN SHANGO OPA ORUN OPE LODAFUN SHANGO.", "REZO: ADIFAFUN OBATALA ABANILE OLAKORUN INLE ADIFAFUN OSHUN AMBOWA SHONSHON ILE OZAIN TIKERAN FAN ELEGBA OFO LERI OSHUN, SHANGO WANBEWANI OSHUN AMIGBO ANSORO ORUNMILA. LODAFUN ELEGBA, LODAFUN ORUNMILA."]}]$q$::jsonb),
(89,'00d50a4de4e742e8ca4b1eb684bbbc61',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ìrẹtẹ̀ habla de la iniciación en Ifá para asegurar el éxito y una larga vida. La persona debe seguir un camino más espiritual. Ifá le da la bendición de los hijos, con una ofrenda a Ifá y a Ọ̀ṣun juntos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere asumir liderazgo o profundizar en su práctica religiosa (relato de Ọ̀rúnmìlà iniciando en muchos lugares).", "Pregunta por una iniciación o por una vida larga.", "Quiere conservar el favor y el apoyo que ya tiene (relato de Ìrosùn e Ìrẹtẹ̀).", "Desea tener hijos (relato de Òpìnní)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Iniciar a muchas personas en todas partes.", "Vida larga; que la muerte y la enfermedad no lo alcancen.", "Hijos, riqueza, pareja y casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Muerte y enfermedad si se pierde el favor de Ọ̀rúnmìlà.", "Separar en la ofrenda lo que debe ir junto."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se pone en el polvo sagrado de Ifá se conserva: sobre el iyẹ̀-ìrosùn, Ọ̀rúnmìlà vive siempre. Y el que ofrece a Ifá y a Ọ̀ṣun en la misma jícara recibe sus bendiciones completas."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà, el que inicia. Le anunciaron a Ọ̀rúnmìlà que iniciaría a mucha gente por todo el mundo. Ofreció una gallina, hojas de tẹ̀tẹ̀ y 3,200 cauríes.", "Ìrosùn e Ìrẹtẹ̀. A los dos les pidieron una chiva y 20,000 cauríes para que Ọ̀rúnmìlà los siguiera favoreciendo y evitaran la muerte. Ofrecieron, y se dijo que sobre el iyẹ̀-ìrosùn Ọ̀rúnmìlà viviría siempre.", "Òpìnní, Ifá y Ọ̀ṣun. Òpìnní quería hijos y le dijeron que ofrendara a Ifá y a Ọ̀ṣun juntos. Lo hizo y le llegaron riquezas, esposas, hijos y casas.", "Òyígí, hijo de Ẹ̀là. Òyígí, hijo de Ẹ̀là en el cielo, preguntó si la vida le sería agradable. Le dijeron que la muerte nunca lo alcanzaría frente a Ẹ̀là. Ofreció y siguió ofrendando a Ifá. Cantaba: 'La muerte no alcanzará a Òyígí; Ẹ̀là la rechazó. La enfermedad no lo alcanzará; Ẹ̀là la rechazó'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: una gallina, hojas de tẹ̀tẹ̀ y 3,200 cauríes.", "Ìrosùn e Ìrẹtẹ̀: una chiva y 20,000 cauríes.", "Para hijos: una gallina, un pescado y aceite de palma, a Ifá y a Ọ̀ṣun en la misma jícara."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà inicia y protege. Ọ̀ṣun recibe junto con Ifá. Ẹ̀là aleja la muerte y la enfermedad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de tẹ̀tẹ̀ (Amaranthus hybridus), iyẹ̀-ìrosùn, gallina, pescado, aceite de palma, chiva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 89.1 (yorùbá): Irosù-Atẹ̀: / a difá fún Ọ̀rúnmìlà. / Wọ̀n ni: / Ọ̀rúnmìlà a maa tẹ̀ wọn / nibi gbogbo agbaka ayé. / Wọ̀n niki ó wa rúbọ: / Adiyẹ, ewé tètè ati egberindilógún owó / Ó gbọ̀ ó rú.", "Verso 89.2 (yorùbá): Àikú-ẹ̀gbọ̀n-Iwà, / a dífá fún İrosù, / a bu fún Ìrẹtẹ̀. / Wọ̀n niki Ìrosù pelu Ìrẹtẹ̀ wa rúbọ / ki Ọ̀rúnmìlà le ba wọ̀n rẹ. / Ki wọn ma baa kú. / Ewúrẹ ati egbàáwa owó li ebọ. / Wọ̀n gbọ̀ wọ̀n rú / Wọ̀n ni: / Orí lyẹ̀-Irosù ni / Ọ̀rúnmìlà yoo maa gbe. / La inmortalidad (larga vida) es la mayor / de las virtudes del buen carácter:", "REZO: IROSO UNKUEMI INTORI TUKA APARO, ATARE MOSAN, EWE ENATORI EYE APARO, ATARE META. AWADO TUYERE MORIN AYE KASHA GUE GUE SHERIN SHAYO KANSHA GUE GUE TERUKO OMODO TOBARINI.", "REZO: IROSO UNKUEMI INTORI TUKA APARO, ATARE MOSAN, EWE ENATORI EYE APARO, ATARE META. AWADO TUYERE MORIN AYE KASHA GUE GUE SHERIN SHAYO KANSHA GUE GUE TERUKO OMODO TOBARINI.", "REZO: OBI GUOBIRE GUENECU A FUN LEGUELEGUE QUOBIRE UMI LODAFUN CHANCHORE TINFERUN ALEGUI ADIE MERI OBI MERA OWO MEFA.", "REZO: IROSO ATE INTORI APENI NI UN POCAN APERIN APERE UN PERU OPERIN EPECUNCHA YA IOAPCUN ALLA UN BABALAWO LODAFUN NILLO CAN FUN ORUNMILA.", "REZO: IROSO ATE INTORI TUCA APARO MESA EWE ENA TORI APARE ATARE META AGUADO TULLERE MERA AYE CAN CHA GUE GUE CHERIN CHALLO NICHA GUE GUE TERU TO OMO DE TOBARINI COFINI CHIRE.", "REZO: ORI GUOBIRE GUENEKU AFUN FUN LEKELEKE GUOBIRE UMI IRE ODAFUN KANSHORE TIMFEREFUN ALEKI ADIE OBI MEFA OWO MEFA.", "REZO: IROSO UNKEMI APOKAN SHAYADE IFA LAYE OLOGDO IFA MERI EBBO SHOSHO MOYARE IFA MERI EBBO ACASHA ACASHA AWO", "AGUARERIADIE MOYARE ADIE ORUNLA IFACASHE MERI EBBO, ARUN OSHE MO- YARE OSHE AWO OSHE MERI EBBO, EBBO OGUNDA LERI ELLA, OGUNDAAGUA, EJA OGUNDA MARI EBBO EYORETE BABA EYE AWO LODE EYI RETE AGUA LODE, EYIRTE MOYARE MOYABE IFA AWO LODE BEIFA MARI EBBO OKAN SHOSHO OKANAYE AWO OKAN SHOSHO BEYEBI AWO LERI AGUA YEBE IFA MARI EBBO, ADIE MEYI OMI ILE IBU OKAN SHOLO. AGUIAJARA IFA LODE IBU OKAN MEYI, META, MENI, MARUN, MEFA, EYI EYO MESAN, MEGUA, MOKANLA, MEYILA, MERINLA, MARUNLA, MEDILOGUN AWO MEYERIFA ACASHA IFA MARI EBBO WANIRE IFA ODARA ORUNMILA ABEYI LORUN ABEYENIFA IROSO UNKEMI AYE YOKAN ADELE MENI, MARUN GUARA IFA OBINI ORISHA, ORUNMILA GUAGUEO MAYI LOGUA IFA ASHE BOSHIRE.", "REZO: IROSO ATE UNKEMI ONI OFOKU UNKEMI ONI KUERE OKUEMI OKUO BUOBODO EKUN EBAYEDE OMO KUE MADO AKUN SHADO OMABU OKUAMI OMO KUOROFA."]}]$q$::jsonb),
(90,'55b12d992bd953a04f0d6a6115606dc9',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Ọ̀ṣẹ́ habla de vencer las dificultades y de mejorar los negocios. Aplicar nuevas ideas, técnicas o conocimientos al trabajo trae el éxito. Hay detractores alrededor; después de la ofrenda lo verán disfrutar de sus beneficios sin poder hacer nada. Lo están poniendo a prueba y necesita la mente serena."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca una forma nueva de llevar su negocio o su trabajo (relato de Ọ̀ṣẹ́ y su Òṣù).", "Siente que otros le frenan y debe confirmar qué está pasando antes de culpar a alguien.", "Pregunta por sus hijos (relato de Ológbò)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vencer a los enemigos.", "Mejorar o renovar el negocio.", "Proteger a los hijos frente a quien quiere dañarlos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enemigos y críticos alrededor.", "Brujería o malas intenciones contra los hijos.", "Caer en una tentación que es trampa."]}, {"titulo": "Enseñanza principal", "texto": "Con calma y con la ofrenda se pasa la prueba. El huevo puesto a la orilla del camino es un cebo: lo que tienta puede ser una trampa, y lo mismo sirve para atrapar al enemigo."}, {"titulo": "Relatos reunidos", "puntos": ["El osù de Ọ̀ṣẹ́. Se oía el osù de Ọ̀ṣẹ́ sonando para saludar al pueblo, y la gente preguntaba qué hacía. El adivino dijo que Ọ̀ṣẹ́ estaba venciendo a sus enemigos y que andaría ocupado con su trabajo de adivinación. Ofreció una paloma, una rata, un pescado y 2,800 cauríes.", "La gata entre las brujas. Ológbò iba a parir a sus hijos frente a las brujas y preguntó si les pasaría algo. Ofrendó. Cuando las brujas tomaron a los recién nacidos para examinarlos uno por uno, ella gritó: '¡Es tabú, es una abominación!', y las brujas se los devolvieron.", "Ọ̀rúnmìlà en medio de las brujas. Ọ̀rúnmìlà estaba de pie y agachado en medio de las brujas. Le dijeron que sus enemigos ya habían visto la gallina que puso huevos a la entrada de su casa, y que recogiera esos huevos y se los ofreciera a ellos. Lo hizo y quedó a salvo. Cantaba: 'El huevo en el camino es una trampa; estamos acostumbrados a poner trampas'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀ṣẹ́: una paloma, una rata, un pescado y 2,800 cauríes.", "Para vencer a los enemigos: huevos de gallina; si cría gallinas y una pone, guardar esos huevos para la ofrenda."]}, {"titulo": "Relaciones espirituales", "texto": "Las brujas (ìyàmi) se apaciguan con la ofrenda correcta. Osù, el báculo de Ifá, anuncia la victoria."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Huevos de gallina, paloma, rata, pescado. Fruto de la palma bien germinado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 90.1 (yorùbá): A ngburo Osù-Ọ̀ṣẹ́ wọnranrankiwọn / A ni: kil'Ọ̀ṣẹ́ nṣe / ti a ngburo Osù rẹ̀ wọnranrankiwọn? / Wọ̀n ni: / Ọ̀ṣẹ́ ṣégun ọ̀tá rẹ̀. / Ọ̀ṣẹ́ r'awo ṣe. / A ni: Ifá maa r'awo ṣe. / Ẹbọ: Ẹyẹlé, eku, ẹja / ati egbèwá owó. / Ó gbọ̀ ó rú.", "REZO: IROSO SHE OLU YENYE ADIFAFUN AERE TINYO LAAUNYE OKAN AKUKO LEBO. OSHA KOLOFUN KITIFUN SHAWE ADIFAFUN ORUNMILA.", "REZO: IROSO SHE OLU YENYE ADIFAFUN AERE TINYO LAAUNYE OKAN AKUKO LEBO. OSHA KOLOFUN KITIFUN SHAWE ADIFAFUN ORUNMILA.", "REZO: IFA ODAFUN ORUMILA OLODAFUN OZAIN AIKORDIE YARACO AKOFA BIRUTA OMI INA EBEYE OWO.", "REZO: ORUNLLELLO ADIFAFUN AORE TINLO LOULLOO ECA EYELE LEBO OCHE COLOSUN QUITIFIN CHAGUE ADIFAFUN ORUMILA AURE LEBO EYELE EURE LEBO.", "IFANIRE IFANI KAFEREFUN YALORDE.", "SUYERE: IGUERE IGUERE IRAYO UN YERE EGGUN SITURE EGGUN BABA EGGUN.", "REZO: OLOFIN EDEYE OPOLIFO BANGA AWO OGBBON, OPE ODO EYIN EDIN IGUI INA, ARONI OZAIN ELOSOKENMOSHISE ORO IROJO ADI, LODAFUN OZAIN KAFEREFUN ORUNMILA.", "SUYERE: BANGA BONGO EWO NIFA, OPONIFA ASHE IFA.", "SUYERE: IGUERE IGUERE IRAYO UN YERE EGGUN SITURE EGGUN BABA EGGUN.", "REZO: OLOFIN EDEYE OPOLIFO BANGA AWO OGBBON, OPE ODO EYIN EDIN IGUI INA, ARONI OZAIN ELOSOKENMOSHISE ORO IROJO ADI, LODAFUN OZAIN KAFEREFUN ORUNMILA.", "SUYERE: BANGA BONGO EWO NIFA, OPONIFA ASHE IFA.", "REZO: IFA ADAFUN ORUNMILA, LODAFUN OZAIN ORUBO AKODIE YABAKO AKOFA BIRUTA ONI INA IFA KAFEREFUN YALORDE.", "REZO: IROSO SHE OLUYEYE ADIFAFUN AKORE OLUO YEKE TINLO LOAYO OKA EYELE LEBO. OSHE KOLOSUN NITIFIN KAWO. ADIFAFUN KUSHE INA OFO, OYU OFO ASHIRI IBODUN ORISHA, IBODUN IFA BELELE BEKE INLE. ADIFAFUN ORUNMILA, LODAFUN OLOKUN, EYELE LEBO.", "SUYERE DE LAS MECHAS: EWERE INAYE EGGUN SITURA EGGUN BABA EGGUN."]}]$q$::jsonb),
(91,'c6b4407a4f372f212728b6a40637bf9d',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Òfún habla de protegerse de las enfermedades para alcanzar la buena fortuna. La persona está gastando mucha energía en su relación de pareja o en su familia y eso está deteriorando sus negocios. Ifá dice que todo lo bueno llegará a sus manos, y le pide hacer una gran comida e invitar a mucha gente."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se esfuerza tanto en una relación que descuida el trabajo o el negocio.", "Tiene un riesgo de salud y no debe creerse invulnerable (relato del leopardo Ẹkùn y Ṣọ̀pọ̀nná).", "Busca recursos y bienestar después de una etapa de desgaste (relato de Ọ̀rúnmìlà y la buena fortuna)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una gran fortuna en camino.", "Regresar a salvo de un viaje de trabajo, con bendiciones.", "El perdón y la fortuna del Òrìṣà."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedades, como la que atacó al leopardo.", "Presumir y no completar la ofrenda.", "Enemigos que siguen sus pasos para hacerle daño."]}, {"titulo": "Enseñanza principal", "texto": "La ofrenda incompleta deja una puerta abierta: el leopardo presumió que nadie lo podía vencer, no cumplió todo, y la enfermedad lo atacó aunque no lo mató. Compartir la comida con muchos atrae las bendiciones."}, {"titulo": "Relatos reunidos", "puntos": ["El leopardo y Ṣọ̀pọ̀nná. Ifá consultó para Ẹkùn, el leopardo, y le pidió mucho aceite de palma en una olla de barro, maíz tostado y ẹkọ con agua en una jícara para que Ṣọ̀pọ̀nná no lo atacara. El leopardo no completó la ofrenda y presumió: 'No sé de nadie que se atreva a pelear conmigo'. El adivino dijo: 'Ṣọ̀pọ̀nná lo atacará, pero no podrá matarlo'.", "La fortuna de Ọ̀rúnmìlà. Le dijeron a Ọ̀rúnmìlà que una gran fortuna venía a su encuentro. Ofreció una paloma y 2,000 cauríes.", "Las sandalias de cáscara de plátano. Ọ̀rúnmìlà iba a trabajar a la ciudad de Òňjó y preguntó si le iría bien. Le dijeron que lo vigilarían pero que vencería, que regresaría con bendiciones, y que debía ofrendar completo. Con cáscara de plátano le prepararon una medicina y le dijeron que la usara como sandalias al volver. Sus enemigos, que habían seguido sus huellas a la ida, ya no pudieron encontrarlas al regreso. Cantaba: 'Cáscara de plátano, borra todo daño de mi camino'.", "Òpè y el banquete. Òpè, esclavo del Òrìṣà, debía hacer una gran ofrenda. Le pidieron carne de elefante y de caracol fritas juntas, y comida y bebida para un banquete con parientes y conocidos. Lo hizo y el Òrìṣà lo perdonó y le dio todas las buenas fortunas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ẹkùn: mucho aceite de palma en olla de barro, maíz tostado y ẹkọ con agua en una jícara.", "Ọ̀rúnmìlà: una paloma y 2,000 cauríes.", "Para el viaje: medicina con cáscara de plátano usada como sandalias al regresar.", "Òpè: carne de elefante y de caracol fritas juntas, y un banquete con mucha gente."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣọ̀pọ̀nná, deidad de la viruela, castiga al que presume. El Òrìṣà perdona a Òpè."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, maíz tostado, ẹkọ, cáscara de plátano, carne de caracol. Ante fiebres o erupciones en la piel, conviene ir al médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 91.1 (yorùbá): İrosù'fún, / Iro eji agbąka: / a difá f'Ẹkùn, / wọ̀n niki ó rúbọ / kiomari ijà Ṣọ̀pònná, / Ebọ: Opolopo epo ninu agbada, / ọkà ti a din, ẹkọ ti a fi omi fọ sinu igbá. / Ekùn gbọ̀ ó rúbọ sùgbọ̀n / ko rúbo pe. / Ó ni: / Ko daju bi okunrin kan / wa tiole tẹ òun lọjọ ijà. / Wọ̀n ni: / Ṣọ̀pònná a baa jà sùgbọ̀n ko le paa.", "Verso 91.2 (yorùbá): Irosù'fún, Omotitun ti o wa j'ayé. / Irosù'fún, A o wẹ orí omo-awo: / a difá f'Ọ̀rúnmìlà / Wọ̀n nì: / Ire nbowa lọna fún un. / Eyẹlé ati ẹgbàwá owó li ebọ. / Ó gbọ̀ ó rú. / Irosù'fún, / un recién nacido viene al mundo.", "REZO: IROSO FUN OSHU OPONI MINUMA AWADO ORILELE LORI APATA INBUJO NIBESHUBU INBELOTAN UNBE ELOPO BASHUBU INBE TARIFA ADIFAFUN OLUWO.", "REZO: ESHU OPINI ABEDO ORILLELE LORI APARTA IMBUJO NIBE CHUBU IMBELOTAN UMBE BANCUBU TARIFA ADIFAFUN OLUO CHIN ALLARE REMI ABO LEBO IMBILO GUO FIGE EYELE ADIE LEBO.", "REZO: IFA KAFEREFUN OZAIN Y OLUO POPO.", "+++ 119"]}]$q$::jsonb),
(92,'9fba75d8d7bc097b2051f1d966407f9d',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ogbè habla de brujería, hechizos o energías negativas que quitan la paz mental. La persona se envuelve con frecuencia en relaciones de pareja, amistad o trabajo que le nublan el juicio. Debe seguir el camino de sus ancestros, cuidar su carácter y no vengar los desaires."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está confundido por su pareja, sus amigos o sus compañeros.", "Siente un ambiente pesado y quiere recuperar la calma (relato de Ọlọ́fin Ọbẹlejẹ).", "Lo comparan con algo amargo o lo critican (relato de Olú Oge).", "Debe tomar en cuenta a sus ancestros y su carácter al decidir."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Sacar lo malo de la casa y regresar con bienestar.", "Abrir el camino a la riqueza y a la pareja.", "Tener seguidores y fama, como Jesús en el relato de Ifá."]}, {"titulo": "Ibi y advertencias", "puntos": ["Energías negativas en casa y en los caminos de acceso.", "Personas amargas o fuerte oposición de quienes lo rodean.", "Vengarse de un desaire: el que cobra hasta el último detalle termina llorando.", "Negarse a aceptar una réplica de lo que prestó."]}, {"titulo": "Enseñanza principal", "texto": "Si alguien le pide algo prestado y no puede devolver lo mismo pero ofrece algo igual, debe aceptarlo. La venganza se paga con dolor: Ogbè exigió su olla exacta, y Ọ̀wọ́nrín le cobró con la vida de su hija. Ifá pide autocontrol y sentido común en los momentos duros."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlófin barre lo malo al bosque. Tres adivinos consultaron para Ọlófin Ọbẹlẹjẹ, que despertó con vibraciones malignas. Le dijeron que barriera su casa y los caminos que llevaban a ella, ofreciera un chivo sobre la basura y lo llevara todo al bosque, con hojas de ọlọ̀wọ̀nràn sánsán: quien saca el mal al bosque regresa a casa con bienestar. Luego, para abrir el camino al dinero, dos palomas, una para su Orí; y para la pareja, dos gallinas, una también para Orí.", "Olú Oge, amargo como el jogbó. Ifá consultó para Olú Oge, que era tan amargo como las hojas de jogbó. Le marcaron tres gallos, 2,600 cauríes y hojas de jogbó para hacer medicina. La persona carece de paz o enfrenta mucha oposición de quienes la rodean.", "Jesús llama seguidores. El sacerdote de Jesús consultó para él cuando venía del cielo a la tierra y preguntó cómo tendría seguidores. Le pidieron quimbombó, y aunque llamaba, nadie venía. Entonces le marcaron sopa de quimbombó fresco y de quimbombó seco, ñame machacado y pudín de harina de ñame; debía ir a las afueras de la ciudad, hacer un camino recto hasta un cruce, levantar ahí una choza, ponerse un cinturón rojo y bailar y cantar invocando el espíritu de su padre. Lo hizo, dio de comer y beber, y se juntó mucha gente a verlo. Dos lo siguieron; los mostró a Ifá, que lo mandó repetir lo mismo al oeste, al norte y al sur de la ciudad, hasta reunir ocho. Ifá le dijo: 'Llamaste a muchos y vinieron pocos, pero se volverán grandes'. Y así fue.", "La olla de Ogbè y las cuentas de Ọ̀wọ́nrín. Ọ̀wọ́nrín plantó un cerezo y, para protegerlo de las cabras, le puso encima una olla sin fondo que le pidió prestada a Ogbè. El árbol creció a través de la olla. Cuando Ogbè la reclamó, Ọ̀wọ́nrín le explicó que sacarla era como tumbar el árbol, pero Ogbè insistió en su olla y no aceptó otra, así que el cerezo se cortó. Tiempo después, la hija de Ogbè iba a casarse y necesitaba unas cuentas al cuello; Ọ̀wọ́nrín, guardián de todas las cuentas, se las prestó. A los diecisiete días había que cortarlas, pero Ọ̀wọ́nrín no permitió que las cortaran: quería sus mismas cuentas, como Ogbè había querido su misma olla. Como no pasaban por los hombros de la muchacha, la decapitaron para sacarlas. Ogbè lloró amargamente y fue con sus babaláwos, pero ya era tarde."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Limpieza: barrer la casa y los caminos, un chivo sobre la basura y llevarlo todo al bosque, con hojas de ọlọ̀wọ̀nràn sánsán.", "Para el dinero: dos palomas, una para Orí. Para la pareja: dos gallinas, una para Orí.", "Olú Oge: tres gallos, 2,600 cauríes y hojas de jogbó.", "Para tener seguidores: quimbombó fresco y seco, ñame machacado y pudín de ñame, comida y bebida para la gente, cinturón rojo e invocación al padre en el cruce de caminos."]}, {"titulo": "Relaciones espirituales", "texto": "Orí recibe una parte de cada ofrenda. Los ancestros y el espíritu del padre se invocan para atraer seguidores."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ọlọ̀wọ̀nràn sánsán (Malvastrum coromandelianum) para sacar lo malo; hojas de jogbó (Hyptis) maceradas en agua con iyẹ̀-ìrosùn del signo, para beber. Quimbombó, ñame, cuentas, chivo, palomas, gallinas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 92.1 (yorùbá): Bonronyin awo Óde-Ido, / Ogorombi awo Óde-Esa, / Erigidúdú awo ilu Ṣakon: / a dífá f'Ọlofin Ọbẹlẹjẹ / i yi nba'bi sùn to nba'bi ji. / A niki o lọ gba ilè ilé rẹ / kiogba onà rẹ̀, / kiopa obúko lee, / Kiogbee los'ẹluju (Ôdàn). / O ni: / \"gẹgẹ a sin'bi r'ẹlùjù, / a ko're wa'lé\" / Ewé de'wé Ọlowonran-nṣan-ṣan, / Eni l'Aladé sin'bi r'ẹluju. / Ebọ li ònà ti Ajé: Eyẹlé Méjì, kiofi okan bẹ orí. / Ebọ li ònà ti aya: Abọ adiyẹ Méjì, kiofi okan bọ orí lẹhin ti o bati / fi öbúką ṣẹbą, Ewe Ọlowonran-nṣanṣan (gsẹkotu) niki ẹni çhun fi / gbalẹ ilé rẹ gẹgẹbi a ti wi loke.", "Verso 92.2 (yorùbá): Eṣú-perewe, / Egba-perewe: / a dífá f'Olú Oge / ti o koro l'ejẹ t'omọt'omọ, / a d'ewé Jogbó, aya Oge koro. / Ẹbọ: Akuko mẹta, egbẹtala owó / ati ewé Jogbó (ewuro) tiiṣe ewé Ifá.", "REZO: OJUANI SHOBI TABAKOYU BAIN BAIN IKU BAIN BAIN LOBATI ADIFAFUN O UN BABLAWO MEDILOGUN TINLODIFA ILE OLOFIN.", "SUYERE: OJUANI SHOBI KESHU BAWAO (3 VECES).", "REZO: OBECHEGUANIZAN BI ETI FRENA BOMO LORUMADIE MEYI (SI UD. NO HACE YO LO HAGO, HE OIDO LO QUE HA HABLADO).", "REZO: OJUANI SHOBE ECHUBA AUN AFECHE ECHUBA IFANI KAFEREFUN ESHU YALORDE ORE CORIRA MELLO ADIFAFUN AMERECO CORO AWOADRO ADUN LEBO AKUKO IKOKO ÑAMETI EBELLO OWO MELLO.", "REZO: OJUANI LOBE ECHUBA A UN AFECHUN ECHUBA OBE UNCHOGUE ADIE DAMILOGUO MOFE LENI CHEMICHIO AGADAGODO KOFINIGUA ARAGUA LORDAFUN ICA BALIDAMIÑO", "REZO: SHELESAN FESO YEBO OYU OFO OJUANI MAYURO ELEGBA SOBEÑAR FE SALAIÑA WAYONI MAYURO ELEGBA SOBEÑAR FE SALA IÑA WAYENI OFE OYU AYORALAN KELEKELE AYU OBARI ADA OBA IYA KALEN WORA INLE OBAN KELEKELE KELE BOBO UNU OYU OLOFIN ABAINILE ELEWORA UMBO ELEWARE EMU.", "REZO: OJUANI SHOBE ESHU FEKUN FESHI KOA FEKUN, IKU ABO ASHE KEKUN ONIYEKUN OBA OMO OLORUN ASHA GUIDI OFO OGGUN ORISHA IKULE ORUNMILA KOMADERE ESHU ELEGBARA KRUBO EWE OMA ESHU BELARIO INLE BOSHELE IÑA ENIFA OMOKA AWO ALAKOBE LARINFA OWUNKO TOBADE TIOKO BABA OWA WIO TOBABINU ESHU MASHE ILORO ABANIWA LODAFUN ORUNMILA."]}]$q$::jsonb),
(93,'33c8ac197fb69051f749628acbd899c6',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ọ̀yẹ̀kú pide ser precavido y cuidadoso en todo: actuar sin pensar trae consecuencias emocionales serias. Ifá marca platos de ẹ̀kuru blanco para los enemigos y anuncia riqueza al que ofrenda. Quien llega de fuera y produce bien en una casa no debe ser cortado cuando aparece algo raro."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tomando una decisión apresurada en una relación (relato de Yemowó y Ajanaa-Werepe).", "Va a ir al campo o de viaje y puede pasar por alto un riesgo concreto (relato de Kuterunbe).", "Se siente rodeado de adversarios y debe actuar con prudencia antes de pelear."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza en abundancia y una vida dulce como la miel.", "Un forastero que trae fortuna a la casa.", "Salvarse de la muerte por una falta si se ofrenda."]}, {"titulo": "Ibi y advertencias", "puntos": ["Infidelidad y sus consecuencias graves.", "Descuido en el trabajo o en el campo: lo que uno mismo produce puede hacerle daño.", "Recibir los frutos de alguien y luego querer deshacerse de él."]}, {"titulo": "Enseñanza principal", "texto": "El cauteloso puede hacer grandes cosas. Y a quien da frutos no se le corta a la primera rareza: Onígbò recogió cuentas y ropa de rey del árbol delgado, pero quiso tumbarlo cuando le brotó una cabeza, y la gente le pidió contenerse."}, {"titulo": "Relatos reunidos", "puntos": ["Yemowó y el amante. Ifá consultó para Òrìṣà-ńlá (Ọbàtálá) porque Yemowó, su esposa, iba al campo a serle infiel. Para no morir por su infidelidad, ella ofreció cuatro palomas, 8,000 cauríes y cuatro caracoles babosa. A Ajanaa-Werepe, el amante, también le pidieron tres chivos y 6,600 cauríes para salvarse de la muerte, y cumplió.", "Kuterunbe y las semillas. Le advirtieron a Kuterunbe, que iba a la granja de Àlorò para la fiesta anual, que si no tenía cuidado ese año las semillas de su campo podían matarlo. Le pidieron toda clase de semillas de la granja, siete gallos y 14,000 cauríes. Se negó.", "El ìrókò en el patio de Onígbò. Onígbò Asùnlólá se quejaba de no tener riqueza. Le pidieron ofrendar y le desearon fortuna. Ofreció, la riqueza le llegó a manos llenas y tuvo paz y alegría: su vida fue como si goteara miel, y el ìrókò de su patio floreció.", "El árbol delgado en casa de Onígbò. Un árbol delgado, forastero, llegó a vivir y a trabajar en casa de Onígbò. Empezó a producir riquezas, luego cuentas, luego lááràngúnkà, la tela brillante de los reyes, y Onígbò lo recogía todo feliz. Un día le brotó una cabeza, y Onígbò mandó cortarlo por esa rareza. La gente le reclamó: 'Recogiste todo lo bueno que te dio, ¿y ahora lo quieres tumbar? Contente, Onígbò'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Yemowó: cuatro palomas, 8,000 cauríes y cuatro caracoles babosa.", "El amante: tres chivos y 6,600 cauríes.", "Kuterunbe: toda clase de semillas de la granja, siete gallos y 14,000 cauríes.", "Para los enemigos: dos platos de ẹ̀kuru blanco y dos platos de ẹ̀kuru con aceite."]}, {"titulo": "Relaciones espirituales", "texto": "Òrìṣà-ńlá (Ọbàtálá) es el esposo ofendido. Olódùmarè renueva el mundo y da vida dulce a Onígbò."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀kuru blanco y ẹ̀kuru con aceite de palma, semillas de cultivo, palomas, caracoles babosa, chivos, gallos. El ìrókò como árbol de la riqueza."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 93.1 (yorùbá): AFU / Ṣipiṣipi-li-a-nri'gba-Ajé, / Dugbẹdugbẹ-li-a-nlu-a-gbee-Yẹba, / A kiilu agbee Yẹba / kiomadun kẹrẹdudu kẹrẹdudu: / a dífá f'Oriṣà-ńlá / nitori Yemowó tiiṣe lyàwó / rẹ ti nlos'oko lo d'oko. / Njẹ nitoripe kioma baafi / oko-dido pa omo-Oriṣà. / A niki ó rú: / eyẹlé mérin, egàárin owó, / ati igbin mérin. / Ó rúbọ. / Ifá yi kanna li o dá fún Ajanaa-Werepe / tiiṣe ale Yemowó. / A niki ó rú: / óbúkọ meta ati egbẹtaelọ̀gbọ̀n owó / ki oun ma baa kú. / Ó gbọ̀ ó rú.", "Verso 93.2 (yorùbá): Àjàlorun I kukuteku awo ẹba'no: / li o difá fún Kuterunbe / ńlọ s'oko Àlorò odùn / Won ni: / \"Bikobaṣoṣṣẹ ninu odún / yi ni irúgbìn oko rẹ maa paa\". / Ẹbọ: Gbogbo irúgbin oko, / akuko-adiyẹ méje / ati ẹgbàáje owó. / Ko rúbo.", "REZO: OJUANI YEKU ABORI BAWA ORIBASHE KAWO ORIBAWA IRE ASHEGUN OTA ELESE SHANGO MARILAYE NI ELEGBARA ORIKUALO OWO OGORO OBURI OBORI YEKU INLE EBEREN OGORO BAWA IFA KALEREN OJUANI YEKU.", "REZO: EMILLE OUNLO ILE EBIMPO FUNILLE OSHUN GUELE QUINLLAN OTAN MOCHIN GUERE ELLE GUN LORI COLORI PALERE MAGUE BINU.", "REZO: OKANA ANIE AITO BALE AJU ADIFAFUN ELEBO AUN ROIOLA AKUKO LEBO, CUCUTE CUCU ADIFAFUN IROSO EKUELE BO ICHU ADA ADIE LEBO.", "REZO: IFANIERE IFANI KAFEREFUN ESHU OCUNI ABUALESE AFOFO.", "REZO: ABORI BAWA ARIBASHE KAWE ORIBAWA IRE ASHEGUN OTA ELESE SHANGO MARILAYE NI ELEGBA ORUKUALE OMO OGOTO OBORI YEKUN INLE SHEREN OBROGAWA IFA KALERUN OJUANI YEKUN WATISHE AWO OZAIN IFA ORUN IFA SHANGO, IFA OZAIN, IFA KAFEREFUN YERETIRA WALU NI ELEGBARA OJUANI YEKUN.", "REZO: IFA NIRE IFA NI KAFEREFUN ESHU OKUNI ABUA LESE AFOFO."]}]$q$::jsonb),
(94,'4febfeb9539605e14339c53e8cf2dfc5',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ìwòrì dice que trabajar duro es la mejor medicina contra la pobreza. También da remedios para los males emocionales: la persona se siente aturdida, con pereza o decaída por falta de descanso espiritual, desarmonía y ansiedad. Ha trabajado mucho sin ver resultados; su riqueza depende de su paciencia y puede llegar en algo que los demás desprecian."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja mucho sin ver resultados y necesita paciencia y un plan más claro.", "Se siente cansado, ansioso o deprimido y necesita descanso; si sigue, ayuda profesional (relato de Ojugbebikan y su esposa).", "La comida está cara o escasa y buscan cómo mejorar (relato de la gente de Ìwòrì)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza para los que ofrendan juntos.", "Comida barata cuando la gente trabaja la tierra.", "Hijos.", "Que la pareja recupere la calma y el buen juicio."]}, {"titulo": "Ibi y advertencias", "puntos": ["Escasez y comida cara.", "Agotamiento, ansiedad y tristeza.", "Que la pareja pierda la razón."]}, {"titulo": "Enseñanza principal", "texto": "Solo el trabajo duro hace bajar la miseria. Los adivinos dieron azadones y machetes al pueblo de Ìwòrì y le dijeron: 'Vayan a trabajar la granja para que la comida esté barata'."}, {"titulo": "Relatos reunidos", "puntos": ["El pueblo de Ìwòrì y la comida cara. En el pueblo de Ìwòrì todo lo de comer estaba caro. Ofrecieron doscientos azadones, doscientos machetes, ratas, pescados y 20,000 cauríes. Luego el babaláwo les dijo a los hombres que tomaran esos azadones y machetes y fueran a trabajar la tierra, porque solo así baja la miseria.", "Ojugbebikan y su esposa. Ifá consultó para Ojugbebikan para que su esposa no enloqueciera, o para que recobrara la razón si ya la había perdido. Le marcaron cuatro caracoles babosa, 8,000 cauríes y medicina de Ifá.", "Ọ̀wọ́nrín, Ìwòrì y Aláfohùnfojúrí. Ifá consultó para tres: Ọ̀wọ́nrín, hijo de Aṣégilówó; Ìwòrì, hijo de Atàpólà; y Aláfohùnfojúrí. Preguntaron si serían ricos y les dijeron que, ofrendando, la pobreza se alejaría para siempre. Ofrecieron palomas y bastante dinero, y se hicieron ricos. Cantaban: '¡Tú serás rico igual que yo!'.", "El pene y el escroto. Cuando el pene y el escroto venían juntos del cielo a la tierra, se preguntaban cuál de los dos sería dueño de los hijos. A los dos les pidieron ofrendar para tener hijos, y cumplieron: los hijos son de los dos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que baje la comida: doscientos azadones, doscientos machetes, ratas, pescados y 20,000 cauríes.", "Para la pareja: cuatro caracoles babosa, 8,000 cauríes y medicina de Ifá.", "Para la riqueza: palomas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá premia el trabajo de la tierra. La ofrenda compartida entre varios trae riqueza para todos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Azadones, machetes, caracoles babosa, palomas. Ante tristeza o ansiedad persistentes, o si alguien pierde el juicio, conviene buscar también ayuda médica."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 94.1 (yorùbá): Iṣu wọ̀n, / epo wọ̀n, / àgbàdo wọ̀n, / ohungbogbo ti enu njẹ li o wọ̀n: / a difá fún wọ̀n l'ode Ìwòrì. / Wọn ni: / \"ohungbogbo ti wọ̀n / fún wọ̀n l'ode Ìwòrì yi, / ki wọ̀n wa rúbọ / ki ppọ le de fun wọ̀n\" / Ẹbọ: Igba okọ̀, igba àdá, / eku, eja ati egbàáwa owó. / Wọ̀n gbọ̀ wọ̀n rú. / Babaláwo niki gbogbo okunrin / ko ọkọ̀ ati àdá kiwọn maa re oko / lọ ṣiṣẹ ki opo le de. / Iṣẹ nüide ipónjú. / Los ñames eran caros, / el aceite de palma era caro, / el maíz era caro / y otros alimentos eran caros.", "Verso 94.2 (yorùbá): Wèrè-nṣe-ẹlẹyaka'de wọ̀n nrẹrin: / a daa f'Ojügbebikan, / a niki ó wa rúbo, / ki aya rẹ ma di wèrè, / biobati di wèrè ki o le sàn. / Ẹbọ: Igbín mẹrin, / ẹgbàárin owó ati ewé-Ifá.", "REZO: OJUANI TANSHELA OWARI OFORE OUN YOKO IGUERI AOFERE EYA OSHUN ADIFAFUN ORINI ESETA BAIN BAIN AWO OSHA OMI.", "REZO: IFE OJUANI TANSHELA IGUOTRI TANSHELLE ADAFUN FUN TIMBERU FORO FORO.", "REZO: OJUANI MUTI IWORI ADIFAFUN OLLOLLU TINLO ILE OLORUN ADIFAFUN ALLELLA GOGODOGO TILO ILE OLORUN AKUKO EBO.", "REZO: IFA BEBERI AWO OMO ONI ELEGBARA OBARALA ILE ELEGBARA WAWA NILASHE OMO ODO FEFELE ILE OBARA NI ILE GEYEBE OBA NILEKUN OBADIÑA ILE NI OTOKUN OBA NISHE AWARA LARUN NIBE SHE OZAIN IFA KAFEREFUN YEMAYA ELEGBARA.", "REZO: ADIFAFUN AYILA AWO OJUANI TANSHELA KOSI ENI UNTEFA MOINLE TOLE BALE LORIYE AFONYA AWO OTUN OKUA INLE ESHU DOKUN ORI OSHE LOGUN LO OSHE OGGUN IKUN BEROWI YANGUI IROLI BELELE ORI BORO LODAFUN EGGUN KAFERE FUN ELEGBA.", "SUYERE: MANGUI ORI ORUN EGGUN BELELE ESHU DOKUN EGGUN BELELE LORIYE.", "REZO: OJUANI TANSHELA AYENI NI IFA AWO LODE NI LORUN OJUANI ATANSHELA AWO NI LODE ATANSHELA MASAGUERE NI ELEGBA INTORI OGUBOGBO OMODE AWO ÑAÑARE NI IFA WANI ASHE ORUNMILA ÑADE WA NI ORUN AWANA SOKU ELEGBA OYU OZAIN FA ELEGBA ELELE INTORI INCAN BURUKU OMODE NI ORUNMILA OYU EREWA ODUDUWA OMONI SHANGO SHEGUE NI ELEGBA BELEL OWANI LORUN UN SORE ORUNMILA SHON SHON LAWA ELEGBA ILE OMI KA SAKUN LAYE ELEGBA ADAN MEYI OYU OZAIN ÑA DE WA NI ORUN ERWA ODUDUWA LAYE ELEGBA ADAN EYI OYU OZAIN ÑA DE WA NO ORUN ERWA ODUDUWA OKONI SHANGO.", "REZO: OELE LO SHEYIN GUMELE BENIN ARINOMIRIA BGEBA YA KERIN ADDURE SIN ADIFAFUN OKAN LENU IRUMELE OJUANI", "TANSHELA, WONTORUN BOWUAYE, ADIFAFUN OZAIN, EYELE TERUN BEWAYE, ADIFAFUN EGGUN ORUNA LALA TORUN WEWUAYE, ADIFAFUN ORISHA LAWATOMI TERUN BEWAYE, ADIFAFUN ORUNMILA TIKOLE ORUN BEWASITAYE BOGBO WON LERI ASHO BORA SHUGBON IJEJE NIAWEN NIGBATI WONDE BOGBO ELELOMO EGGUN DAKUN YAWANI DI NI BI ASHERO ALARAMBARA UN KAFIDEBORA UMBE ODER AYE DAFIBERA DELEAYE OSHA NI ADAKUN NISHERE BEBBE ORUNMILA BOSHE PIPE NISHERE KUESIBE ORUNMILA NANIBATISHE DEKUN KOFIYE ESHU BONU IYAMI BARASI KOFIYE DENU KOFIYE DE BOGBO ARA NIBATI EBE KOLAKOYU ATUN SEGALEMU IKUN TEMINU ELEYE MI KOYNA YENURE YADE ELEYE BENFO EYADE LOKEYA AGOGO NI IPORO ARAN NI IKIYA OKUGUGU ISHERI MOBE EYA ENUKOTO ORIN AWO LEBO SILENU ESETONA IYEBA ERO PO ERO FAORI MINI OBA MILOWO ELEYE.", "SUYERE: IYO NIYO, NIYO AWERENYIN IWORI FERE IFA, OJUANI FORE IFA OMONI TANSHELA ARE IFA.", "REZO: ADIFAFUN TANSHELA OLA ARISFENINI AFORAN FEFERAN ORUN OJURPO EGGUN ALABOP LE AWO EGGUN AUREFUN NO OBINI DUDU OKAN EBORA ABOKUE EGGUN ODARA OBA IKU AGBALAYE NI ORUN LALA EFUN LELE FEFERAN INLE LAYE EGGUN AWO ORUN OTANSHELA OBANISHE EGGUN LESE OLOFIN LESE ORUN OBASHE EGGUN ODARA IKU EGGUN MAFUN ORUN BELELE AWO ORUN OJUANI TANSHELA, LODAFUN OBA EGGUN, KAFEREFUN EGGUN OBINI EBBO AGBA INSHE OZAIN ODARA.", "REZO: OJUANI TANSHELA ADIFAFUN OLOFIN TIMBEME FOROFORO IKODIE EYELE EWENI AWO LEBO BOGBO EYELE."]}]$q$::jsonb),
(95,'6272936e683d61d90b28eb14a2f83663',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ìdí dice que la generosidad, la honestidad y la palabra cumplida son el secreto del éxito y del amor. Los negocios de la persona van a cambiar de mal a bien. Su pareja le dará muchos hijos y será respetada por muchos; por dentro llora mucho y debe acudir a Ifá con constancia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que mejore un negocio que va mal.", "Tiene algo que no es suyo o duda si devolverlo (relato de los cestos y bolsos).", "Le cuesta compartir o teme perder su posición (relato de la tortuga).", "Desea hijos y reconocimiento (relato de Àlúkúlàkà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Cambio de los negocios para bien.", "Ser querido y preferido por la gente.", "Muchos hijos y partos felices.", "Recuperar la riqueza perdida."]}, {"titulo": "Ibi y advertencias", "puntos": ["La tacañería: que todo se le voltee y lo destituyan.", "Quedarse con lo ajeno.", "Tristeza guardada."]}, {"titulo": "Enseñanza principal", "texto": "El que devuelve las cosas a su dueño siempre prospera. La tortuga dijo que no podía ser generosa, y por eso se le pidió una ofrenda grande de comida para compartir."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga que no quería dar. A Ọbahun Ìjàpá, la tortuga, le dijeron que fuera generosa para recibir bendiciones, y respondió que no podía. Le pidieron un paquete grande de nueces de kola, una cazuela grande de puré de ñame, otra de sopa, cuatro palomas y 2,000 cauríes, para que nada se le volteara en contra y no la quitaran de su puesto.", "Los cestos y los bolsos. A los cestos y a los bolsos les pidieron dos palomas y 2,400 cauríes para que la gente los prefiriera. Ofrecieron, y se declaró que todo el que entrega las cosas a su dueño siempre tendrá bienestar.", "Àlúkúlàkà y los partos. Àlúkúlàkà, otro nombre de Orò, se quejaba de no tener descendencia. Le pidieron ofrendar para tener muchos hijos y partos exitosos. Cumplió, y sus hijos se extendieron por todo el mundo; él cantaba: '¡Yo parí muchos niños!'.", "Oriri mòjò recupera su riqueza. Oriri mòjò había perdido sus riquezas y preguntó si volvería a tenerlas. Ofreció y recuperó dinero, pareja, hijos y casa, con paz. Cantaba: 'Oriri mòjò, ayúdame; Ifá, ayúdame; la riqueza que te pedí no la olvides'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La tortuga: un paquete grande de nueces de kola, una cazuela de puré de ñame, una cazuela de sopa, cuatro palomas y 2,000 cauríes.", "Para ser preferido: dos palomas y 2,400 cauríes.", "Para hijos y para recuperar la riqueza: la ofrenda que marque Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Orò (Àlúkúlàkà) da descendencia. Ifá devuelve lo perdido al que ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nueces de kola, puré de ñame, sopa, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 95.1 (yorùbá): “Ọ̀wọ́nrín-dímọwọ́, / Çwọ̀nrín-dimẹsẹ, / a niki o f'ohuntorẹ ki afẹfẹ / le maa f'ẹre wa'le\", / \"Ó ni òun ko f'ohuntorẹ\": / a dífá f'Obahun ljapá, / a niki o wa rúbo / ki òràn ipónjú ma baa de sii. / Ẹbọ: Egbirin Obi, / àràbà-iyán, / ikoko-obe, / ẹyẹlé mẹrin ati ẹgbàwá owó.", "Verso 95.2 (yorùbá): Gbadani-gbasibẹ, / Biababi'ni-kiaf'ohun-f'olohun, / Ire li aigba: / a difá f'Okẹ / a bu f'Apo. / A niki ẹnikoẹkan wọ̀n wa rúbọ / ki omo aráyé baa le maa feran wọn. / Eyẹlé Méjì, ati egbejilá owó. / Wọ̀n rúbọ. / Wọ̀n ni: / \"To abariwon, / ẹniti nfi ohun f'olohun / ko maa yee ni lowo\" / \"Cuida estas cosas, mantenlas a salvo\", / \"Si usted dice: / estas cosas son devueltas a sus dueños / cuando lo soliciten; / el bienestar es solvente / (tiene credibilidad, es serio)\":", "REZO: OJUANI NI SHIDI ARIRE LEPANI KOSOBO LEPANI ADIFAFUN AWO ASHELU TINSHOMO OLOJA.", "REZO: OGUANI SHIDI ORIABE BUA NI CORABATELE PUNI. ORUNMILA ADIFALLOCO LODAFUN ONI CHECHE COGUO NI ENRE OGUANI CHIDI IYORADE SANAYE.", "REZO: OWO ORU DEBO SOPALU ACOCHOCHO CABAMBU MAJU A ODAFUN OWO CHELLU TINCHOMA ALOLLA AKUKO LEBO ESHU. ORIDE FABICOSOBATOLE FANU.", "REZO: OJUANI NI SHIDI AGADA BEÑI KOTO LODAFUN POGO SIMELE LODENI.", "SUYERE: ARIN YANYA KIYA KINI LOMI SOGAREKEDE ARIN YANYA KIYA SHANGO LOGUE EYIRI ARIN YANYA KIYA.", "REZO: ADIFAFUN LODONI AWO INLE TOBARISHE OBONI LABOSURAYE OLUO POPO IKU UBOWANI OYU MOMO TORIMOLE OLUO POPO IFA KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN OSHUN, LONGO LONGO MARUN, AWORI ILE ORUNMILA KAFEREFUN EGGUN ORUNMILA.", "REZO: OJUANI ODDI SHIDI ODEKUTAN, ODE OMITAN ODE, ONA FUEMO, EWAWO EKA OKO ODE AYAIFA, LODAFUN ORUNMILA, ADIFAFUN OSHUN.", "SUYERE: ODE BIYAYE KUARA UMPRA YENUKUA SHONSBO SHARANNIYE"]}]$q$::jsonb),
(96,'849f6d56e83ef3dc395909aa27f68f55',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ìrosùn habla de la importancia de los sueños. La persona necesita acercarse a la energía de sus ancestros para desenredar dificultades pasajeras. Ifá le pide no ser malicioso para que las bendiciones no se alejen, y ofrendar para no morir antes de tiempo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tuvo un sueño que le dejó inquietud o esperanza y quiere entenderlo (relato de Ọlawunmi y la campana).", "Busca acercarse a su tradición familiar o a sus ancestros.", "Teme que un arranque de mal carácter termine en vergüenza pública."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un sueño bueno que anuncia honor y riqueza.", "Vida larga.", "Un buen matrimonio fuera de casa, con el cariño de la familia."]}, {"titulo": "Ibi y advertencias", "puntos": ["La malicia, que aleja las bendiciones.", "Muerte prematura si no se ofrenda.", "Ignorar lo que se sueña."]}, {"titulo": "Enseñanza principal", "texto": "Un sueño puede ser un mensaje: el que sueña con campanas de baile y una sonrisa debe consultar y ofrendar. Hay que tratar bien a los que uno quiere; así, cuando toque partir, la despedida es con bendición."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlawunmi y su sueño. Ọlawunmi soñó una noche y en la mañana mandó llamar a un babaláwo. Erinmuyẹ, el adivino de la buena fortuna, consultó, salió Ọ̀wọ́nrín Ìrosùn y le dijo: 'Anoche soñaste; oíste una campana de baile y viste a alguien sonriéndote. Fue un sueño muy bueno, por eso debes ofrendar'. Ofreció dos palomas, dos gallinas, dos paquetes de kola y 2,400 cauríes, y le rogaron la cabeza con una paloma. El adivino declaró que Ọlawunmi siempre sería una persona honorable; su nombre quiere decir 'la riqueza y el honor se tejen a mi alrededor'.", "Àkókó se va a casar. Àkókó, hija de la ciudad de Ìramòrí, iba a casarse en otra ciudad. Le pidieron ofrendar. Todos los que la querían lloraban porque no querían que se fuera, y ella también lloraba por lo bien que la habían tratado. Ofreció, se fue y le cantaron que abrazaría y cargaría en la espalda a todos sus hijos.", "Onítidi y la vida larga. Ifá consultó para un grupo de personas que ofrendaron para tener vida larga y no morir antes de tiempo; ofrecieron todo lo pedido y un chivo grande. Viven muchos años. 'Vemos a Onítidi, muy viejo y frágil, y vemos la vida.' Por eso a este signo también se le llama Ọ̀wọ́nrín Onítidi."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Por el sueño: dos palomas, dos gallinas, dos paquetes de kola y 2,400 cauríes; rogación de cabeza con una paloma.", "Para vida larga: un chivo grande con los demás artículos que marque Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Orí se ruega con paloma. Los ancestros ayudan a deshacer las dificultades."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nueces de kola, palomas, gallinas, chivo. Maíz con su estigma como cola de caballo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 96.1 (yorùbá): Erinmuyẹ awo Ire: / a dífá f'Olawunmi / nigbi Ọlawunmi sùn tiola ala. / Ojumo mọ, / o niki a pe Babaláwo / wa wo Ifá f'oun. / A lọ pe Erinmuyẹ awo Ire, o de. / A dá'fá lia ri Ọ̀wọ́nrín'rosù. / Ó wo titi o ni: / Ọlawunmi! / Sisùn li o sun tiola ala loru / nitori eyi lioṣe pe Babaláwo. / Loju ala o ngbọ iro agogo-ijó, / enikan nrẹrín si o. / Ala tiola ire ni. / Nitorinaa ki o rúbọ: / Eyẹlé Méjì, adiyẹ Méjì, / egbirin obi Méjì, / egbèjila owó. / Ó gbọ̀ ó ru. / A fi eyẹlé bọ orí fún un. / Wọ̀n ni: / Iwọ Ọlawunmi ko ni gbai lọla.", "REZO: OJUANI HERMOSO OGUN ATI ELEGBARA AWO NIFA LESE OLOFIN, ORUNMILA ATI SHANGO UMBO VARIYO ODARA NIGDARA OMO OLOFIN OFO LEITOSHU ARAYE LODAFUN ORUNMILA KAFEREFUN PINADO.", "REZO: AWOBO OWO ITANA ADIFAFUN ORUMILA UMBANTILO LOCADIE OBINI OCOSU OSE MEFA KAFEREFUN SHANGO.", "REZO: OJUANI IROSO DOSOMO KUELE KUELE LOYUMAMA KUELE KUELE ALALELE IGBA KUELE KIFO IFA AWO KUELE KUYA ADIFAFUN OSUADA TINSHOMA OLORDUMARE.", "REZO: OJUANI MOSUN DESUMU PELE LOYUMAMA PELE PELE PELE ALALELE IFA KUELE KIFE IFA AWO ITANA, AWO IKU BALOKU SHANGO ILEKE AIKORDIE AWO PELE PELE KIYA ADIFAFUN OSUN ADA ADIFAFUN ITANA LAU LAU TINSHOMO OLORDUMARE TALA EGOTUDE AGBADA OJUANI AMOSUN KALO AWO IKU OSHISHE ITANA MEYI IBO OKUETA KONOKE OBOSHEYEO ALAYE ADIFAFUN ORUNMILA ADIFAFUN EGGUN TIRE LEBO LELE SHANGO BOKU BOKU IBALOKUN BORIYEYE SHANGO AWO ITANA.", "REZO: OGGUN ATI ELEGBARA AWONIFA, LESE OLOFIN ORUNMILA, ATI SHANGO UMBOWARIYO ODARA NIGDARA OMO OLOFIN EFE LEITOSHU ARAYE LODAFUN ORUNMILA KAFEREFUN GUANADO.", "SUYERE: AGADA MOSARAO AGADA MOSARAO ORUNMILA LORDA OBBE AGADA MOSARAO.", "REZO: AWO IFA KANANILE KOFITO PARA OPOLOPO ENI UNYEN GUNUGU IFA BI ADE ITO AWO KISHE ITA UNLO SHO SHON ILE", "AWO AGBA KISHE ITABO ARUGBO AMODE NITA KISHE IFA OLOFIN ODE ORUN ITA ISHE ELEGBA LODAFUN EGGUN KAFEREFUN ORUNMILA.", "SUYERE: IFA LOLA ONA FUNI LASHE OJUANI HERMOSO GBOGBO AGBA EGGUN TORUN MAGBEN."]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
